//! Ephor: The overseer of your Zig code - Static + Dynamic analysis
//!
//! Output format: path:line:col: severity[rule-id]: message
//! Compatible with GCC, clang, ESLint, IntelliJ IDEA, VS Code
//!
//! Commands:
//! - orphans:    Files not imported from entry points
//! - memory:     Alloc without defer patterns
//! - errors:     Silent catch {} discards
//! - unused:     Unused imports and declarations
//! - complexity: Function complexity metrics
//! - fmt-check:  Files needing zig fmt (wrapper)
//! - stats:      Project metrics
//! - check:      Run all checks
//! - runtime:    Run tests with memory diagnostics
//! - init:       Create an ephor.json config file
//! - install:    Add ephor to a project's build.zig
//! - upgrade:    Update ephor to the latest version (alias: update)
//! - help:       Print help (-h, --help)
//! - version:    Print the version (--version, -v)

const std = @import("std");
const mem = std.mem;
const Allocator = mem.Allocator;

/// Compatibility layer for std.fs APIs removed in Zig 0.16.0.
/// The I/O handle arrives through cwd(): no file-scope global (EPH-I0771).
const Fs = struct {
    pub const max_path_bytes = std.Io.Dir.max_path_bytes;

    pub fn cwd(io: std.Io) CompatDir {
        return .{ .io = io };
    }

    pub const CompatDir = struct {
        io: std.Io,

        pub fn access(
            self: CompatDir,
            sub_path: []const u8,
            options: std.Io.Dir.AccessOptions,
        ) !void {
            return std.Io.Dir.cwd().access(self.io, sub_path, options);
        }
        pub fn openFile(
            self: CompatDir,
            sub_path: []const u8,
            options: std.Io.Dir.OpenFileOptions,
        ) !std.Io.File {
            return std.Io.Dir.cwd().openFile(self.io, sub_path, options);
        }
        pub fn openDir(
            self: CompatDir,
            sub_path: []const u8,
            options: std.Io.Dir.OpenOptions,
        ) !std.Io.Dir {
            return std.Io.Dir.cwd().openDir(self.io, sub_path, options);
        }
        pub fn readFileAlloc(
            self: CompatDir,
            allocator: Allocator,
            sub_path: []const u8,
            max_bytes: usize,
        ) ![]u8 {
            const limit: std.Io.Limit = .limited(max_bytes);
            return std.Io.Dir.cwd().readFileAlloc(self.io, sub_path, allocator, limit);
        }
        /// readFileAlloc with the final path component opened no-follow
        /// (RED4-7, EPH-I0210): the scan reads a file the walk recorded
        /// from its dirent kind, so a symlink swapped in between must fail
        /// the open instead of redirecting the read outside the tree. The
        /// bounded-read body mirrors std readFileAllocOptions (no
        /// follow_symlinks option exists there), and allow_directory=false
        /// fails a swapped directory at open instead of mid-read.
        pub fn readFileAllocNoFollow(
            self: CompatDir,
            allocator: Allocator,
            sub_path: []const u8,
            max_bytes: usize,
        ) std.Io.Dir.ReadFileAllocError![]u8 {
            var file = try std.Io.Dir.cwd().openFile(self.io, sub_path, .{
                .follow_symlinks = false,
                .allow_directory = false,
            });
            defer file.close(self.io);
            var file_reader = file.reader(self.io, &.{});
            const limit: std.Io.Limit = .limited(max_bytes);
            return file_reader.interface.allocRemainingAlignedSentinel(
                allocator,
                limit,
                .of(u8),
                null,
            ) catch |err| switch (err) {
                error.ReadFailed => return file_reader.err.?,
                error.OutOfMemory, error.StreamTooLong => |e| return e,
            };
        }
        pub fn createFile(
            self: CompatDir,
            sub_path: []const u8,
            flags: std.Io.Dir.CreateFileOptions,
        ) !std.Io.File {
            return std.Io.Dir.cwd().createFile(self.io, sub_path, flags);
        }
        pub fn statFile(self: CompatDir, sub_path: []const u8) !std.Io.Dir.Stat {
            return std.Io.Dir.cwd().statFile(self.io, sub_path, .{});
        }
        pub fn realpath(self: CompatDir, sub_path: []const u8, out_buffer: []u8) ![]u8 {
            const n = try std.Io.Dir.cwd().realPathFile(self.io, sub_path, out_buffer);
            return out_buffer[0..n];
        }
        pub fn realpathAlloc(self: CompatDir, allocator: Allocator, sub_path: []const u8) ![:0]u8 {
            return std.Io.Dir.cwd().realPathFileAlloc(self.io, sub_path, allocator);
        }
        pub fn writeFile(
            self: CompatDir,
            sub_path: []const u8,
            data: []const u8,
            flags: std.Io.Dir.CreateFileOptions,
        ) !void {
            const opts: std.Io.Dir.WriteFileOptions = .{
                .sub_path = sub_path,
                .data = data,
                .flags = flags,
            };
            return std.Io.Dir.cwd().writeFile(self.io, opts);
        }
    };
};

/// Spawn paths for the external tools ephor executes (EPH-I0154). main
/// resolves them once from the EPHOR_ZIG_PATH / EPHOR_CURL_PATH env
/// overrides, then through PATH to an absolute path (EPH-I0163): the
/// spawn names the resolved binary, never a per-spawn PATH lookup name.
/// The buffers back the resolved absolute paths, so no allocation is
/// needed at startup.
var tool_zig_path: []const u8 = "zig";
var tool_zig_buf: [Fs.max_path_bytes]u8 = undefined;
var tool_curl_path: []const u8 = "curl";
var tool_curl_buf: [Fs.max_path_bytes]u8 = undefined;

/// An external tool ephor spawns, for EPHOR_*_PATH resolution (EPH-I0154).
const ToolKind = enum {
    zig,
    curl,

    /// Env var that overrides the spawn path of this tool.
    fn envVar(self: ToolKind) []const u8 {
        return switch (self) {
            .zig => "EPHOR_ZIG_PATH",
            .curl => "EPHOR_CURL_PATH",
        };
    }

    /// argv[0] used when no valid override is set: the PATH lookup name.
    fn bareName(self: ToolKind) []const u8 {
        return switch (self) {
            .zig => "zig",
            .curl => "curl",
        };
    }
};

/// Resolve the spawn path of an external tool (EPH-I0154, EPH-I0163). An
/// absolute env override that exists and is not a directory wins. An
/// empty value counts as unset (EPH-I0314). Without a valid override the
/// bare name resolves through PATH to an ABSOLUTE path at startup
/// (EPH-I0163): the spawn then names the resolved binary instead of a
/// per-spawn PATH lookup name, so the executed tool is fixed at startup
/// and the subprocess boundary is deterministic. A PATH that yields no
/// match keeps the bare name: the late spawn then fails with the same
/// clear error as before. The fallback stays fail-open, not a hard
/// error: the threat is a hostile environment, which the operator
/// controls, and a path typo must not brick the run.
///
/// The check is a fast-fail convenience, not a security gate (EPH-I0312):
/// it validates existence and not-a-directory only. Executability is not
/// checked — Windows ignores the access() options entirely (std Io
/// Threaded.zig dirAccessWindows), so an X_OK gate would be a silent no-op
/// there, and the exec at spawn time is the authoritative gate. The gap
/// between this check and the late spawn is a TOCTOU window (std documents
/// the same race for access()); it is accepted because the environment is
/// operator-controlled and a swapped path fails at spawn with a clear
/// error.
fn resolveToolFromEnv(
    diag: *DiagCtx,
    tool: ToolKind,
    env_val: ?[]const u8,
    path_env: ?[]const u8,
) []const u8 {
    const buf = switch (tool) {
        .zig => &tool_zig_buf,
        .curl => &tool_curl_buf,
    };
    const val = env_val orelse return resolveToolFromPath(diag, tool, buf, path_env);
    // An empty override is not an override: treat it as unset, silently
    // (EPH-I0314). The pre-fix warning called it "not an absolute path".
    if (val.len == 0) return resolveToolFromPath(diag, tool, buf, path_env);
    if (!std.fs.path.isAbsolute(val)) {
        cliDiag(
            diag,
            "warning: ignoring {s} value '{s}' (not an absolute path). Using PATH.\n",
            .{ tool.envVar(), val },
        );
        return resolveToolFromPath(diag, tool, buf, path_env);
    }
    // statFile subsumes the existence check: it resolves the path and
    // reports the kind in one call. A directory would fail confusingly at
    // the late spawn, so reject it here (EPH-I0312).
    const st = std.Io.Dir.cwd().statFile(diag.io, val, .{}) catch {
        cliDiag(
            diag,
            "warning: {s} path '{s}' does not resolve. Using PATH.\n",
            .{ tool.envVar(), val },
        );
        return resolveToolFromPath(diag, tool, buf, path_env);
    };
    if (st.kind == .directory) {
        cliDiag(
            diag,
            "warning: {s} path '{s}' is a directory. Using PATH.\n",
            .{ tool.envVar(), val },
        );
        return resolveToolFromPath(diag, tool, buf, path_env);
    }
    return val;
}

/// Resolve the bare tool name through PATH to an absolute path
/// (EPH-I0163). The first PATH entry whose dir/name resolves as an
/// existing non-directory wins; the name gets a ".exe" suffix on
/// Windows, where the PATH entries hold extensionless names. An empty
/// PATH entry (including the empty-list shape) and an unresolvable
/// candidate skip silently — PATH conventions are per-platform, and the
/// bare-name fallback keeps the pre-fix spawn failure for a tool no
/// PATH entry names. The resolved path lands in `buf`, which backs
/// tool_zig_path / tool_curl_path for the whole run.
fn resolveToolFromPath(
    diag: *DiagCtx,
    tool: ToolKind,
    buf: *[Fs.max_path_bytes]u8,
    path_env: ?[]const u8,
) []const u8 {
    const name = tool.bareName();
    const path_list = path_env orelse return name;
    const exe_suffix: []const u8 = if (@import("builtin").os.tag == .windows) ".exe" else "";
    var iter = mem.splitScalar(u8, path_list, std.fs.path.delimiter);
    while (iter.next()) |dir| {
        if (dir.len == 0) continue;
        const candidate = std.fmt.bufPrint(buf, "{s}/{s}{s}", .{ dir, name, exe_suffix }) catch
            continue;
        const st = std.Io.Dir.cwd().statFile(diag.io, candidate, .{}) catch continue;
        if (st.kind == .directory) continue;
        return candidate;
    }
    return name;
}

/// Resolve every tool spawn path once from the process environment.
fn initToolPaths(diag: *DiagCtx, environ_map: *const std.process.Environ.Map) void {
    const path_env = environ_map.get("PATH");
    tool_zig_path = resolveToolFromEnv(diag, .zig, environ_map.get("EPHOR_ZIG_PATH"), path_env);
    tool_curl_path = resolveToolFromEnv(diag, .curl, environ_map.get("EPHOR_CURL_PATH"), path_env);
}

/// Diagnostics and I/O context for one ephor run (EPH-I0771). Replaces the
/// file-scope test-hook globals, including the pre-refactor global_io.?
/// unwrap convention (band-B00 F4, EPH-I0313): io is a required field, so
/// a context without an I/O handle cannot exist and no set-before-use
/// ordering can panic. Production main constructs one instance at startup
/// and threads it. Tests construct a fresh instance per test and assert on
/// the fields directly. No restore-at-exit and no canary: a per-instance
/// value cannot leak across tests by construction.
///
/// cliDiag's output sink (EPH-I1051): the formatted message goes through
/// writeFn when a DiagCtx carries a sink. The default (null sink) writes
/// via std.debug.print to raw stderr — byte-identical with pre-sink
/// output, because the sink path's fixed-buffer format only runs when a
/// sink is installed. Tests install a per-test capture sink and assert on
/// the diagnostics in-process (the EPH-I0314 warning-absence seam).
const DiagSink = struct {
    /// Sink state (a test capture struct; null-context fns ignore it).
    ctx: *anyopaque,
    /// Writes one formatted diagnostic message.
    writeFn: *const fn (ctx: *anyopaque, msg: []const u8) void,
};

const DiagCtx = struct {
    /// I/O handle for child-process and file operations.
    io: std.Io,
    /// Mutes cliDiag when false. The mute does not change the test-runner
    /// verdict: the verdict derives from TestResults counts only (fail,
    /// crash, timeout, leak, log_err). cliDiag writes via std.debug.print
    /// to raw stderr (or through diag_sink when one is installed), which
    /// the runner echoes into the gate log on success (build_runner "no
    /// matter the result") but never counts against the step. Error-path
    /// tests mute parse diagnostics and assert on the resulting state;
    /// the mute keeps that echoed stderr quiet.
    cli_diagnostics_enabled: bool = true,
    /// JSON output mode (--format=json): the shared stderr stream carries
    /// the machine JSON guarantee, so human diagnostics must not reach it
    /// (EPH-I0213). A pre-scan of argv arms this before the config load;
    /// parseSimpleFlag sets it when the format flag parses. Once armed the
    /// latch stays on for the whole run, even when a later --format=text
    /// switches the output format back.
    json_stream: bool = false,
    /// Injectable diagnostic sink (EPH-I1051): cliDiag routes the
    /// formatted message here when set. Null keeps the default
    /// std.debug.print stderr path byte-identical (the fixed-buffer
    /// format runs only when a sink is installed). The json_stream and
    /// cli_diagnostics_enabled latches gate the sink exactly like the
    /// default path, so the JSON machine guarantee stays pure.
    diag_sink: ?DiagSink = null,
    /// Errno-style detail for error.InvalidFailOnValue /
    /// error.InvalidStrictValue out of config parsing: the parse layer
    /// cannot know which ephor.json it is reading, so it stashes the
    /// offending value here and the catch-site (which knows the path)
    /// prints. Owned copy in a fixed buffer (B13-17): the config content
    /// buffer the value aliases is freed right after the catch, so a
    /// borrowed slice would dangle one refactor later. Truncation at the
    /// buffer bound is fine for a diagnostic.
    last_bad_gate_value: [bad_gate_value_buf_bytes]u8 = undefined,
    last_bad_gate_value_len: usize = 0,
    /// Last diagnostic muted by the machine latch (EPH-I1067): when
    /// json_stream is armed, cliDiag never prints, so the abort path
    /// renders the last stashed message inside the machine error object
    /// instead of losing it. Owned copy in a fixed buffer (the
    /// last_bad_gate_value policy): the message may alias a buffer that
    /// frees right after the call. Truncation at the buffer bound is
    /// fine for a diagnostic.
    last_muted_diag: [diag_msg_buf_bytes]u8 = undefined,
    last_muted_diag_len: usize = 0,
    /// True once an "error:" diagnostic printed this run (EPH-I0728).
    /// errorExitCode consults the latch: a failure whose cause already
    /// printed must not repeat as the runtime's bare error line, so the
    /// exit code returns silently instead. Set by cliDiag on the printed
    /// or stashed message, never by any other channel.
    error_diag_printed: bool = false,
    /// "ignoring suppression/gate keys from untrusted" notes printed. One
    /// per offending config file.
    untrusted_config_note_count: usize = 0,
    /// "trusting config at" notes printed (RED3-4, EPH-I0209). One per
    /// trusted config file whose directory covers the scan target.
    trusted_config_note_count: usize = 0,
    /// "two configs loaded" notes printed (EPH-I0076). One per run, when
    /// the cwd config and a target-side config both loaded.
    dual_config_note_count: usize = 0,
    /// "honoring N entries ... as reachability hints" notes printed
    /// (RED3-10, EPH-I0170). One per untrusted config file that contributed
    /// surviving entries.
    untrusted_entries_hint_note_count: usize = 0,
    /// Error-naming convention disclosure notes (RED3-9, EPH-I0169). One
    /// per run, when the applied convention came from a config at or
    /// inside the scan target.
    error_naming_note_count: usize = 0,
    /// Config read failures that are not a missing file (B13-9, EPH-I0517):
    /// an unreadable or oversized config must never silently read as "no
    /// config here".
    unreadable_config_warn_count: usize = 0,
    /// Rejected config path_dir values.
    path_dir_reject_count: usize = 0,
    /// Entries dropped by the EPH-I0195 containment gates (untrusted config
    /// entries, target-tree build.zig extraction).
    entries_reject_count: usize = 0,
    /// Outside-root entry notes printed. The gates print one note per
    /// config file or per extraction run, never per entry.
    entries_reject_note_count: usize = 0,
    /// "CLI --entry values kept alongside target entries" notes
    /// (EPH-I0201). One per run, when a dir-target switch keeps the
    /// explicit CLI entries and a target source contributes entries
    /// alongside them.
    cli_entries_note_count: usize = 0,
    /// zig fmt output lines the EPH-I0197 safety gates rejected (hostile
    /// bytes, outside-root paths).
    fmt_reject_count: usize = 0,
    /// Threshold values clamped at the documented maxima.
    threshold_clamp_count: usize = 0,
    /// Config threshold values that do not parse as a positive integer
    /// (B13-11, EPH-I0518): a mistyped huge value reverting to the default
    /// silently was the pre-fix behavior.
    threshold_invalid_count: usize = 0,
    /// Suppression-accounting notes printed.
    suppression_note_count: usize = 0,
    /// ".ephor-ignore auto-load" notes. The explicit --known-issues path
    /// stays silent by design (the user asked for it).
    known_issues_autoload_count: usize = 0,
    /// Refused untrusted .ephor-ignore auto-loads.
    untrusted_ignore_skip_count: usize = 0,
    /// AST-tier skip notes (EPH-I0200).
    ast_skip_note_count: usize = 0,
    /// Depth-cap truncation notes (EPH-I0667, trust-model F-5). One note
    /// per run, the first time any directory-depth cap truncates a subtree.
    depth_cap_note_count: usize = 0,
    /// Entries-widen-scan notes (EPH-I0784).
    entries_widen_note_count: usize = 0,
    /// Resident-content budget for the corpus warning (EPH-I0199). Real
    /// monorepos sit far below 1 GiB of Zig source. Hostile amplification
    /// (thousands of near-10 MB files) crosses it. A field, not a const, so
    /// tests can shrink it on their own instance.
    corpus_bytes_warn_threshold: usize = 1024 * 1024 * 1024,
    /// Corpus-bytes warnings. Also the once-per-run guard: the warning is
    /// edge-triggered, so a nonzero value means it already fired.
    corpus_warn_count: usize = 0,
};

/// Test seam: a fresh diagnostics context on the testing I/O (EPH-I0771).
/// Every test that touches the diagnostics surface constructs its own and
/// asserts on its fields. Nothing is shared, so nothing needs restoring.
fn testDiagCtx() DiagCtx {
    return .{ .io = std.testing.io };
}

/// Read cap for Zig SOURCE files (EPH-I0150): the import graph's per-file
/// content read (analyzeFile) and the export path's snippet re-read
/// (writeCodeSnippet) share this one cap, so a file the graph skipped can
/// never re-enter through the snippet path. 10 MiB sits far past real
/// source files (ZA702's exceptional-file threshold defaults to 50 KB)
/// and bounds the resident corpus the graph holds (EPH-I0199). std's
/// limited read trips when the cap is reached, so a file at or over the
/// cap is recorded in ImportGraph.skipped_files and reported as ZA502
/// instead of vanishing silently.
///
/// The other read caps are different classes and stay separate: config
/// files read at 64 KiB, build.zig reads at 512 KiB (integration update)
/// and 1 MiB (entry extraction, init path detection, init patching) by
/// call site, the known-issues list at 10 MiB, and the runtime capture
/// limits (10 MiB test output, 1 MiB ast-check output) bound child
/// processes, not source reads. Build-path ref scans share this cap
/// (band-B03 F21, EPH-I0376).
const max_source_file_bytes = 10 * 1024 * 1024;

/// Cap on the stashed invalid CI-gate value (B13-17). The longest valid
/// fail_on value is 7 bytes ("warning"); 64 bytes leaves room for a
/// malformed token worth naming in the diagnostic.
const bad_gate_value_buf_bytes = 64;

/// Cap on one formatted cliDiag message for the sink path (EPH-I1051).
/// The default stderr path never formats (std.debug.print direct), so
/// the cap bounds only sink-bearing runs, which tests install. The
/// largest production messages are a path (<= Fs.max_path_bytes) plus
/// under 1 KiB of static text; 8 KiB covers every production class. An
/// over-cap message keeps its head — the diagnostic prefix — by the
/// same truncation policy as the stashBadGateValue clamp (B13-17).
const diag_msg_buf_bytes = 8192;

/// Latch the printed-error flag for error-keyword messages (EPH-I0728):
/// errorExitCode reads the latch to keep one error line per failure. The
/// comptime prefix check makes the branch vanish for every non-error
/// message, and the branch lives here so cliDiag keeps its complexity
/// budget.
fn latchErrorDiag(diag: *DiagCtx, comptime fmt: []const u8) void {
    if (comptime mem.startsWith(u8, fmt, "error: ")) diag.error_diag_printed = true;
}

/// Unarm the printed-error latch after an error line the run survives
/// (EPH-I1161). errorExitCode skips the runtime's bare error line only
/// when the latch names the failure it is about to return, so a line
/// printed for a failure the run survives (the fmt band's cannot-run
/// line, the export failure line) must not keep the latch armed: a
/// later unrelated failure would then exit silently with the surviving
/// line naming the wrong one. The helper lives beside latchErrorDiag so
/// the pair's guarantee stays visible.
fn unlatchErrorDiag(diag: *DiagCtx) void {
    diag.error_diag_printed = false;
}

/// Print a CLI/config diagnostic unless the run has muted the channel or
/// the output stream is the JSON machine guarantee (EPH-I0213). With a
/// sink installed (EPH-I1051) the message formats once into a fixed
/// buffer and goes through the sink; without one the call passes
/// straight to std.debug.print, so production output is byte-identical
/// with the pre-sink code.
fn cliDiag(diag: *DiagCtx, comptime fmt: []const u8, args: anytype) void {
    if (!diag.cli_diagnostics_enabled) return;
    // An error-keyword message latches the printed-error flag for
    // errorExitCode's one-line-per-failure guarantee (EPH-I0728). The
    // branch lives in the helper so cliDiag keeps its complexity budget.
    latchErrorDiag(diag, fmt);
    if (diag.json_stream) {
        // The machine latch mutes the message, but the abort path must
        // still carry it: stash the formatted text (EPH-I1067). The
        // fixed buffer keeps the head on over-cap, the sink path's
        // truncation policy.
        var stash_buf: [diag_msg_buf_bytes]u8 = undefined;
        var stash_writer: std.Io.Writer = .fixed(&stash_buf);
        stash_writer.print(fmt, args) catch |err| switch (err) {
            error.WriteFailed => {},
        };
        const stash_msg = stash_writer.buffered();
        @memcpy(diag.last_muted_diag[0..stash_msg.len], stash_msg);
        diag.last_muted_diag_len = stash_msg.len;
        return;
    }
    const sink = diag.diag_sink orelse {
        std.debug.print(fmt, args);
        return;
    };
    var buf: [diag_msg_buf_bytes]u8 = undefined;
    var w: std.Io.Writer = .fixed(&buf);
    w.print(fmt, args) catch |err| switch (err) {
        // Over-cap truncation keeps the head: the diagnostic prefix
        // survives (the stashBadGateValue clamp is the same policy).
        error.WriteFailed => {},
    };
    sink.writeFn(sink.ctx, w.buffered());
}

/// Test capture sink for cliDiag (EPH-I1051): install on a DiagCtx, run
/// the code under test, assert on the captured bytes in-process. The
/// buffer is sized for the diagnostics the pins emit; an over-cap write
/// keeps the truncated head and sets `truncated`, so the test's content
/// assertions still fail loudly on the missing tail.
const CaptureSink = struct {
    buf: [512]u8 = undefined,
    len: usize = 0,
    /// Set when a diagnostic did not fit the capture (a future test's
    /// message outgrew the buffer).
    truncated: bool = false,

    fn sink(self: *CaptureSink) DiagSink {
        return .{ .ctx = self, .writeFn = CaptureSink.write };
    }

    fn slice(self: *const CaptureSink) []const u8 {
        return self.buf[0..self.len];
    }

    fn write(ctx: *anyopaque, msg: []const u8) void {
        const self: *CaptureSink = @ptrCast(@alignCast(ctx));
        const n = @min(msg.len, self.buf.len - self.len);
        if (n < msg.len) self.truncated = true;
        @memcpy(self.buf[self.len .. self.len + n], msg[0..n]);
        self.len += n;
    }
};

test "cliDiag routes through the sink; the latches still gate it (EPH-I1051)" {
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    cliDiag(&diag, "note: {s} {d}\n", .{ "alpha", 3 });
    try std.testing.expectEqualStrings("note: alpha 3\n", capture.slice());
    // json_stream: the machine guarantee stays pure — the latch gates the
    // sink exactly like the default stderr path (B56 gate guarantee).
    diag.json_stream = true;
    cliDiag(&diag, "machine\n", .{});
    try std.testing.expectEqual(@as(usize, 14), capture.len);
    // The mute gates the sink too.
    diag.json_stream = false;
    diag.cli_diagnostics_enabled = false;
    cliDiag(&diag, "muted\n", .{});
    try std.testing.expectEqual(@as(usize, 14), capture.len);
}

test "cliDiag over-cap format keeps the head and sets the sink truncated latch (EPH-I1051)" {
    // The >8192-byte format output trips the cliDiag fixed buffer's
    // WriteFailed, the head-preserving truncation at the catch site
    // (the policy the previous tests never pinned); the 8192-byte head
    // then overflows the 512-byte capture, which keeps its own truncated
    // head and sets the latch. Both truncations preserve the diagnostic
    // prefix, so the assertion pins the delivered head byte-for-byte:
    // "note: " plus the first 506 argument bytes (512 minus the prefix).
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    const long_arg = "x" ** (diag_msg_buf_bytes + 808);
    cliDiag(&diag, "note: {s}\n", .{long_arg});
    try std.testing.expect(capture.truncated);
    try std.testing.expectEqual(@as(usize, 512), capture.len);
    try std.testing.expectEqualStrings(
        "note: " ++ long_arg[0 .. 512 - "note: ".len],
        capture.slice(),
    );
}

