/// `list-tests` command: static test discovery over the scanned path. The
/// count is the gate's cross-check twin for the zig runner's test total
/// (EPH-I1088). No diagnostics print between the listing and the footer
/// line, so the JSON stream stays a single machine document.
fn handleListTests(ctx: *RunCtx) !void {
    var g = ImportGraph.init(ctx.alloc, ctx.diag);
    defer g.deinit();
    g.scan_root = ctx.base_path;
    try scanPath(&g, ctx.cfg.path);
    requireScannedFiles(ctx, &g);
    if (ctx.should_exit_error) return;
    var blocks = try collectTestBlocks(ctx.alloc, &g);
    defer blocks.deinit(ctx.alloc);
    printTestListing(ctx.alloc, blocks.items, ctx.cfg.format);
}

/// Print the discovery listing: one `file:line test "name"` per block in
/// text mode, a machine object in JSON mode. The final text line carries
/// the count the gate cross-checks against the runner's total.
fn printTestListing(
    allocator: Allocator,
    blocks: []const TestBlockInfo,
    format: OutputFormat,
) void {
    if (format == .json) {
        var obj = types.OutBuf{ .allocator = allocator };
        defer obj.deinit();
        buildTestListingJson(&obj, allocator, blocks) catch return;
        std.debug.print("{s}", .{obj.buf.items});
        return;
    }
    for (blocks) |b| {
        std.debug.print("{s}:{d} test \"{s}\"\n", .{ b.file, b.line, b.name });
    }
    std.debug.print(
        "{d} test block{s} found\n",
        .{ blocks.len, if (blocks.len == 1) "" else "s" },
    );
}

/// Render the list-tests machine object: file, line, and name per block
/// plus the count. File and name cross escapeJson (repo-derived fields,
/// EPH-I0146); the line and the count are plain integers.
fn buildTestListingJson(
    obj: *types.OutBuf,
    allocator: Allocator,
    blocks: []const TestBlockInfo,
) !void {
    try obj.buf.appendSlice(allocator, "{\"tests\":[");
    for (blocks, 0..) |b, i| {
        if (i > 0) try obj.buf.appendSlice(allocator, ",");
        var file = try types.escapeJson(allocator, b.file);
        defer file.deinit(allocator);
        var name = try types.escapeJson(allocator, b.name);
        defer name.deinit(allocator);
        try obj.buf.print(
            allocator,
            "{{\"file\":\"{s}\",\"line\":{d},\"name\":\"{s}\"}}",
            .{ file.slice, b.line, name.slice },
        );
    }
    try obj.buf.print(allocator, "],\"count\":{d}}}\n", .{blocks.len});
}

/// Render the runtime prompt body (EPH-I0173, EPH-I0212): the scan path
/// and the command cross sanitizeTerminal before the trust-decision print,
/// so control bytes in either cannot rewrite the displayed terms. Caller
/// owns the returned slice.
fn runtimePromptText(
    allocator: Allocator,
    base_path: []const u8,
    cmd_str: []const u8,
) ![]const u8 {
    var safe_path = try types.sanitizeTerminal(allocator, base_path);
    defer safe_path.deinit(allocator);
    var safe_cmd = try types.sanitizeTerminal(allocator, cmd_str);
    defer safe_cmd.deinit(allocator);
    return std.fmt.allocPrint(allocator,
        \\
        \\WARNING: Runtime analysis will COMPILE AND EXECUTE code in:
        \\  {s}
        \\
        \\Command: {s}
        \\
        \\This runs untrusted code with your user privileges.
        \\Only run this on projects you trust.
        \\
        \\Proceed? [y/N]
    , .{ safe_path.slice, safe_cmd.slice });
}

/// Interactive gate for `runtime`: the analysis compiles and executes the
/// target, so the user confirms unless --yes was passed. Returns false on
/// any answer other than y/Y (EOF included). JSON mode owns the stream as
/// a machine guarantee (EPH-I1099): no prompt text may print and no silent
/// stdin read may hang a machine consumer, so the call declines without
/// printing or reading; the caller routes the decline to the abort object.
fn confirmRuntime(ctx: *const RunCtx) !bool {
    if (ctx.cfg.auto_approve) return true;
    if (ctx.cfg.format == .json) return false;
    const cmd_str = ctx.cfg.runtime_command orelse "zig build test";
    const prompt = try runtimePromptText(ctx.alloc, ctx.base_path, cmd_str);
    defer ctx.alloc.free(prompt);
    std.debug.print("{s}", .{prompt});
    var read_buf: [16]u8 = undefined;
    var stdin_reader = std.Io.File.stdin().reader(ctx.diag.io, &read_buf);
    const n = stdin_reader.interface.readSliceShort(&read_buf) catch 0;
    if (n == 0 or (read_buf[0] != 'y' and read_buf[0] != 'Y')) {
        std.debug.print("Aborted.\n", .{});
        return false;
    }
    return true;
}

/// `runtime` command: dynamic analysis under the project's own test run.
/// A declined prompt skips the epilogue (no update notification); the run
/// still exits with the decline code (EPH-I0261).
fn handleRuntime(ctx: *RunCtx) !void {
    if (!try confirmRuntime(ctx)) {
        // JSON mode: the decline rides the epilogue abort object
        // (EPH-I1099). The stashed diagnostic names the --yes remedy,
        // and the run exits 1, so the armed machine stream carries one
        // document instead of ending empty.
        if (ctx.cfg.format == .json) {
            cliDiag(
                ctx.diag,
                "error: runtime analysis needs interactive confirmation. Pass --yes to run it\n",
                .{},
            );
            ctx.should_exit_error = true;
            return;
        }
        ctx.abort_epilogue = true;
        return;
    }
    try loadKnownIssues(ctx.diag, ctx.alloc, ctx.cfg);
    var suppressed: usize = 0;
    var analysis_ran = false;
    var issues = try runRuntimeAnalysis(
        ctx.diag.io,
        ctx.alloc,
        ctx.cfg.path,
        .{
            .verbose = ctx.cfg.verbose,
            .custom_command = ctx.cfg.runtime_command,
            .json_stream = ctx.diag.json_stream,
            .suppressed_out = &suppressed,
            .analysis_ran = &analysis_ran,
        },
    );
    defer deinitIssues(&issues, ctx.alloc);
    // Cannot-run class (EPH-I0734): a spawn failure, a capture overflow,
    // or a missing target directory means the analysis never ran. The
    // ZR104 finding names the cause, and the exit code fails the run
    // like a declined prompt (EPH-I0261) regardless of fail_on — a CI
    // gate must not pass on a run that analyzed nothing.
    if (!analysis_ran) ctx.should_exit_error = true;
    const c = printIssues(issues.items, "runtime", ctx.reportOut(null));
    // EPH-I0211: the dedup/cap note. cliDiag's json latch keeps it off
    // the machine stream (the band precedent: the truncation warning).
    if (suppressed > 0) {
        cliDiag(
            ctx.diag,
            "note: {d} further runtime findings suppressed (duplicates or the cap)\n",
            .{suppressed},
        );
    }
    reportSuppression(ctx.diag, &ctx.suppression, ctx.cfg, null);
    applyStrictGate(c, ctx.cfg, &ctx.strict_fail);
}

/// Every findings list the `check` report consumes, plus the AST-tier
/// coverage counters. deinit releases the item payloads the same way the
/// pre-split per-list defers did.
const CheckFindings = struct {
    orphan_issues: std.ArrayListUnmanaged(Issue),
    cfg_mem_issues: std.ArrayListUnmanaged(Issue),
    err_issues: std.ArrayListUnmanaged(Issue),
    ignored_err_issues: std.ArrayListUnmanaged(Issue),
    unused_issues: std.ArrayListUnmanaged(Issue),
    cx_issues: std.ArrayListUnmanaged(Issue),
    fmt_issues: std.ArrayListUnmanaged(Issue),
    style_issues: std.ArrayListUnmanaged(Issue),
    naming_issues: std.ArrayListUnmanaged(Issue),
    test_issues: std.ArrayListUnmanaged(Issue),
    conc_issues: std.ArrayListUnmanaged(Issue),
    ast_stats: ast_tier.Stats,
    /// ZT105 pub-fn census for the coverage gate (EPH-I1091).
    coverage: UntestedFnCounts = .{},

    fn deinit(self: *CheckFindings, alloc: Allocator) void {
        deinitIssues(&self.orphan_issues, alloc);
        deinitIssues(&self.cfg_mem_issues, alloc);
        deinitIssues(&self.err_issues, alloc);
        deinitIssues(&self.ignored_err_issues, alloc);
        deinitIssues(&self.unused_issues, alloc);
        deinitIssues(&self.cx_issues, alloc);
        deinitIssues(&self.fmt_issues, alloc);
        deinitIssues(&self.style_issues, alloc);
        deinitIssues(&self.naming_issues, alloc);
        deinitIssues(&self.test_issues, alloc);
        deinitIssues(&self.conc_issues, alloc);
    }
};

/// Keep only memory-family findings in the list (EPH-I0723): the CFG
/// pass the memory command shares with check emits the error tier
/// (ZA202/ZA203, runCFGSafetyAnalyses → analyzeCFGErrors), the
/// definite-assignment rule (ZA607), and the null-safety and panic
/// families too, and the specialized command's promise is the memory
/// category (ZA1xx). In-place compaction keeps ownership single: a
/// dropped item's payloads free here, the kept ones stay with the list
/// for the caller's deinit. Infallible by construction (no allocation).
fn filterMemoryFamily(issues: *std.ArrayListUnmanaged(Issue), allocator: Allocator) void {
    var write: usize = 0;
    for (issues.items) |*issue| {
        if (mem.startsWith(u8, issue.rule, "ZA1")) {
            issues.items[write] = issue.*;
            write += 1;
        } else {
            issue.deinit(allocator);
        }
    }
    issues.items.len = write;
}

/// The cfg_mem_issues list split by rule family: ZA8 → null-safety, ZA9 →
/// panic, everything else → memory. ZA2 drops out (analyzeErrors owns those
/// findings; printing both would duplicate them). The buckets hold copies,
/// so deinit frees the bucket arrays only.
const FilteredMemIssues = struct {
    mem_only: std.ArrayListUnmanaged(Issue),
    null_safety: std.ArrayListUnmanaged(Issue),
    panic: std.ArrayListUnmanaged(Issue),

    fn deinit(self: *FilteredMemIssues, alloc: Allocator) void {
        self.mem_only.deinit(alloc);
        self.null_safety.deinit(alloc);
        self.panic.deinit(alloc);
    }
};

/// Per-category print counts from one `check` run: the summary table reads
/// the fields, the strict gate reads total().
const CheckCounts = struct {
    orphan: PrintCounts,
    mem: PrintCounts,
    /// Combined errors counts: the report merges the two error-family
    /// lists into one stream object, so each analyzer key appears once
    /// (EPH-I0536, B15 F3).
    err: PrintCounts,
    null_safety: PrintCounts,
    panic: PrintCounts,
    unused: PrintCounts,
    cx: PrintCounts,
    fmt: PrintCounts,
    naming: PrintCounts,
    style: PrintCounts,
    tests: PrintCounts,
    conc: PrintCounts,

    fn total(self: *const CheckCounts) PrintCounts {
        return self.orphan
            .add(self.mem)
            .add(self.err).add(self.null_safety)
            .add(self.panic).add(self.unused)
            .add(self.cx).add(self.fmt)
            .add(self.naming).add(self.style)
            .add(self.tests).add(self.conc);
    }
};

/// Emit the post-load trust disclosures (RED3-4/RED3-9, EPH-I0209/I0169)
/// from the check handler, after the CLI path and the target-config load
/// settle the final scan root. Target-dir configs print their own trust
/// notes from the loader; this helper covers the cwd channel and the
/// error-naming convention, whose source config path was recorded during
/// the parse.
fn notePostLoadTrust(diag: *DiagCtx, allocator: Allocator, cfg: *const Config) !void {
    // The cwd config loads trusted and unconditionally; disclose the
    // decision whenever its directory covers the scan target.
    if (cfg.cwd_config_loaded and configDirCoversScanRoot(diag.io, ".", cfg.path))
        try noteTrustedConfig(diag, allocator, CONFIG_FILENAME);
    try noteDualLoadIfAny(diag, allocator, cfg);
    // A non-default error-naming convention that comes from a config at
    // or inside the scanned tree.
    if (cfg.error_naming != .title_case) {
        if (cfg.error_naming_from_path) |src| {
            if (configDirInsideScanRoot(diag.io, configPathDirname(src), cfg.path))
                try noteErrorNamingSource(diag, allocator, src, cfg.error_naming);
        }
    }
}

/// The dual-load note (EPH-I0076): when a target-side config also
/// loaded, the cwd config's exclude and rule lists apply to the target
/// scan. Skipped when the last committed config came from the cwd
/// itself — `ephor check .` loads the same file twice.
fn noteDualLoadIfAny(diag: *DiagCtx, allocator: Allocator, cfg: *const Config) !void {
    if (!cfg.cwd_config_loaded or !cfg.target_config_loaded) return;
    const dir = cfg.config_dir orelse return;
    if (mem.eql(u8, dir, ".")) return;
    try noteDualConfigLoad(diag, allocator, dir);
}

/// `check` command: run every analyzer over the import graph and print the
/// merged report. The pipeline splits into scan → collect → report so each
/// stage stays a flat orchestration.
fn handleCheck(ctx: *RunCtx) !void {
    if (ctx.cfg.entries.items.len == 0) {
        printNoEntriesError(ctx.diag);
        ctx.should_exit_error = true;
    }
    if (ctx.should_exit_error) return;
    try notePostLoadTrust(ctx.diag, ctx.alloc, ctx.cfg);
    try loadKnownIssues(ctx.diag, ctx.alloc, ctx.cfg);
    var g = ImportGraph.init(ctx.alloc, ctx.diag);
    defer g.deinit();
    g.scan_root = ctx.base_path;
    try buildCheckGraph(ctx, &g);
    requireScannedFiles(ctx, &g);
    if (ctx.should_exit_error) return;
    var findings = try collectCheckFindings(ctx, &g);
    defer findings.deinit(ctx.alloc);
    try reportCheckFindings(ctx, &g, &findings);
}

/// Build the check run's import graph: scan the configured path, pull in
/// entry files outside it, then mark reachability.
fn buildCheckGraph(ctx: *const RunCtx, g: *ImportGraph) !void {
    try scanPath(g, ctx.cfg.path);
    try noteEntriesWidenScan(ctx.diag, ctx.alloc, ctx.cfg.path, ctx.cfg.entries.items);
    // Entry-point files outside the scanned path still feed orphan
    // detection when checking subdirectories. One physical file scans
    // once: a repeated occurrence (duplicate string, alternate spelling)
    // handed to analyzeFile a second time overwrites the first graph
    // entry and leaks the replaced value and the stored key (EPH-I0817).
    var seen: std.StringHashMapUnmanaged(void) = .empty;
    defer {
        var iter = seen.keyIterator();
        while (iter.next()) |key| ctx.alloc.free(key.*);
        seen.deinit(ctx.alloc);
    }
    for (ctx.cfg.entries.items) |e| {
        if (try markEntryScanned(ctx.diag.io, ctx.alloc, &seen, e)) continue;
        scanOutOfRootEntry(ctx, g, e);
    }
    for (ctx.cfg.entries.items) |e| try g.markReachable(e);
    try g.markBuildPathReferences(ctx.cfg);
}

/// Insert `entry` into the out-of-root scan set and return true when a
/// previous occurrence already scanned the same physical file (EPH-I0817).
/// The key is the entry's realpath when it resolves, the raw text
/// otherwise: duplicate strings and alternate spellings of one file
/// collapse to one scan, while unresolvable entries still dedupe by their
/// text. The set owns its keys; buildCheckGraph frees them at teardown.
fn markEntryScanned(
    io: std.Io,
    allocator: Allocator,
    seen: *std.StringHashMapUnmanaged(void),
    entry: []const u8,
) !bool {
    var buf: [Fs.max_path_bytes]u8 = undefined;
    const resolved = Fs.cwd(io).realpath(entry, &buf) catch null;
    const owned = try allocator.dupe(u8, resolved orelse entry);
    errdefer allocator.free(owned);
    // The map keeps the key on a fresh insert, so the success path either
    // frees (already scanned) or hands the key to the map. The contains
    // + put form keeps the handoff visible to the ZA101 transfer model
    // (getOrPut's key retention is not in the container method table).
    if (seen.contains(owned)) {
        allocator.free(owned);
        return true;
    }
    try seen.put(allocator, owned, {});
    return false;
}

/// Scan one entry file that sits outside the scanned path. Boundary
/// compare (RED4-3): entry "src-evil/x.zig" is outside path "src" and must
/// still be scanned for orphans. The coverage test is realpath-normalized
/// (EPH-I0812), so an entry spelling the scanned file differently does not
/// scan it a second time. Repeated occurrences of one physical file among
/// the entries dedupe at the caller before this gate (EPH-I0817). EPH-I0195:
/// ingest is the containment boundary, so out-of-root entries can only
/// arrive here via operator channels (CLI --entry, trusted config), where
/// outside reads are the documented RED4-3 orphan feature.
fn scanOutOfRootEntry(ctx: *const RunCtx, g: *ImportGraph, entry: []const u8) void {
    if (entryCoveredByScan(ctx.diag.io, ctx.cfg.path, entry)) return;
    g.scanSingleFile(entry) catch |err| noteMissingEntry(ctx.cfg, entry, err);
}

/// True when `entry` sits inside the scan path's tree. When both sides
/// realpath-resolve, the physical tree decides: equal realpaths mean one
/// physical file, so alternate spellings (absolute, infix-./) count as
/// covered. A symlink escape reads as outside, and two distinct files
/// never collide. When either side fails to resolve, the textual test
/// decides, exactly as before (EPH-I0812).
fn entryCoveredByScan(io: std.Io, scan_path: []const u8, entry: []const u8) bool {
    var scan_buf: [Fs.max_path_bytes]u8 = undefined;
    var entry_buf: [Fs.max_path_bytes]u8 = undefined;
    const scan_real = Fs.cwd(io).realpath(scan_path, &scan_buf) catch null;
    const entry_real = Fs.cwd(io).realpath(entry, &entry_buf) catch null;
    if (scan_real) |sr| {
        if (entry_real) |er| return isPathAncestorOrEqual(sr, er);
    }
    return isPathAncestorOrEqual(scan_path, entry);
}

/// Verbose-only note for an entry file that could not be scanned. A
/// missing entry file is not an error.
fn noteMissingEntry(cfg: *const Config, entry: []const u8, err: anyerror) void {
    if (!cfg.verbose) return;
    std.debug.print("note: entry {s} not found: {}\n", .{ entry, err });
}

/// Count the out-of-root .zig entry strings for the scan-shape note
/// (EPH-I0784): the entries passing both gates — outside the scan path
/// (scanOutOfRootEntry's boundary, realpath-normalized per EPH-I0812) and
/// .zig-suffixed (scanSingleFile's filter). The count is an upper bound on
/// joins, not the join count itself: analyzeFile skips missing or
/// unreadable reads silently, and the --entry and config appends do not
/// dedup, so a stale or duplicated entry counts here but never joins the
/// graph. Every entry passing both gates counts once per occurrence.
/// Genuine widening is never missed — every joined entry passed both
/// gates, so the count can only over-report (EPH-I0802).
fn countOutOfRootEntries(io: std.Io, scan_path: []const u8, entries: []const []const u8) usize {
    var count: usize = 0;
    for (entries) |entry| {
        if (entryCoveredByScan(io, scan_path, entry)) continue;
        if (!mem.endsWith(u8, entry, ".zig")) continue;
        count += 1;
    }
    return count;
}

/// EPH-I0784 scan-shape note: the check scan is the CLI path UNION the
/// entry points (the join is intended). Fires only when at least one .zig
/// entry sits outside the scan path, so a run the CLI path already covers
/// stays silent. The coverage test is realpath-normalized (EPH-I0812): an
/// entry spelling the scanned file differently does not count. N is
/// countOutOfRootEntries' upper bound, not the joined-file count
/// (EPH-I0802). The path crosses the terminal sanitizer: it can derive
/// from a config file (EPH-I0147).
fn noteEntriesWidenScan(
    diag: *DiagCtx,
    allocator: Allocator,
    scan_path: []const u8,
    entries: []const []const u8,
) !void {
    const widened = countOutOfRootEntries(diag.io, scan_path, entries);
    if (widened == 0) return;
    var safe_path = try types.sanitizeTerminal(allocator, scan_path);
    defer safe_path.deinit(allocator);
    // B13-21 (EPH-I0520): count only after the fallible sanitize
    // succeeded — an OOM before the note prints must not count it.
    diag.entries_widen_note_count += 1;
    cliDiag(
        diag,
        "note: scan includes {d} entry point{s} outside {s} " ++
            "(entry points always join the scan)\n",
        .{ widened, if (widened == 1) @as([]const u8, "") else "s", safe_path.slice },
    );
}

/// Run every analyzer over the graph and merge the auxiliary lists
/// (skipped files, int-cast guards, AST tier) into their report homes.
/// errdefer mirrors the pre-split per-list defers on the error path.
fn collectCheckFindings(ctx: *const RunCtx, g: *ImportGraph) !CheckFindings {
    const alloc = ctx.alloc;
    var orphan_issues = try g.getOrphanIssues(alloc, ctx.cfg);
    errdefer deinitIssues(&orphan_issues, alloc);
    try mergeSkippedIssues(alloc, g, &orphan_issues);
    var cfg_mem_issues = try analyzeCFGMemory(alloc, g);
    errdefer deinitIssues(&cfg_mem_issues, alloc);
    try mergeIntCastIssues(alloc, g, &cfg_mem_issues);
    // AST tier: ZA111 findings join the memory list, ZA503 parse
    // findings join the structure list before its sort so the merged
    // list stays file-ordered (EPH-I0742). The returned skip log names
    // the skipped paths in the skip note (EPH-I1197).
    var ast_stats = ast_tier.Stats{};
    const skip_log = try mergeAstTierIssues(alloc, g, &ast_stats, .{
        .cfg = &cfg_mem_issues,
        .structure = &orphan_issues,
    });
    sortIssuesByFile(orphan_issues.items);
    var err_issues = try analyzeErrors(alloc, g);
    errdefer deinitIssues(&err_issues, alloc);
    var unused_issues = try analyzeUnused(alloc, g);
    errdefer deinitIssues(&unused_issues, alloc);
    var cx_issues = try analyzeComplexity(alloc, g, ctx.cfg.thresholds);
    errdefer deinitIssues(&cx_issues, alloc);
    var fmt_issues = try runFmtCheck(ctx.diag, alloc, ctx.cfg.path);
    errdefer deinitIssues(&fmt_issues, alloc);
    var style_issues = try analyzeStyle(alloc, g, ctx.cfg.thresholds);
    errdefer deinitIssues(&style_issues, alloc);
    var naming_issues = try analyzeNaming(alloc, g, ctx.cfg.error_naming);
    errdefer deinitIssues(&naming_issues, alloc);
    var coverage_counts: UntestedFnCounts = .{};
    var test_issues = try analyzeTests(alloc, g, &coverage_counts);
    errdefer deinitIssues(&test_issues, alloc);
    var conc_issues = try analyzeConcurrency(alloc, g);
    errdefer deinitIssues(&conc_issues, alloc);
    noteAstTierSkips(ctx.diag, ast_stats, skip_log);
    var ignored_err_issues = try analyzeIgnoredErrors(alloc, g);
    errdefer deinitIssues(&ignored_err_issues, alloc);
    return .{
        .orphan_issues = orphan_issues,
        .cfg_mem_issues = cfg_mem_issues,
        .err_issues = err_issues,
        .ignored_err_issues = ignored_err_issues,
        .unused_issues = unused_issues,
        .cx_issues = cx_issues,
        .fmt_issues = fmt_issues,
        .style_issues = style_issues,
        .naming_issues = naming_issues,
        .test_issues = test_issues,
        .conc_issues = conc_issues,
        .ast_stats = ast_stats,
        .coverage = coverage_counts,
    };
}

/// ZA904 (opt-in note) rides the CFG list so it flows through the ZA9 →
/// panic category filter and the export list. Messages are static (not
/// owned), so the cast list frees only its array after the atomic move
/// (EPH-I0690, F-2).
fn mergeIntCastIssues(
    alloc: Allocator,
    g: *ImportGraph,
    into: *std.ArrayListUnmanaged(Issue),
) !void {
    var cast_issues = try analyzeIntCastGuards(alloc, g);
    errdefer deinitIssues(&cast_issues, alloc);
    try moveIssues(alloc, into, &cast_issues);
    cast_issues.deinit(alloc);
    cast_issues = .empty;
}

/// Sink pair for mergeAstTierIssues (EPH-I0742): ZA111 findings merge
/// into the memory list, ZA503 parse findings into the structure list.
/// One struct keeps the merge signature at four parameters.
const AstTierMergeSinks = struct {
    cfg: *std.ArrayListUnmanaged(Issue),
    structure: *std.ArrayListUnmanaged(Issue),
};

/// AST tier: ZA111 findings merge into the memory list so they flow
/// through the ZA1 → memory category filter and the export list; ZA503
/// parse findings merge into the structure list (EPH-I0742) so they
/// print beside the other file-level skips. Item ownership moves with
/// the atomic moveIssues transfer (EPH-I0690, F-2), so the tier list
/// frees only its array on the success path; an OOM keeps the owned
/// payloads with the list for the errdefer. The parse findings append
/// directly into `sinks.structure`, whose own errdefer covers them. The
/// returned skip log records the skipped paths for the skip note
/// (EPH-I1197).
fn mergeAstTierIssues(
    alloc: Allocator,
    g: *ImportGraph,
    stats: *ast_tier.Stats,
    sinks: AstTierMergeSinks,
) !SkipPathLog {
    var skip_log = SkipPathLog{};
    var obs = AstTierObs{ .parse = sinks.structure, .skips = &skip_log };
    var ast_issues = try analyzeAstTier(alloc, g, stats, &obs);
    errdefer deinitIssues(&ast_issues, alloc);
    try moveIssues(alloc, sinks.cfg, &ast_issues);
    ast_issues.deinit(alloc);
    ast_issues = .empty;
    return skip_log;
}

/// Print every category's findings, the suppression note, the optional
/// summary, and the footer, then apply the strict gate and export.
fn reportCheckFindings(ctx: *RunCtx, g: *ImportGraph, findings: *CheckFindings) !void {
    const out = ctx.reportOut(g);
    var filtered = try filterMemIssues(ctx.alloc, findings.cfg_mem_issues.items);
    defer filtered.deinit(ctx.alloc);
    const counts = try printCheckReports(out, findings, &filtered);
    // RED3-3: the suppression note lands before STATUS/summary/footer so a
    // suppressed repo never shows a bare clean status.
    reportSuppression(ctx.diag, &ctx.suppression, ctx.cfg, null);
    if (ctx.cfg.show_summary) printCheckSummary(ctx, g, findings, &counts);
    printResultFooter(counts.total(), ctx.cfg.format);
    // Findings are informational unless --strict/--fail-on gates them.
    applyStrictGate(counts.total(), ctx.cfg, &ctx.strict_fail);
    // Coverage gate (EPH-I1091): the ratio leg runs on the scan's ZT105
    // census; the runner legs run only when --coverage-evidence supplied
    // the runner's counts. The block applies only to the operator's own
    // tree (the scan root inside the invocation cwd) — a coverage limit
    // is a self-measurement, never a verdict on a foreign scan target. In
    // text mode a broken evidence file warns (the gate script fails on
    // the warning) and leaves the runner legs unevaluated; in JSON mode
    // the run fails closed with the abort object.
    if (coverageGateAppliesToScan(ctx)) {
        loadRunCoverageEvidence(ctx);
        applyCoverageGate(ctx, findings.coverage);
    }
    try exportCheckIssues(ctx, out, findings, &filtered);
}

/// Split the merged CFG list into the memory, null-safety, and panic
/// report buckets, dropping the ZA2 items the CFG error tier emits
/// (ZA202/ZA203, runCFGSafetyAnalyses → analyzeCFGErrors): analyzeErrors
/// re-emits each one at the same (file, line), so keeping them here
/// would double-print. The ZA2-ownership test pins the twin assumption
/// — every dropped CFG ZA2 must have a same-(file, line, rule) twin in
/// the errors list — and that the drop is the only thing keeping ZA2
/// out of the buckets (EPH-I0174).
fn filterMemIssues(alloc: Allocator, items: []const Issue) !FilteredMemIssues {
    var filtered = FilteredMemIssues{
        .mem_only = .empty,
        .null_safety = .empty,
        .panic = .empty,
    };
    errdefer filtered.deinit(alloc);
    for (items) |issue| {
        if (mem.startsWith(u8, issue.rule, "ZA8")) {
            try filtered.null_safety.append(alloc, issue);
        } else if (mem.startsWith(u8, issue.rule, "ZA9")) {
            try filtered.panic.append(alloc, issue);
        } else if (mem.startsWith(u8, issue.rule, "ZA2")) {
            continue;
        } else {
            try filtered.mem_only.append(alloc, issue);
        }
    }
    return filtered;
}

/// Print all thirteen categories in the pinned report order. The two
/// error-family lists merge into one "errors" stream object: a consumer
/// keying on the analyzer name must see each analyzer at most once
/// (EPH-I0536, B15 F3).
fn printCheckReports(
    out: ReportOutCtx,
    findings: *CheckFindings,
    filtered: *FilteredMemIssues,
) !CheckCounts {
    var err_merged = std.ArrayListUnmanaged(Issue).empty;
    // Array-only ownership: the item payloads stay owned by their source
    // lists until CheckFindings teardown (EPH-I0882 pattern).
    defer err_merged.deinit(out.allocator);
    try err_merged.appendSlice(out.allocator, findings.ignored_err_issues.items);
    try err_merged.appendSlice(out.allocator, findings.err_issues.items);

    const orphan = printIssues(findings.orphan_issues.items, "orphans", out);
    const mem_count = printIssues(filtered.mem_only.items, "memory", out);
    const err = printIssues(err_merged.items, "errors", out);
    const null_safety = printIssues(filtered.null_safety.items, "null-safety", out);
    const panic = printIssues(filtered.panic.items, "panic", out);
    const unused = printIssues(findings.unused_issues.items, "unused", out);
    const cx = printIssues(findings.cx_issues.items, "complexity", out);
    const fmt = printIssues(findings.fmt_issues.items, "format", out);
    const naming = printIssues(findings.naming_issues.items, "naming", out);
    const style = printIssues(findings.style_issues.items, "style", out);
    const tests = printIssues(findings.test_issues.items, "tests", out);
    const conc = printIssues(findings.conc_issues.items, "concurrency", out);
    return .{
        .orphan = orphan,
        .mem = mem_count,
        .err = err,
        .null_safety = null_safety,
        .panic = panic,
        .unused = unused,
        .cx = cx,
        .fmt = fmt,
        .naming = naming,
        .style = style,
        .tests = tests,
        .conc = conc,
    };
}

/// The --summary block: merge the AST-tier counters into the scan stats
/// (EPH-I0200: getStats walks content only and cannot observe parse
/// outcomes), then print in the configured format.
fn printCheckSummary(
    ctx: *const RunCtx,
    g: *ImportGraph,
    findings: *const CheckFindings,
    counts: *const CheckCounts,
) void {
    var stats = g.getStats();
    stats.ast_parsed = findings.ast_stats.parsed;
    stats.ast_skipped = findings.ast_stats.skipped;
    // Note-severity findings ride one summary member, not per-category
    // buckets: the buckets keep the historical warnings-only meaning
    // (EPH-I0535).
    const all = counts.total();
    printSummary(.{
        .orphan = counts.orphan.warnings,
        .memory = counts.mem.warnings,
        .err = counts.err.warnings,
        .unused = counts.unused.warnings,
        .complexity = counts.cx.warnings,
        .fmt = counts.fmt.warnings,
        .style = counts.style.warnings + counts.naming.warnings,
        .null_safety = counts.null_safety.warnings,
        .panic = counts.panic.warnings,
        .tests = counts.tests.warnings,
        .concurrency = counts.conc.warnings,
        .notes = all.notes,
    }, stats, ctx.suppression, ctx.cfg.format);
}

/// Print the export confirmation. The path crosses the terminal
/// sanitizer like every other repo-derived path print (EPH-I0147): a
/// hostile byte in --export= must not reach the terminal. On sanitize
/// OOM the notice prints the count without the path rather than risk
/// the raw bytes. cliDiag keeps the notice off the JSON machine stream
/// (EPH-I0213) and lets tests capture it through the sink (EPH-I1051).
fn printExportNotice(
    diag: *DiagCtx,
    allocator: Allocator,
    exported_count: usize,
    export_path: []const u8,
) void {
    var safe_path = types.sanitizeTerminal(allocator, export_path) catch {
        cliDiag(diag, "exported {d} issues\n", .{exported_count});
        return;
    };
    defer safe_path.deinit(allocator);
    cliDiag(diag, "exported {d} issues to {s}\n", .{ exported_count, safe_path.slice });
}

/// --export=<file>: gather every printed finding into one list and write
/// the export document. An export failure prints an error and fails the
/// run (EPH-I0741): a CI step that lost its export artifact must not
/// pass. The error line crosses cliDiag, whose json_stream latch keeps
/// it off the JSON machine stream; the exit flag carries the failure
/// in both modes (the stashed diagnostic rides the JSON abort object).
fn exportCheckIssues(
    ctx: *RunCtx,
    out: ReportOutCtx,
    findings: *const CheckFindings,
    filtered: *const FilteredMemIssues,
) !void {
    const export_path = ctx.cfg.export_path orelse return;
    var all_issues = try collectAllIssues(ctx.alloc, findings, filtered);
    defer all_issues.deinit(ctx.alloc);
    // cliDiag gates both notices on json_stream: the machine stream
    // stays pure in JSON mode (EPH-I0213), and the export file itself
    // is the result signal there. The confirmation path is sanitized
    // (EPH-I0542).
    if (exportIssues(ctx.alloc, export_path, all_issues.items, out)) |exported_count| {
        printExportNotice(ctx.diag, ctx.alloc, exported_count, export_path);
    } else |err| {
        cliDiag(ctx.diag, "error: failed to export issues: {}\n", .{err});
        // The run survives this failure: the exit flag carries it, so
        // the printed-error latch must not keep speaking for a later
        // unrelated failure (EPH-I1161).
        unlatchErrorDiag(ctx.diag);
        ctx.should_exit_error = true;
    }
}

/// Gather every printed list into one slice for export, in report order.
/// The lists differ only by source field, so an inline-for over the group
/// tuple keeps the gather data-driven instead of thirteen hand copies.
fn collectAllIssues(
    alloc: Allocator,
    findings: *const CheckFindings,
    filtered: *const FilteredMemIssues,
) !std.ArrayListUnmanaged(Issue) {
    var all = std.ArrayListUnmanaged(Issue).empty;
    // Array-only unwind: the gather appends shallow copies, and every
    // item's payload stays owned by its source list until CheckFindings
    // teardown. deinitIssues here would free the payloads twice, so the
    // errdefer frees only the array (EPH-I0882). The export caller
    // mirrors the array-only deinit on the success path.
    errdefer all.deinit(alloc);
    const groups = .{
        findings.orphan_issues.items, filtered.mem_only.items,
        findings.err_issues.items,    findings.ignored_err_issues.items,
        findings.unused_issues.items, findings.cx_issues.items,
        findings.fmt_issues.items,    findings.style_issues.items,
        findings.naming_issues.items, filtered.null_safety.items,
        filtered.panic.items,         findings.test_issues.items,
        findings.conc_issues.items,
    };
    inline for (groups) |items| {
        for (items) |issue| try all.append(alloc, issue);
    }
    return all;
}

/// Error exit path (EPH-I0543). JSON mode owns the stream as a machine
/// guarantee: the runtime's bare error line would break it (EPH-I0213),
/// so the run emits one machine-readable error object and returns the
/// failure code (EPH-I1067). `msg` rides as the message member — the
/// stashed diagnostic for a parse abort, empty for a mid-run handler
/// failure, where no diagnostic belongs to the abort. Text mode
/// propagates the error so the runtime prints the diagnostic. Neither
/// mode exits here: runEphor's defers run at its return, and the entry
/// wrapper applies the code through std.process.exit from a scope with
/// no pending defers.
fn errorExitCode(diag: *DiagCtx, allocator: Allocator, err: anyerror, msg: []const u8) !u8 {
    if (diag.json_stream) {
        printAbortJson(allocator, err, msg);
        return 1;
    }
    // One error line per failure (EPH-I0728): when a diagnostic already
    // named the failure, propagating the error would make the runtime
    // print a second bare "error: X" line. The exit code returns
    // silently instead. An error no diagnostic named (an OOM mid-run)
    // still propagates so the runtime line stays the only signal.
    if (diag.error_diag_printed) return 1;
    return err;
}

/// Print the JSON-mode abort object once (EPH-I1067): the error name and
/// the message render into one buffer, so a render failure cannot strand
/// a partial object in the machine stream (the buildIssuesJson
/// guarantee). On failure the run degrades to the allocation-free object
/// of the same shape with an empty message: the machine stream must
/// still carry a valid document.
fn printAbortJson(allocator: Allocator, err: anyerror, msg: []const u8) void {
    var obj = types.OutBuf{ .allocator = allocator };
    defer obj.deinit();
    buildAbortJson(&obj, allocator, err, msg) catch {
        std.debug.print("{{\n  \"error\": \"{s}\",\n  \"message\": \"\"\n}}\n", .{@errorName(err)});
        return;
    };
    std.debug.print("{s}", .{obj.buf.items});
}

/// Render the JSON-mode abort object into `obj` (EPH-I1067): the error
/// name and the diagnostic message. The message crosses escapeJson like
/// every repo-derived field (EPH-I0146); the error name is a Zig
/// identifier, so it never needs escaping.
fn buildAbortJson(
    obj: *types.OutBuf,
    allocator: Allocator,
    err: anyerror,
    msg: []const u8,
) !void {
    var escaped = try types.escapeJson(allocator, msg);
    defer escaped.deinit(allocator);
    try obj.buf.print(allocator,
        \\{{
        \\  "error": "{s}",
        \\  "message": "{s}"
        \\}}
        \\
    , .{ @errorName(err), escaped.slice });
}

/// Print the pending unknown-version fallback warning through the
/// diagnostics channel (EPH-I1054): cliDiag's json_stream latch keeps
/// the warning off the machine stream on a fallback build running
/// --format=json, and the DiagSink captures it for in-process pins.
/// Text mode prints it after the findings, because compat records the
/// flag during analysis.
fn reportUnknownVersionWarning(diag: *DiagCtx) void {
    if (!compat.takeUnknownVersionWarning()) return;
    cliDiag(diag, "{s}", .{compat.unknown_version_warning_text});
}

/// Abort disposition for an unresolved scan root (EPH-I0172, RED4-7):
/// the path may carry scanned-tree bytes (path_dir from an untrusted
/// config), so it crosses the terminal sanitizer before the render. On
/// sanitize OOM the message drops the path rather than print it raw.
/// The exit code carries the JSON abort object (errorExitCode).
fn unresolvedScanRootExit(
    diag: *DiagCtx,
    allocator: Allocator,
    path: []const u8,
    err: anyerror,
) !u8 {
    if (types.sanitizeTerminal(allocator, path)) |safe_val| {
        var safe_path = safe_val;
        defer safe_path.deinit(allocator);
        cliDiag(
            diag,
            "error: cannot resolve scan path '{s}': {s}\n",
            .{ safe_path.slice, @errorName(err) },
        );
    } else |_| {
        cliDiag(diag, "error: cannot resolve scan path: {s}\n", .{@errorName(err)});
    }
    return errorExitCode(
        diag,
        allocator,
        error.ScanRootUnresolved,
        diag.last_muted_diag[0..diag.last_muted_diag_len],
    );
}

/// Exit code for a declined text-mode runtime prompt (EPH-I0261): the
/// requested analysis did not run, so the decline is a failure. The
/// deliberate choice is documented in printHelp and the README: a CI
/// run without --yes fails instead of passing silently.
fn declinedRuntimeExitCode() u8 {
    return 1;
}

/// Exit code for a failed run (EPH-I1070 follow-up, EPH-I0543). Text
/// mode keeps the silent exit(1). JSON mode must leave a readable
/// document on the armed stream, so the abort object rides the code:
/// the stashed diagnostic (possibly empty) rides as the message,
/// exactly like the parse abort. One branch covers the flag-first,
/// no-entries, and strict-fail shapes. A clean run returns 0 and
/// runEphor's defers hold; the entry wrapper applies the code after
/// they run.
fn failedRunExitCode(diag: *DiagCtx, allocator: Allocator, ctx: *const RunCtx) u8 {
    if (!(ctx.should_exit_error or ctx.strict_fail or ctx.coverage_fail)) return 0;
    if (diag.json_stream) {
        printAbortJson(
            allocator,
            error.RunFailed,
            diag.last_muted_diag[0..diag.last_muted_diag_len],
        );
    }
    return 1;
}

/// Entry point. The run body lives in runEphor so its defers (the
/// config strings, the suppression cache, the DebugAllocator leak
/// report) run before any non-zero exit code applies (EPH-I0543):
/// std.process.exit never runs defers, so the exit must sit in a scope
/// with none pending — this one. A propagated error reaches the Zig
/// runtime's error path unchanged, exit code 1.
pub fn main(init: std.process.Init) !void {
    std.process.exit(try runEphor(init));
}

/// The run body (EPH-I0543): parse, dispatch, and the exit-code
/// computation. Every exit disposition returns through this function so
/// its defers run; the entry wrapper applies the code after they do.
fn runEphor(init: std.process.Init) !u8 {
    var diag = DiagCtx{ .io = init.io };
    // Production keeps the safety-on DebugAllocator by decision
    // (ADR-0008, F12, EPH-I0699): fail-closed heap checking on hostile
    // corpus input plus the exit leak report every gate relies on. Do
    // not switch allocators without a user ruling.
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();
    // JSON-mode pre-scan before tool-path resolution: the env warnings
    // fire before parseArgs' own scan would arm the latch (EPH-I0213).
    // parseArgs scans again: its latch must hold for direct test callers.
    if (scanArgsForJson(init.minimal.args)) diag.json_stream = true;
    initToolPaths(&diag, init.environ_map);

    var cfg = parseArgs(&diag, alloc, init.minimal.args) catch |err| {
        // The parse abort must still carry a machine-readable object on
        // the JSON stream: the stashed diagnostic rides as the message
        // (EPH-I1067).
        return errorExitCode(&diag, alloc, err, diag.last_muted_diag[0..diag.last_muted_diag_len]);
    };
    defer cfg.deinit(alloc);

    const entry = command_table.get(cfg.command);
    if (entry.check_updates) {
        checkForUpdates(
            &diag,
            alloc,
            init.environ_map.get("HOME"),
            init.environ_map.get("EPHOR_NO_UPDATE_CHECK"),
        );
    }
    // The pending notification outlives every return path from here
    // (abort, handler error, clean epilogue), so a deferred free covers
    // them all; the epilogue only prints (EPH-I0545).
    defer freeUpdateNotification(alloc);

    // EPH-I0172 (RED4-7): a failed root realpath aborts with an explicit
    // error — every containment gate keys on this root, so the raw-path
    // silent degrade must not come back.
    var base_buf: [std.fs.max_path_bytes]u8 = undefined;
    const base_path = Fs.cwd(diag.io).realpath(cfg.path, &base_buf) catch |err|
        return unresolvedScanRootExit(&diag, alloc, cfg.path, err);

    // Suppression-fact cache shared by every printIssues/exportIssues call in
    // this run; built lazily per (file, rule), freed at exit.
    var ignore_cache = IgnoreCache.init(alloc);
    defer ignore_cache.deinit();

    var ctx = RunCtx{
        .alloc = alloc,
        .cfg = &cfg,
        .diag = &diag,
        .base_path = base_path,
        .ignore_cache = &ignore_cache,
    };
    switch (entry.handler) {
        .infallible => |h| h(&ctx),
        // JSON mode owns the stream as a machine guarantee: the runtime's
        // bare error line would break it, so a failing handler emits the
        // machine error object with no diagnostic message (a mid-run
        // message does not belong to the abort) and returns the failure
        // code (EPH-I0213, EPH-I1067).
        .fallible => |h| h(&ctx) catch |err| return errorExitCode(&diag, alloc, err, ""),
    }
    // A declined runtime prompt skips the epilogue (no update
    // notification print), but the decline is a failed run: the exit
    // code carries it, so a CI pipeline without --yes fails instead of
    // passing silently while running nothing (EPH-I0261).
    if (ctx.abort_epilogue) return declinedRuntimeExitCode();

    // Unknown-version fallback warning (EPH-I1054): compat recorded the
    // flag during analysis; the epilogue routes the message through
    // cliDiag, whose json_stream latch keeps it off the JSON machine
    // stream.
    reportUnknownVersionWarning(&diag);

    // Print update notification after all analysis output. JSON mode
    // skips it so the machine stream stays pure (EPH-I0213). The
    // deferred free above covers every return path (EPH-I0545).
    if (update_notification) |msg| {
        if (cfg.format != .json) std.debug.print("{s}", .{msg});
    }

    // Exit code AFTER all defers run (EPH-I0543): runEphor computes the
    // code, its defers (cfg.deinit, gpa.deinit) run at the return, and
    // only then does the entry wrapper apply it through
    // std.process.exit. A failed run returns 1 here: text mode silently,
    // JSON mode emitting the abort object first so the armed stream
    // never ends without a document (EPH-I1070 follow-up).
    return failedRunExitCode(&diag, alloc, &ctx);
}

// ============================================================================
// Tests
// ============================================================================

/// Shared fixture for the IdentUseIndex tests: one line per masking shape
/// countRealIdentUses honors (string literals, escaped quotes, char
/// literals, `\\` bodies and mid-line tails, full and trailing comments,
/// word-boundary neighbors, a double occurrence on the declaring line).
const ident_use_test_content =
    "const a1 = 1;\n" ++ // 1
    "const a2 = a1 + a1;\n" ++ // 2
    "const a3 = a2;\n" ++ // 3
    "const s1 = \"a3 in string\";\n" ++ // 4
    "const c1 = 'a3';\n" ++ // 5
    "const m1 =\n" ++ // 6
    "    \\\\a3 multiline body\n" ++ // 7
    ";\n" ++ // 8
    "const t1 = a3; // trailing a1\n" ++ // 9
    "const dbl = dbl;\n" ++ // 10
    "const esc = \"a\\\"tail here\";\n" ++ // 11
    "const tail = 1;\n" ++ // 12
    "const fo = 1;\n" ++ // 13
    "const foo = fo;\n" ++ // 14
    "const food = fo;\n" ++ // 15
    "const pre = 1; const mid = pre;\n" ++ // 16
    "const solo = 1;\n" ++ // 17
    "// solo full-line comment\n" ++ // 18
    "const ml2 = 1;\n" ++ // 19
    "f(); \\\\ ml2 tail masked\n"; // 20

const ident_use_test_names = [_][]const u8{
    "a1",  "a2",    "a3",     "s1",      "c1",   "m1",  "t1",  "dbl",
    "esc", "tail",  "fo",     "foo",     "food", "pre", "mid", "solo",
    "ml2", "const", "string", "missing",
};

test "IdentUseIndex matches countRealIdentUses across masked shapes" {
    var index = IdentUseIndex.init(std.testing.allocator, ident_use_test_content);
    defer index.deinit();
    try index.build();
    var decl_line: usize = 1;
    while (decl_line <= 20) : (decl_line += 1) {
        for (ident_use_test_names) |name| {
            // The direct scan saturates at 1 (EPH-I0438), so parity here
            // is the > 0 verdict: masking drift still breaks parity in
            // both directions — an index count that should be 0 (masked
            // occurrence recorded) or a real use the index misses. The
            // exact counts are pinned by the exact-count test below.
            try std.testing.expectEqual(
                countRealIdentUses(ident_use_test_content, name, decl_line),
                @min(index.countUses(name, decl_line), 1),
            );
        }
    }
}

test "IdentUseIndex exact counts on masking edge shapes" {
    var index = IdentUseIndex.init(std.testing.allocator, ident_use_test_content);
    defer index.deinit();
    try index.build();
    // A second occurrence on the declaring line counts as a use.
    try std.testing.expectEqual(@as(usize, 1), index.countUses("dbl", 10));
    // A char literal is not masked: 'a3' counts as a use of a3.
    try std.testing.expectEqual(@as(usize, 2), index.countUses("a3", 3));
    // Occurrences inside string literals stay masked, escapes included.
    try std.testing.expectEqual(@as(usize, 0), index.countUses("tail", 12));
    try std.testing.expectEqual(@as(usize, 0), index.countUses("s1", 4));
    // A `\\` body line and a mid-line `\\` tail are string data.
    try std.testing.expectEqual(@as(usize, 0), index.countUses("m1", 6));
    try std.testing.expectEqual(@as(usize, 0), index.countUses("ml2", 19));
    // A full-line comment mention is not a use.
    try std.testing.expectEqual(@as(usize, 0), index.countUses("solo", 17));
    // A trailing-comment mention is not a use, and a declaring line with
    // no occurrence of the name subtracts nothing (a1 raw total is 3).
    try std.testing.expectEqual(@as(usize, 3), index.countUses("a1", 9));
    // Word boundaries: food is not a use of foo (raw total is the decl).
    try std.testing.expectEqual(@as(usize, 1), index.countUses("foo", 1));
    // The index answers for any name, even one its line never offered as
    // a decl candidate (mid is the second const on line 16).
    try std.testing.expectEqual(@as(usize, 0), index.countUses("mid", 16));
    try std.testing.expectEqual(@as(usize, 1), index.countUses("mid", 1));
    // Unknown names have no occurrences.
    try std.testing.expectEqual(@as(usize, 0), index.countUses("missing", 1));
}

test "IdentUseIndex falls back to the direct scan for non-identifier names" {
    const content = "const ab = 1;\ncall(a-b);\n";
    var index = IdentUseIndex.init(std.testing.allocator, content);
    defer index.deinit();
    try index.build();
    // "a-b" is not an identifier run, so the index cannot answer for it.
    // The fallback keeps the direct scan's verdict.
    try std.testing.expectEqual(countRealIdentUses(content, "a-b", 1), index.countUses("a-b", 1));
    try std.testing.expectEqual(@as(usize, 1), index.countUses("a-b", 1));
    // The empty name takes the same fallback.
    try std.testing.expectEqual(countRealIdentUses(content, "", 2), index.countUses("", 2));
}

test "countRealIdentUses saturates at the first confirmed use (EPH-I0438)" {
    // The > 0 verdict is the rule: a used decl answers 1 no matter
    // how many uses, an unused decl answers 0. Pre-fix the first case
    // returned the exact count 2, so the pin fails on the old code.
    const used = "const x = 1;\nuse(x);\nuse(x);\n";
    try std.testing.expectEqual(@as(usize, 1), countRealIdentUses(used, "x", 1));
    const unused = "const x = 1;\n";
    try std.testing.expectEqual(@as(usize, 0), countRealIdentUses(unused, "x", 1));
    // A self-reference on the declaring line is a use (the dbl pin's
    // semantics): n > 1 on the decl line confirms it immediately.
    const self_ref = "const dbl = dbl;\n";
    try std.testing.expectEqual(@as(usize, 1), countRealIdentUses(self_ref, "dbl", 1));
}

test "member-access runs are not decl-line self-uses (EPH-I0445)" {
    // `const h = @import("x").h;` holds two `h` runs on the declaring
    // line — the alias and the member access. The initializer's member
    // access is part of the declaration, not a use: pre-fix it left one
    // phantom use and the unused alias was never flagged.
    const lone = "const h = @import(\"x\").h;\n";
    var idx = IdentUseIndex.init(std.testing.allocator, lone);
    defer idx.deinit();
    try idx.build();
    try std.testing.expectEqual(@as(usize, 0), idx.countUses("h", 1));
    try std.testing.expectEqual(@as(usize, 0), countRealIdentUses(lone, "h", 1));
    // A real later use still counts: 2 occurrences, minus the decl line.
    const used = "const h = @import(\"x\").h;\nuse(h);\n";
    var idx2 = IdentUseIndex.init(std.testing.allocator, used);
    defer idx2.deinit();
    try idx2.build();
    try std.testing.expectEqual(@as(usize, 1), idx2.countUses("h", 1));
    try std.testing.expectEqual(@as(usize, 1), countRealIdentUses(used, "h", 1));
    // A `..` range end is a use, not a member access: the range's second
    // dot must not exclude the name (EPH-I0445 r1 — the first exclusion
    // cut read `for (0..n)` as a `0.n` member access and dropped real
    // uses, surfacing as 7 ZA402 FPs on ephor's own src/).
    const ranged = "const n = 4;\nfor (0..n) {}\n";
    var idx3 = IdentUseIndex.init(std.testing.allocator, ranged);
    defer idx3.deinit();
    try idx3.build();
    try std.testing.expectEqual(@as(usize, 1), idx3.countUses("n", 1));
    try std.testing.expectEqual(@as(usize, 1), countRealIdentUses(ranged, "n", 1));
    // Member-access uses on OTHER lines still count: a struct field's
    // uses are its member accesses (`Class.parent` reads the field).
    // Pre-fix verdicts for those shapes must not move (EPH-I0445 r1 —
    // the first global exclusion cut produced ghostty ZA402/403 FPs on
    // fields and mixin consts).
    const field_used = "var parent: *Parent.Class = undefined;\nuse(Class.parent);\n";
    var idx4 = IdentUseIndex.init(std.testing.allocator, field_used);
    defer idx4.deinit();
    try idx4.build();
    try std.testing.expectEqual(@as(usize, 1), idx4.countUses("parent", 1));
    try std.testing.expectEqual(@as(usize, 1), countRealIdentUses(field_used, "parent", 1));
}

test "countOccurrences" {
    const input = "pub fn a() pub fn b() pub fn c()";
    try std.testing.expectEqual(@as(usize, 3), countOccurrences(input, "pub fn "));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences("no matches", "pub fn "));
}

test "countLines" {
    try std.testing.expectEqual(@as(usize, 1), countLines("single"));
    try std.testing.expectEqual(@as(usize, 3), countLines("a\nb\nc"));
}

test "isIdent" {
    try std.testing.expect(isIdent('a'));
    try std.testing.expect(isIdent('Z'));
    try std.testing.expect(isIdent('_'));
    try std.testing.expect(isIdent('0'));
    try std.testing.expect(!isIdent(' '));
    try std.testing.expect(!isIdent('-'));
}

test "ImportGraph.isSkippableDir skips dot-prefixed directories" {
    // Hardcoded skip list must still match.
    try std.testing.expect(ImportGraph.isSkippableDir(".git"));
    try std.testing.expect(ImportGraph.isSkippableDir("zig-out"));
    try std.testing.expect(ImportGraph.isSkippableDir("node_modules"));
    try std.testing.expect(ImportGraph.isSkippableDir("vendor"));

    // Regression: any dot-prefixed dir must be skipped. direnv-per-project
    // caches and project-local scratch dirs previously caused recursive
    // traversals to walk thousands of cache entries.
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-global-cache"));
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-cache-ephor"));
    try std.testing.expect(ImportGraph.isSkippableDir(".zig-cache-test"));
    try std.testing.expect(ImportGraph.isSkippableDir(".tmp"));
    try std.testing.expect(ImportGraph.isSkippableDir(".claude"));

    // Non-hidden, non-listed dirs must still be traversable.
    try std.testing.expect(!ImportGraph.isSkippableDir("src"));
    try std.testing.expect(!ImportGraph.isSkippableDir("lib"));
    try std.testing.expect(!ImportGraph.isSkippableDir("tests"));
}

test "main walk prunes dependency dirs with the shared skip predicate (EPH-I0377)" {
    // One skip predicate serves every walk: the main source walk must
    // prune the dependency and build-output dirs the nested discovery
    // walks prune. Pre-fix the main walk used a weaker predicate and
    // analyzed files under these dirs (band-B03 F23).
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    try tmp.dir.createDirPath(std.testing.io, "src");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "src/a.zig",
        .data = "pub fn a() void {}\n",
    });
    try tmp.dir.createDirPath(std.testing.io, "node_modules");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "node_modules/dep.zig",
        .data = "pub fn d() void {}\n",
    });
    try tmp.dir.createDirPath(std.testing.io, "deps");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "deps/dep2.zig",
        .data = "pub fn d2() void {}\n",
    });
    try tmp.dir.createDirPath(std.testing.io, "vendor");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "vendor/v.zig",
        .data = "pub fn v() void {}\n",
    });
    try tmp.dir.createDirPath(std.testing.io, ".build");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = ".build/b.zig",
        .data = "pub fn b() void {}\n",
    });
    try tmp.dir.createDirPath(std.testing.io, ".packages");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = ".packages/p.zig",
        .data = "pub fn p() void {}\n",
    });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    try graph.scanDirectory(root);

    try std.testing.expectEqual(@as(usize, 1), graph.files.count());
    var iter = graph.files.keyIterator();
    try std.testing.expect(mem.endsWith(u8, iter.next().?.*, "/src/a.zig"));
}

test "stats: a trailing newline adds no phantom line or blank (EPH-I0724)" {
    // Pre-fix, countLines counted 1 + count('\n'), so a newline-terminated
    // file reported one extra Total Line, and the splitScalar walk counted
    // the phantom trailing segment as a blank line. A one-line file must
    // read 1 total, 1 code, 0 blank.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "a.zig", .data = "pub fn a() void {}\n" });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "b.zig",
        .data = "pub fn b() void {}\n// comment\n\npub fn c() void {}\n",
    });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    try graph.scanDirectory(root);
    const s = graph.getStats();
    try std.testing.expectEqual(@as(usize, 2), s.total_files);
    try std.testing.expectEqual(@as(usize, 5), s.total_lines);
    try std.testing.expectEqual(@as(usize, 3), s.code_lines);
    try std.testing.expectEqual(@as(usize, 1), s.comment_lines);
    try std.testing.expectEqual(@as(usize, 1), s.blank_lines);
}

test "zero-zig-files scan is a usage error (EPH-I0726)" {
    // A non-zig path argument resolves to zero Zig files. Silent exit 0
    // would read as ran-clean; the run must fail with one diagnostic and
    // the usage-error exit. A scan that finds a Zig file stays silent.
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "notes.txt", .data = "hello\n" });

    var cfg = testConfig();
    defer cfg.deinit(allocator);
    var cache = IgnoreCache.init(allocator);
    defer cache.deinit();
    var ctx = RunCtx{
        .alloc = allocator,
        .cfg = &cfg,
        .diag = &diag,
        .base_path = ".",
        .ignore_cache = &cache,
    };

    // The graph holds zero files after scanning the non-zig path.
    const txt_path = try tmpFilePath(allocator, &tmp, "notes.txt");
    defer allocator.free(txt_path);
    var g = ImportGraph.init(allocator, &diag);
    defer g.deinit();
    g.scan_root = ctx.base_path;
    try scanPath(&g, txt_path);
    try std.testing.expectEqual(@as(usize, 0), g.files.count());
    requireScannedFiles(&ctx, &g);
    try std.testing.expect(ctx.should_exit_error);
    try std.testing.expect(
        mem.indexOf(u8, capture.slice(), "error: no Zig files found at") != null,
    );

    // A Zig file scan does not trip the gate.
    ctx.should_exit_error = false;
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "real.zig",
        .data = "pub fn main() void {}\n",
    });
    const zig_path = try tmpFilePath(allocator, &tmp, "real.zig");
    defer allocator.free(zig_path);
    var g2 = ImportGraph.init(allocator, &diag);
    defer g2.deinit();
    g2.scan_root = ctx.base_path;
    try scanPath(&g2, zig_path);
    try std.testing.expectEqual(@as(usize, 1), g2.files.count());
    requireScannedFiles(&ctx, &g2);
    try std.testing.expect(!ctx.should_exit_error);
}

test "stats file count is the graph count: joined out-of-root entries count once (EPH-I0541)" {
    // The check summary's Files line is the graph count, and the check
    // graph is the scan path UNION the joined entry points (EPH-I0784).
    // A 2-file walk plus one out-of-root entry must total 3 — the count
    // reflects the union, never a doubled scan set. Pre-fix the B15
    // out-of-band note read the union as a doubling.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "a.zig", .data = "pub fn a() void {}\n" });
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "b.zig", .data = "pub fn b() void {}\n" });
    var tmp2 = std.testing.tmpDir(.{});
    defer tmp2.cleanup();
    try tmp2.dir.writeFile(std.testing.io, .{
        .sub_path = "e.zig",
        .data = "pub fn e() void {}\n",
    });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    try graph.scanDirectory(root);
    try std.testing.expectEqual(@as(usize, 2), graph.getStats().total_files);
    // One out-of-root entry joins the graph (the check flow's union).
    const entry_path = try tmp2.dir.realPathFileAlloc(std.testing.io, "e.zig", allocator);
    defer allocator.free(entry_path);
    try graph.scanSingleFile(entry_path);
    try std.testing.expectEqual(@as(usize, 3), graph.getStats().total_files);
}

test "markBuildPathReferences reads with the shared source cap (EPH-I0376)" {
    // The cap-boundary regression pin lives on the LIVE read site
    // (markBuildPathReferences, three production callers): a b.path()
    // ref beyond the old 4 MiB ref-scan cap is found now that the ref
    // scan shares max_source_file_bytes with the main analysis read
    // (band-B03 F21). Pre-fix the read tripped the 4 MiB limit and the
    // ref was silently missed. The per-file ref scanner this pin
    // originally rode was deleted (EPH-I0374 cascade, reviewer r2).
    const allocator = std.testing.allocator;
    var diag = testDiagCtx();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // build.zig makes findBuildRoot resolve to the tmp root; the nested
    // build discovery then finds no subdirectories, so the only marking
    // path for target.zig is the b.path() ref scan itself.
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "build.zig",
        .data = "pub fn build(b: *std.Build) void {}\n",
    });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "target.zig",
        .data = "pub fn t() void {}\n",
    });

    const pad = try allocator.alloc(u8, 4 * 1024 * 1024 + 4096);
    defer allocator.free(pad);
    @memset(pad, ' ');
    const file_content = try std.mem.concat(allocator, u8, &.{ pad, "b.path(\"target.zig\")" });
    defer allocator.free(file_content);
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "big.zig", .data = file_content });

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const root = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(root);
    // Production shape (EPH-I0172): every handler sets the containment
    // root; the null-root fail-closed gate must not mask this fixture.
    graph.scan_root = root;
    const big_path = try std.fmt.allocPrint(allocator, "{s}/big.zig", .{root});
    // The map takes ownership of the key (deinit frees it); the pin must
    // not free it again.
    try graph.reachable.put(big_path, {});

    var cfg = testConfig();
    cfg.path = root;
    try graph.markBuildPathReferences(&cfg);

    const target = try std.fmt.allocPrint(allocator, "{s}/target.zig", .{root});
    defer allocator.free(target);
    try std.testing.expect(graph.reachable.contains(target));
}

