    var h = try initSuppressHarness(&diag, allocator, "src/shape.zig", suppress_leak_source);
    defer h.deinit(allocator);
    const issues = [_]Issue{
        testJsonIssue("src/a.zig", 1, "ZA101"),
        testJsonIssue("src/c.zig", 3, "ZA102"),
    };
