/// Test helper: one warning finding on `file` for the analyzer JSON
/// shape tests (kept narrow so the fixture lines stay under the line cap).
fn testJsonIssue(file: []const u8, line: usize, rule: []const u8) Issue {
    return .{
        .file = file,
        .line = line,
        .col = 1,
        .severity = .warning,
        .rule = rule,
        .message = "finding",
        .help = null,
    };
}

