test "check ZA2 ownership: every dropped CFG ZA2 has an errors twin (EPH-I0174)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // One file with every ZA2 trigger shape the analyzers emit: the six
    // line-based classes (ZA201/204/206/209/210 by analyzeErrors, ZA205
    // by analyzeIgnoredErrors) plus the two the CFG error tier emits
    // (ZA202 catch unreachable, ZA203 orelse unreachable, via
    // runCFGSafetyAnalyses → analyzeCFGErrors). filterMemIssues drops
    // CFG-list ZA2 items because analyzeErrors re-emits each one at the
    // same (file, line); this test pins that twin assumption and the
    // drop mechanism on a live CFG-ZA2 input.
    const content =
        \\const std = @import("std");
        \\fn mayFail() !void {
        \\    return error.Fail;
        \\}
        \\fn work() void {}
        \\fn silentCatch() void {
        \\    mayFail() catch {};
        \\}
        \\fn usesUndefined(allocator: std.mem.Allocator) void {
        \\    var x: u32 = undefined;
        \\    _ = x;
        \\    _ = allocator;
        \\}
        \\fn ignoredError() void {
        \\    _ = mayFail();
        \\}
        \\fn exitsBypassingDefer() void {
        \\    defer work();
        \\    std.process.exit(1);
        \\}
        \\fn neverFails() !void {
        \\    work();
        \\}
        \\fn verboseTry() !void {
        \\    mayFail() catch |e| return e;
        \\}
        \\fn catchesUnreachable() void {
        \\    const v = mayFail() catch unreachable;
        \\    _ = v;
        \\}
        \\fn orelseUnreachable(p: ?*u8) u8 {
        \\    const x = p orelse unreachable;
        \\    return x.*;
        \\}
    ;
    var run = try runErrorsCheck(&diag, allocator, "za2_ownership.zig", content);
    defer run.deinit(allocator);

    // Half one: the line-based error analyzers emit every class they own.
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za2_ownership.zig", RULE_SILENT_CATCH),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za2_ownership.zig", RULE_UNDEFINED_USAGE),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za2_ownership.zig", RULE_EXIT_BYPASSES_DEFER),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za2_ownership.zig", RULE_USELESS_ERROR_RETURN),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(run.issues.items, "za2_ownership.zig", RULE_NO_CATCH_RETURN),
    );

    // ZA205 rides the ignored-errors analyzer, which feeds its own list
    // in the .check pipeline — outside the CFG drop entirely.
    var ignored = try analyzeIgnoredErrors(allocator, &run.graph);
    defer deinitIssues(&ignored, allocator);
    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(ignored.items, "za2_ownership.zig", RULE_IGNORED_ERROR),
    );

    // Half two: the CFG list CAN carry ZA2 items — the CFG error tier
    // emits ZA202/ZA203 on this fixture — and filterMemIssues drops
    // them. Pin both halves of the drop's guarantee: every dropped CFG
    // ZA2 item has a same-(file, line, rule) twin in the errors list,
    // and the drop is the only thing keeping ZA2 out of the buckets.
    var cfg_issues = try analyzeCFGMemory(allocator, &run.graph);
    defer deinitIssues(&cfg_issues, allocator);

    // Positive control: the fixture triggers both CFG ZA2 emitters, so
    // the twin and bucket assertions below run on a non-empty input.
    try std.testing.expect(countRuleIssues(
        cfg_issues.items,
        "za2_ownership.zig",
        RULE_CATCH_UNREACHABLE,
    ) > 0);
    try std.testing.expect(countRuleIssues(
        cfg_issues.items,
        "za2_ownership.zig",
        RULE_ORELSE_UNREACHABLE,
    ) > 0);

    for (cfg_issues.items) |cfg_issue| {
        if (!mem.startsWith(u8, cfg_issue.rule, "ZA2")) continue;
        var twin = false;
        for (run.issues.items) |err_issue| {
            if (mem.eql(u8, err_issue.rule, cfg_issue.rule) and
                mem.eql(u8, err_issue.file, cfg_issue.file) and
                err_issue.line == cfg_issue.line)
            {
                twin = true;
                break;
            }
        }
        // A CFG-only ZA2 class would vanish in the drop: the errors twin
        // is what keeps the finding visible (EPH-I0174).
        try std.testing.expect(twin);
    }

    var filtered = try filterMemIssues(allocator, cfg_issues.items);
    defer filtered.deinit(allocator);
    for (filtered.mem_only.items) |issue|
        try std.testing.expect(!mem.startsWith(u8, issue.rule, "ZA2"));
    for (filtered.null_safety.items) |issue|
        try std.testing.expect(!mem.startsWith(u8, issue.rule, "ZA2"));
    for (filtered.panic.items) |issue|
        try std.testing.expect(!mem.startsWith(u8, issue.rule, "ZA2"));
}

test "memory command filter keeps only the ZA1 memory family (EPH-I0723)" {
    // The memory command shares the CFG pass with check, and that pass
    // emits the error tier (ZA202), the definite-assignment rule (ZA607),
    // and the null-safety/panic families beside the memory findings. The
    // command's promise is the memory category, so filterMemoryFamily
    // must drop every non-ZA1 rule. The pre-filter asserts pin that the
    // fixture really produced the leak families: the filter, not a
    // missing emission, is what narrows the list.
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const content =
        \\fn mayFail() !void {
        \\    return error.Fail;
        \\}
        \\fn leak(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\    _ = buf;
        \\}
        \\fn catchesUnreachable() void {
        \\    const v = mayFail() catch unreachable;
        \\    _ = v;
        \\}
        \\fn use(v: u32) void {
        \\    _ = v;
        \\}
        \\fn whileElseBreak(c: bool, d: bool) void {
        \\    var x: u32 = undefined;
        \\    while (c) {
        \\        if (d) {
        \\            break;
        \\        }
        \\        x = 1;
        \\    } else {
        \\        x = 2;
        \\    }
        \\    use(x);
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "memory_filter.zig", content);
    defer run.deinit(allocator);

    const file = "memory_filter.zig";
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_DEFER) == 1);
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_CATCH_UNREACHABLE) == 1);
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_DEFINITE_ASSIGNMENT) == 1);

    filterMemoryFamily(&run.issues, allocator);
    try std.testing.expectEqual(@as(usize, 1), run.issues.items.len);
    try std.testing.expectEqualStrings(RULE_ALLOC_NO_DEFER, run.issues.items[0].rule);
}

test "countOutOfRootEntries counts only .zig entries outside the scan path (EPH-I0784)" {
    const diag = testDiagCtx();
    // The scan path covers its own tree: nothing joins.
    try std.testing.expectEqual(@as(usize, 0), countOutOfRootEntries(diag.io, "src", &.{}));
    try std.testing.expectEqual(
        @as(usize, 0),
        countOutOfRootEntries(diag.io, "src", &.{"src/main.zig"}),
    );
    try std.testing.expectEqual(@as(usize, 0), countOutOfRootEntries(
        diag.io,
        "src/main.zig",
        &.{"src/main.zig"},
    ));
    // Out-of-root .zig entries join. A non-.zig name never reaches the
    // graph (scanSingleFile filter), so it does not count.
    try std.testing.expectEqual(@as(usize, 2), countOutOfRootEntries(
        diag.io,
        "src",
        &.{ "build.zig", "tools/gen.zig", "README.md" },
    ));
    // Component boundary (RED4-3): a sibling prefix is outside, not inside.
    try std.testing.expectEqual(
        @as(usize, 1),
        countOutOfRootEntries(diag.io, "src", &.{"src-evil/x.zig"}),
    );
    // Duplicates count once per occurrence: the --entry and config appends
    // do not dedup, so a doubled entry over-reports (never under-reports).
    try std.testing.expectEqual(@as(usize, 2), countOutOfRootEntries(
        diag.io,
        "src",
        &.{ "tools/gen.zig", "tools/gen.zig" },
    ));
}

test "entryCoveredByScan folds alternate spellings of one file (EPH-I0812)" {
    const diag = testDiagCtx();
    // Real-file fixture created in the invocation cwd (EPH-I0575): the
    // absolute and infix-dot spellings resolve to the relative form's
    // realpath, so all three count as covered. The fixture is created
    // here, not assumed, and deleted after.
    var cwd = std.Io.Dir.cwd();
    try cwd.createDirPath(std.testing.io, "ephor-i0812-spell/src");
    defer cwd.deleteTree(std.testing.io, "ephor-i0812-spell") catch {};
    try cwd.writeFile(std.testing.io, .{
        .sub_path = "ephor-i0812-spell/src/main.zig",
        .data = "pub fn main() void {}\n",
    });
    try cwd.writeFile(std.testing.io, .{
        .sub_path = "ephor-i0812-spell/src/types.zig",
        .data = "pub fn main() void {}\n",
    });
    var buf: [Fs.max_path_bytes]u8 = undefined;
    const abs = try Fs.cwd(diag.io).realpath("ephor-i0812-spell/src/main.zig", &buf);
    var cwd_buf: [Fs.max_path_bytes]u8 = undefined;
    const cwd_real = try Fs.cwd(diag.io).realpath(".", &cwd_buf);
    const infix = try std.fmt.allocPrint(
        std.testing.allocator,
        "{s}/./ephor-i0812-spell/src/main.zig",
        .{cwd_real},
    );
    defer std.testing.allocator.free(infix);
    try std.testing.expect(entryCoveredByScan(
        diag.io,
        "ephor-i0812-spell/src/main.zig",
        "ephor-i0812-spell/src/main.zig",
    ));
    try std.testing.expect(entryCoveredByScan(diag.io, abs, "ephor-i0812-spell/src/main.zig"));
    try std.testing.expect(entryCoveredByScan(diag.io, infix, "ephor-i0812-spell/src/main.zig"));
    // A different physical file is not covered.
    try std.testing.expect(!entryCoveredByScan(diag.io, abs, "ephor-i0812-spell/src/types.zig"));
    // Both sides resolve here: the realpath pair decides (the dir covers
    // the file).
    try std.testing.expect(entryCoveredByScan(
        diag.io,
        "ephor-i0812-spell/src",
        "ephor-i0812-spell/src/main.zig",
    ));
    // Unresolvable paths fall back to the textual test.
    try std.testing.expect(!entryCoveredByScan(diag.io, "main.zig", "other.zig"));
}

