test "extractQuotedPath accepts stdlib-named project files (EPH-I0529)" {
    // "std.zig" and "builtin_extra.zig" are relative file imports, not
    // stdlib names (verified against the 0.16.0 compiler: @import("std")
    // and @import("builtin") are the only package forms, and the .zig
    // suffix gate rejects both). Pre-fix, startsWith("std")/"builtin"
    // refused these entries; zls carries a real @import("std.zig").
    try std.testing.expectEqualStrings(
        "stdfoo.zig",
        extractQuotedPath("@import(\"stdfoo.zig\")", 9).?,
    );
    try std.testing.expectEqualStrings(
        "std.zig",
        extractQuotedPath("b.path(\"std.zig\")", 8).?,
    );
    try std.testing.expectEqualStrings(
        "builtin_extra.zig",
        extractQuotedPath("b.path(\"builtin_extra.zig\")", 8).?,
    );
    // The bare stdlib package names stay rejected by the suffix gate.
    try std.testing.expectEqual(
        @as(?[]const u8, null),
        extractQuotedPath("@import(\"std\")", 9),
    );
    try std.testing.expectEqual(
        @as(?[]const u8, null),
        extractQuotedPath("@import(\"builtin\")", 9),
    );
}

test "pathJoin beyond the segment cap fails closed (EPH-I0533)" {
    const allocator = std.testing.allocator;
    // 17 segments: the parse stops at 16 ("p.zig") with "q" still
    // ahead, so the join is truncated. The .zig suffix is deliberate:
    // pre-fix, the 16 segments joined to ".../o/p.zig", which passes
    // the join's .zig gate and returns a wrong path — either a silent
    // miss or a wrong existing file. Fail-closed: null. The old a..q
    // fixture never reached the join and passed on the broken code
    // (OPS-I0198 masked-fixture class).
    const line =
        "pathJoin(&.{ \"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\", \"h\"," ++
        " \"i\", \"j\", \"k\", \"l\", \"m\", \"n\", \"o\", \"p.zig\", \"q\" })";
    const start = mem.indexOfScalar(u8, line, '{').?;
    try std.testing.expectEqual(
        @as(?[]const u8, null),
        try extractPathJoin(allocator, line, start),
    );
}

test "pathJoin at the segment cap with a trailing comma is not truncated (EPH-I0533)" {
    const allocator = std.testing.allocator;
    const line =
        "pathJoin(&.{ \"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\", \"h\"," ++
        " \"i\", \"j\", \"k\", \"l\", \"m\", \"n\", \"o\", \"p.zig\", })";
    const start = mem.indexOfScalar(u8, line, '{').?;
    const joined = (try extractPathJoin(allocator, line, start)).?;
    defer allocator.free(joined);
    // A trailing comma after a complete 16-segment parse leaves no quote
    // in the remainder: not truncation, the join is complete.
    try std.testing.expectEqualStrings("a/b/c/d/e/f/g/h/i/j/k/l/m/n/o/p.zig", joined);
}

test "isKnownIssue matches file paths beyond 512 bytes (EPH-I0532)" {
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    // A path longer than the old 512-byte key buffer: bufPrint failed
    // and isKnownIssue returned false — the finding always printed, the
    // suppression never matched. The no-format compare has no key size.
    const long_file = try allocator.alloc(u8, 600);
    defer allocator.free(long_file);
    @memset(long_file, 'a');
    try cfg.known_issues.append(
        allocator,
        try std.fmt.allocPrint(allocator, "{s}:{d}", .{ long_file, 42 }),
    );
    const issue = Issue{
        .file = long_file,
        .line = 42,
        .col = 1,
        .severity = .warning,
        .rule = "ZA101",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(issue, &cfg));
    const other_line = Issue{
        .file = long_file,
        .line = 43,
        .col = 1,
        .severity = .warning,
        .rule = "ZA101",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(other_line, &cfg));
    // A file path containing ':' still matches: the line number is the
    // last colon-separated field.
    const colon_file = "dir:part/main.zig";
    try cfg.known_issues.append(
        allocator,
        try std.fmt.allocPrint(allocator, "{s}:{d}", .{ colon_file, 7 }),
    );
    const colon_issue = Issue{
        .file = colon_file,
        .line = 7,
        .col = 1,
        .severity = .warning,
        .rule = "ZA101",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(colon_issue, &cfg));
    // A three-field entry ("file:line:rule") suppresses only the named
    // rule (EPH-I0158). Pre-fix the suffix made the whole key never
    // match — the line part did not parse as a number and the key was
    // skipped. The matching rule is now suppressed, a different rule on
    // the same line still reports, and the same rule on another line
    // still reports.
    try cfg.known_issues.append(allocator, try allocator.dupe(u8, "plain.zig:3:ZA101"));
    const rule_issue = Issue{
        .file = "plain.zig",
        .line = 3,
        .col = 1,
        .severity = .warning,
        .rule = "ZA101",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(rule_issue, &cfg));
    const other_rule_issue = Issue{
        .file = "plain.zig",
        .line = 3,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(other_rule_issue, &cfg));
    const other_line_issue = Issue{
        .file = "plain.zig",
        .line = 4,
        .col = 1,
        .severity = .warning,
        .rule = "ZA101",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(other_line_issue, &cfg));
    // The 2-field form stays all-rules: a different rule on the pinned
    // line is still suppressed.
    const two_field_other_rule = Issue{
        .file = long_file,
        .line = 42,
        .col = 1,
        .severity = .warning,
        .rule = "ZA306",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(two_field_other_rule, &cfg));
}

test "known-issue keys match across the ./ display prefix (EPH-I0738)" {
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try cfg.known_issues.append(allocator, try allocator.dupe(u8, "src/bad.zig:8"));
    // `ephor check .` prints `./src/bad.zig:8`: the hand-written key
    // without the ./ prefix must match (the audit's silent-miss shape).
    const dot_issue = Issue{
        .file = "./src/bad.zig",
        .line = 8,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(dot_issue, &cfg));
    // The reverse: a ./ prefixed key matches the plain rendered path.
    try cfg.known_issues.append(allocator, try allocator.dupe(u8, "./lib/x.zig:3"));
    const plain_issue = Issue{
        .file = "lib/x.zig",
        .line = 3,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(isKnownIssue(plain_issue, &cfg));
    // The line number still discriminates across the prefix strip.
    const wrong_line = Issue{
        .file = "./src/bad.zig",
        .line = 9,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(wrong_line, &cfg));
}

test "known-issue keys stay byte-exact beyond the ./ prefix (EPH-I0738)" {
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try cfg.known_issues.append(allocator, try allocator.dupe(u8, "src/bad.zig:8"));
    // A `../` prefix and a different dir are different paths: the strip
    // covers the invocation-cwd rendering delta, never path identity.
    const parent_issue = Issue{
        .file = "../src/bad.zig",
        .line = 8,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(parent_issue, &cfg));
    const other_dir_issue = Issue{
        .file = "other/src/bad.zig",
        .line = 8,
        .col = 1,
        .severity = .warning,
        .rule = "ZA201",
        .message = "m",
        .help = null,
    };
    try std.testing.expect(!isKnownIssue(other_dir_issue, &cfg));
}

test "isValidZigImport keeps the .zig gate (EPH-I0527)" {
    // The std/builtin equality checks were unreachable: the suffix gate
    // already rejects both names, so the visible behavior is unchanged
    // after their deletion (A/B: byte-identical corpus expected).
    try std.testing.expect(isValidZigImport("src/main.zig"));
    try std.testing.expect(!isValidZigImport("src/main.txt"));
    try std.testing.expect(!isValidZigImport("std"));
    try std.testing.expect(!isValidZigImport("builtin"));
}

test "joinPathSegments guards the empty slice and propagates OOM (EPH-I0528)" {
    const allocator = std.testing.allocator;
    // Empty segments: the pre-fix `segments.len - 1` underflowed (usize
    // wraps to max) and only the caller-side count==0 guard saved it.
    try std.testing.expectEqual(
        @as(?[]const u8, null),
        try joinPathSegments(allocator, &.{}, 0),
    );
    // A non-.zig join returns null, allocation freed.
    try std.testing.expectEqual(
        @as(?[]const u8, null),
        try joinPathSegments(allocator, &.{"a.txt"}, 5),
    );
    // Happy path unchanged.
    const joined = (try joinPathSegments(allocator, &.{ "src", "main.zig" }, 11)).?;
    defer allocator.free(joined);
    try std.testing.expectEqualStrings("src/main.zig", joined);
    // OOM propagates as OutOfMemory, never "not a path".
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    try std.testing.expectError(
        error.OutOfMemory,
        joinPathSegments(failing.allocator(), &.{"a.zig"}, 5),
    );
}

test "parseCommand maps the bare version word (EPH-I0544)" {
    // The bare word is the most common version-query spelling; pre-fix it
    // fell through to the path latch and died with FileNotFound plus a
    // misleading outside-root note.
    try std.testing.expectEqual(
        Command.version,
        parseCommand("version") orelse return error.TestUnexpectedResult,
    );
    // The flag spellings still map.
    try std.testing.expectEqual(
        Command.version,
        parseCommand("--version") orelse return error.TestUnexpectedResult,
    );
    try std.testing.expectEqual(
        Command.version,
        parseCommand("-v") orelse return error.TestUnexpectedResult,
    );
    // An unknown word still falls through to the path latch.
    try std.testing.expect(parseCommand("src") == null);
}

test "parseCommandIntoArgv parses tokens within the buffer" {
    var buf: [64][]const u8 = undefined;
    var scratch: [1024]u8 = undefined;
    const parsed = parseCommandIntoArgv("zig build test", &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 3), parsed.argc);
    try std.testing.expect(!parsed.truncated);
    try std.testing.expectEqualStrings("zig", buf[0]);
    try std.testing.expectEqualStrings("build", buf[1]);
    try std.testing.expectEqualStrings("test", buf[2]);
}

test "parseCommandIntoArgv strips quotes and honors escapes (EPH-I0507)" {
    var buf: [64][]const u8 = undefined;
    var scratch: [1024]u8 = undefined;
    // The band-B12 F20 shape: `--command 'run "a b"'` must pass `a b` to
    // the child without the quote bytes, and `\'`/`\"` escapes stay
    // literal bytes in any quote state.
    const parsed = parseCommandIntoArgv("zig run \"a b\" 'c\\'d'", &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 4), parsed.argc);
    try std.testing.expect(!parsed.truncated);
    try std.testing.expectEqualStrings("zig", buf[0]);
    try std.testing.expectEqualStrings("run", buf[1]);
    try std.testing.expectEqualStrings("a b", buf[2]);
    try std.testing.expectEqualStrings("c'd", buf[3]);
    // An inner single quote inside a string literal is a literal byte
    // inside double quotes, so quoting does not end early.
    const parsed2 = parseCommandIntoArgv("echo \"it's\"", &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 2), parsed2.argc);
    try std.testing.expect(!parsed2.truncated);
    try std.testing.expectEqualStrings("it's", buf[1]);
}

test "parseCommandIntoArgv unclosed quote consumes the tail; tabs split (EPH-I0244)" {
    var buf: [64][]const u8 = undefined;
    var scratch: [1024]u8 = undefined;
    // An unterminated quote consumes the rest of the command as one
    // token; the quote byte itself is stripped (the d383904 guarantee,
    // EPH-I0244). The pre-fix tokenizer kept the quote bytes and lumped
    // the remainder into the last token silently.
    const parsed = parseCommandIntoArgv("\"echo", &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 1), parsed.argc);
    try std.testing.expect(!parsed.truncated);
    try std.testing.expectEqualStrings("echo", buf[0]);
    // A tab splits unquoted tokens exactly like a space; inside quotes a
    // tab is a literal byte.
    const parsed2 = parseCommandIntoArgv("a\tb\t\"c\td\"", &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 3), parsed2.argc);
    try std.testing.expectEqualStrings("a", buf[0]);
    try std.testing.expectEqualStrings("b", buf[1]);
    try std.testing.expectEqualStrings("c\td", buf[2]);
}

test "parseCommandIntoArgv fits exactly 64 tokens without truncation" {
    const allocator = std.testing.allocator;
    var cmd: std.ArrayListUnmanaged(u8) = .empty;
    defer cmd.deinit(allocator);
    for (0..64) |i| {
        if (i > 0) try cmd.append(allocator, ' ');
        try cmd.append(allocator, 'x');
    }
    var buf: [64][]const u8 = undefined;
    var scratch: [1024]u8 = undefined;
    const parsed = parseCommandIntoArgv(cmd.items, &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 64), parsed.argc);
    try std.testing.expect(!parsed.truncated);
}

test "parseCommandIntoArgv truncates token 65 instead of overflowing" {
    // RED5-1: 70 tokens previously wrote past the [64] stack buffer.
    const allocator = std.testing.allocator;
    var cmd: std.ArrayListUnmanaged(u8) = .empty;
    defer cmd.deinit(allocator);
    for (0..70) |i| {
        if (i > 0) try cmd.append(allocator, ' ');
        try cmd.appendSlice(allocator, "tok");
    }
    var buf: [64][]const u8 = undefined;
    var scratch: [1024]u8 = undefined;
    const parsed = parseCommandIntoArgv(cmd.items, &buf, &scratch);
    try std.testing.expectEqual(@as(usize, 64), parsed.argc);
    try std.testing.expect(parsed.truncated);
    try std.testing.expectEqualStrings("tok", buf[63]);
}

test "parseCommandIntoArgv truncates on a scratch byte cap (EPH-I0507)" {
    var buf: [64][]const u8 = undefined;
    var scratch: [4]u8 = undefined;
    const parsed = parseCommandIntoArgv("abcdef", &buf, &scratch);
    try std.testing.expect(parsed.truncated);
}

// ============================================================================
// Runtime analysis tests (ZR1xx, EPH-I0230, EPH-I0231, EPH-I0232)
// ============================================================================

/// Run classifyGPALine on the first line of `input` with the rest of the
/// input as the live iterator, mirroring parseGPADiagnostics.
fn runClassifyGPALine(allocator: Allocator, input: []const u8) !std.ArrayListUnmanaged(Issue) {
    var issues: std.ArrayListUnmanaged(Issue) = .empty;
    errdefer deinitIssues(&issues, allocator);
    var iter = mem.splitScalar(u8, input, '\n');
    const first = iter.next() orelse return issues;
    const ctx = RuntimeEmitCtx{ .issues = &issues, .allocator = allocator };
    try classifyGPALine(ctx, &iter, false, first);
    return issues;
}

test "extractFileLocation parses file:line shapes" {
    const Case = struct { input: []const u8, file: []const u8, line: usize };
    const cases = [_]Case{
        .{ .input = "/a/b.zig:12:3: 0x1 in foo", .file = "/a/b.zig", .line = 12 },
        .{ .input = "src/main.zig:42", .file = "src/main.zig", .line = 42 },
        .{ .input = "no location here", .file = "unknown", .line = 0 },
        .{ .input = "x.zig:notdigits", .file = "x.zig", .line = 0 },
        // A bare .zig name at end of input matches: the suffix bound reads
        // <=, so the file is located with no line number (band-B12 F23).
        .{ .input = "bare.zig", .file = "bare.zig", .line = 0 },
        // Line numbers that overflow usize read as no location (null), so
        // the fallback anchors at the file with line 0 (band-B12 F23).
        .{ .input = "x.zig:99999999999999999999999999999 x", .file = "x.zig", .line = 0 },
        // The first .zig match wins, even when a later one carries the
        // line number.
        .{ .input = "a.zig b.zig:5", .file = "a.zig", .line = 0 },
    };
    for (cases) |c| {
        const loc = extractFileLocation(c.input);
        try std.testing.expectEqualStrings(c.file, loc.file);
        try std.testing.expectEqual(c.line, loc.line);
    }
}

test "parseLocationLine parses the :NN suffix after a file name" {
    try std.testing.expectEqual(@as(?usize, 123), parseLocationLine("f.zig:123:45", 5));
    try std.testing.expectEqual(@as(?usize, 0), parseLocationLine("f.zig:0", 5));
    try std.testing.expectEqual(@as(?usize, null), parseLocationLine("f.zig:", 5));
    try std.testing.expectEqual(@as(?usize, null), parseLocationLine("f.zig:abc", 5));
    try std.testing.expectEqual(@as(?usize, null), parseLocationLine("f.zig", 5));
    // Overflowing line numbers read as no location (null), never a fake
    // line 0 (band-B12 F23, EPH-I0508).
    try std.testing.expectEqual(
        @as(?usize, null),
        parseLocationLine("f.zig:99999999999999999999999999", 5),
    );
}

test "classifyGPALine routes every gpa_classifications pattern to its rule" {
    const allocator = std.testing.allocator;
    for (gpa_classifications) |cls| {
        for (cls.patterns) |pat| {
            const line = try std.fmt.allocPrint(allocator, "err: {s} in /t.zig:7", .{pat});
            defer allocator.free(line);
            var issues = try runClassifyGPALine(allocator, line);
            defer deinitIssues(&issues, allocator);
            try std.testing.expectEqual(@as(usize, 1), issues.items.len);
            try std.testing.expectEqualStrings(cls.rule, issues.items[0].rule);
            try std.testing.expectEqualStrings(cls.message, issues.items[0].message);
        }
    }
}

test "classifyGPALine pins hard-coded rules for two table rows (band-T01 F8, EPH-I0555)" {
    // The routing test reads the rule and message from the same table
    // row, so a row mapped to the wrong rule stays green. These literals
    // pin the table content independently of the table.
    const allocator = std.testing.allocator;
    {
        var issues = try runClassifyGPALine(allocator, "err: double free in /t.zig:7");
        defer deinitIssues(&issues, allocator);
        try std.testing.expectEqual(@as(usize, 1), issues.items.len);
        try std.testing.expectEqualStrings("ZR102", issues.items[0].rule);
        try std.testing.expectEqualStrings(
            "double free detected at runtime",
            issues.items[0].message,
        );
    }
    {
        var issues = try runClassifyGPALine(allocator, "err: Segmentation fault at address 0x0");
        defer deinitIssues(&issues, allocator);
        try std.testing.expectEqual(@as(usize, 1), issues.items.len);
        try std.testing.expectEqualStrings("ZR105", issues.items[0].rule);
        try std.testing.expectEqualStrings(
            "segmentation fault - invalid memory access",
            issues.items[0].message,
        );
    }
}

test "classifyGPALine honors the located flag of each classification" {
    const allocator = std.testing.allocator;
    const Case = struct {
        input: []const u8,
        rule: []const u8,
        file: []const u8,
        line: usize,
    };
    const cases = [_]Case{
        // Located classes take file:line from the diagnostic line itself.
        .{
            .input = "Double free at /x/y.zig:9 now",
            .rule = RULE_RUNTIME_DOUBLE_FREE,
            .file = "/x/y.zig",
            .line = 9,
        },
        .{
            .input = "use after free in /z.zig:3",
            .rule = RULE_RUNTIME_USE_AFTER_FREE,
            .file = "/z.zig",
            .line = 3,
        },
        .{
            .input = "Invalid free of /a.zig:5",
            .rule = RULE_RUNTIME_DOUBLE_FREE,
            .file = "/a.zig",
            .line = 5,
        },
        // Non-located classes anchor at the synthetic "runtime" file.
        .{
            .input = "Segmentation fault at address 0x0",
            .rule = RULE_RUNTIME_PANIC,
            .file = "runtime",
            .line = 1,
        },
        .{
            .input = "stack overflow in deepRecursion",
            .rule = RULE_RUNTIME_PANIC,
            .file = "runtime",
            .line = 1,
        },
        .{
            .input = "OutOfMemory while growing",
            .rule = RULE_RUNTIME_PANIC,
            .file = "runtime",
            .line = 1,
        },
    };
    for (cases) |c| {
        var issues = try runClassifyGPALine(allocator, c.input);
        defer deinitIssues(&issues, allocator);
        try std.testing.expectEqual(@as(usize, 1), issues.items.len);
        try std.testing.expectEqualStrings(c.rule, issues.items[0].rule);
        try std.testing.expectEqualStrings(c.file, issues.items[0].file);
        try std.testing.expectEqual(c.line, issues.items[0].line);
        try std.testing.expectEqual(Severity.err, issues.items[0].severity);
    }
}

test "classifyGPALine stays silent on an unmatched line" {
    const allocator = std.testing.allocator;
    var issues = try runClassifyGPALine(allocator, "1/1 tests passed");
    defer deinitIssues(&issues, allocator);
    try std.testing.expectEqual(@as(usize, 0), issues.items.len);
}

