    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // The positive half of the containment gate: a panic whose frame path
    // resolves under the scan root keeps its location through the
    // subprocess seam. The path is the repo's own src/main.zig (the test
    // cwd), resolved so the fixture stays hermetic.
    var abs_buf: [Fs.max_path_bytes]u8 = undefined;
    const abs_src = Fs.cwd(std.testing.io).realpath("src/main.zig", &abs_buf) catch
        return error.SkipZigTest;
    const script_body = try std.fmt.allocPrint(
        allocator,
        "echo 'thread 1 panic: boom at {s}:42 now' >&2\nexit 1\n",
        .{abs_src},
    );
    defer allocator.free(script_body);
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "panic2.sh", .data = script_body });
    const script = try tmpFilePath(allocator, &tmp, "panic2.sh");
    defer allocator.free(script);
    const cmd = try std.fmt.allocPrint(allocator, "sh {s}", .{script});
    defer allocator.free(cmd);

    var issues = try runRuntimeAnalysis(
        std.testing.io,
        allocator,
        ".",
        .{ .verbose = false, .custom_command = cmd },
    );
    defer deinitIssues(&issues, allocator);

    try std.testing.expectEqual(@as(usize, 1), issues.items.len);
    try std.testing.expectEqualStrings(RULE_RUNTIME_PANIC, issues.items[0].rule);
    try std.testing.expectEqualStrings(abs_src, issues.items[0].file);
    try std.testing.expectEqual(@as(usize, 42), issues.items[0].line);
}

test "runRuntimeAnalysis reports a located ZR101 for child GPA leak text (band-T01 F6)" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // band-T01 F6 (EPH-I0554): the GPA diagnostics parse path had no
    // subprocess-level pin — family C unit tests covered the parser, but
    // nothing wired child stderr through runRuntimeAnalysis to a ZR101
    // finding. The 0.16 leak shape: the header names the leak and the
    // next line carries the stack-frame location the parser borrows.
    const script_body =
        \\echo 'error(gpa): memory address 0x104000000 leaked:' >&2
        \\echo '/x/proj/src/main.zig:7:9: 0x104000123 in leaky (test)' >&2
        \\exit 1
    ;
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "leak.sh", .data = script_body });
    const script = try tmpFilePath(allocator, &tmp, "leak.sh");
    defer allocator.free(script);
    const cmd = try std.fmt.allocPrint(allocator, "sh {s}", .{script});
    defer allocator.free(cmd);

    var issues = try runRuntimeAnalysis(
        std.testing.io,
        allocator,
        ".",
        .{ .verbose = false, .custom_command = cmd },
    );
    defer deinitIssues(&issues, allocator);

    // The leak header plus its location line yield exactly one leak
    // finding; the nonzero exit must not add a bare ZR104. EPH-I0171
    // (re-derived pin, B86): the forged location fails the containment
    // gate, so the finding keeps the generic message instead of
    // embedding the forged path.
    try std.testing.expectEqual(@as(usize, 1), issues.items.len);
    try std.testing.expectEqualStrings(RULE_RUNTIME_MEMORY_LEAK, issues.items[0].rule);
    try std.testing.expectEqualStrings("memory leak detected at runtime", issues.items[0].message);
    try std.testing.expect(!issues.items[0].message_owned);
}

test "runRuntimeAnalysis embeds an in-root leak location in the ZR101 message (EPH-I0171)" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // The positive half: a leak frame path that resolves under the scan
    // root stays in the owned message. The path is the repo's own
    // src/main.zig resolved from the test cwd.
    var abs_buf: [Fs.max_path_bytes]u8 = undefined;
    const abs_src = Fs.cwd(std.testing.io).realpath("src/main.zig", &abs_buf) catch
        return error.SkipZigTest;
    const script_body = try std.fmt.allocPrint(
        allocator,
        "echo 'error(gpa): memory address 0x104000000 leaked:' >&2\necho '{s}:7:9: 0x104000123 in leaky (test)' >&2\nexit 1\n",
        .{abs_src},
    );
    defer allocator.free(script_body);
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "leak2.sh", .data = script_body });
    const script = try tmpFilePath(allocator, &tmp, "leak2.sh");
    defer allocator.free(script);
    const cmd = try std.fmt.allocPrint(allocator, "sh {s}", .{script});
    defer allocator.free(cmd);

    var issues = try runRuntimeAnalysis(
        std.testing.io,
        allocator,
        ".",
        .{ .verbose = false, .custom_command = cmd },
    );
    defer deinitIssues(&issues, allocator);

    try std.testing.expectEqual(@as(usize, 1), issues.items.len);
    try std.testing.expectEqualStrings(RULE_RUNTIME_MEMORY_LEAK, issues.items[0].rule);
    const expected_msg = try std.fmt.allocPrint(allocator, "memory leak at {s}:7", .{abs_src});
    defer allocator.free(expected_msg);
    try std.testing.expectEqualStrings(expected_msg, issues.items[0].message);
    try std.testing.expect(issues.items[0].message_owned);
}

test "runRuntimeAnalysis frees the partial findings list on a mid-parse failure" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // EPH-I0767: located findings on both streams force payload
    // allocations in both parsers, so an allocation failure mid-parse
    // unwinds holding a partial list of owned findings.
    const script_body =
        \\echo 'thread 1 panic: boom at /x/proj/src/main.zig:42 now'
        \\echo 'double free at /y/proj/src/lib.zig:9:3' >&2
    ;
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "emit.sh", .data = script_body });
    const script = try tmpFilePath(allocator, &tmp, "emit.sh");
    defer allocator.free(script);
    const cmd = try std.fmt.allocPrint(allocator, "sh {s}", .{script});
    defer allocator.free(cmd);

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run), the IgnoreCache
    // sweep pattern.
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    {
        var issues = try runRuntimeAnalysis(
            std.testing.io,
            probe.allocator(),
            ".",
            .{ .verbose = false, .custom_command = cmd },
        );
        deinitIssues(&issues, probe.allocator());
    }
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        if (runRuntimeAnalysis(
            std.testing.io,
            failing.allocator(),
            ".",
            .{ .verbose = false, .custom_command = cmd },
        )) |issues| {
            var list = issues;
            deinitIssues(&list, failing.allocator());
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
        }
        // Byte balance at every failure point is the leak proof. Pre-fix
        // the mid-parse indices drop the partial list (EPH-I0767).
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

// ============================================================================
// Phase 4: CFG Memory Analysis Tests (ZA105, ZA106)
// ============================================================================

/// Helper to create test FileAnalysis with content
fn createTestFileAnalysis(
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !FileAnalysis {
    const path_copy = try allocator.dupe(u8, path);
    // The content dupe can fail: free the path on that path so the
    // FailingAllocator sweeps over this seam stay byte-balanced
    // (EPH-I0895).
    errdefer allocator.free(path_copy);
    return .{
        .path = path_copy,
        .resolved_path = path_copy,
        .imports = .empty,
        .content = try allocator.dupe(u8, content),
        .has_tests = false,
        .pub_function_count = 0,
        .line_count = countLines(content),
        .is_generated = detectGeneratedHeader(content),
    };
}

/// Graph + issues from running the CFG memory pipeline on one in-memory file.
const CFGTestRun = struct {
    graph: ImportGraph,
    issues: std.ArrayListUnmanaged(Issue),

    fn deinit(self: *CFGTestRun, allocator: Allocator) void {
        self.graph.deinit();
        deinitIssues(&self.issues, allocator);
    }
};

/// Test helper: build a one-file graph and run the full CFG memory pipeline.
fn runCFGMemoryTest(
    diag: *DiagCtx,
    allocator: Allocator,
    path: []const u8,
    content: []const u8,
) !CFGTestRun {
    var graph = ImportGraph.init(allocator, diag);
    errdefer graph.deinit();
    const analysis = try createTestFileAnalysis(allocator, path, content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, path), {});
    var issues = try analyzeCFGMemory(allocator, &graph);
    errdefer deinitIssues(&issues, allocator);
    return .{ .graph = graph, .issues = issues };
}

/// One failing-allocator sweep iteration over the CFG memory pipeline:
/// build the one-file graph and run analyzeCFGMemory. An induced
/// OutOfMemory surfaces as an error; the caller asserts byte balance
/// after the run. The graph deinit happens inside, so the caller only
/// checks the allocator ledger (EPH-I0895).
fn sweepCFGMemoryOnce(
    failing: *std.testing.FailingAllocator,
    path: []const u8,
    content: []const u8,
) !void {
    const a = failing.allocator();
    var diag = testDiagCtx();
    var graph = ImportGraph.init(a, &diag);
    defer graph.deinit();
    var analysis = try createTestFileAnalysis(a, path, content);
    var analysis_owned = true;
    defer if (analysis_owned) analysis.deinit(a);
    try graph.files.put(analysis.path, analysis);
    analysis_owned = false;
    var issues = try analyzeCFGMemory(a, &graph);
    deinitIssues(&issues, a);
}

test "ZA105: runCFGMemoryAnalyses frees r1 payloads when appendSlice OOMs (EPH-I0895)" {
    const allocator = std.testing.allocator;
    const path = "sweep_uaf.zig";
    const content =
        \\fn sweep_uaf(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\    allocator.free(buf);
        \\    _ = buf.len;
        \\}
    ;

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run).
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    try sweepCFGMemoryOnce(&probe, path, content);
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        if (sweepCFGMemoryOnce(&failing, path, content)) |_| {
            // Success iteration: the pipeline ran clean under the budget.
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
        }
        // Byte balance at every failure point is the leak proof. Pre-fix
        // the r1 transfer index leaks the message_owned payloads when
        // out.appendSlice OOMs (EPH-I0895).
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

test "scanBlocksForPatterns frees a partial alloc set on alloc failure (EPH-I0241)" {
    // The four array allocs were one struct literal pre-fix: a failure at
    // alloc N leaked allocs 1..N-1 (no errdefer could run before the
    // state bound). The sequential form with the errdefer deinit frees
    // the slices bound so far — the errdefer reads the CURRENT state at
    // scope exit (verified live on zig 0.16.0), and the still-empty
    // slices free as no-ops. SingleFailureAllocator fails exactly ONE
    // allocation and passes the rest through to the leak-checking
    // parent, so a single induced failure inside the alloc sequence is
    // the discriminating shape (std.testing.FailingAllocator latches and
    // would fail every later alloc too).
    const parent = std.testing.allocator;
    var cfg = ControlFlowGraph.init(parent, "probe", 0);
    defer cfg.deinit();
    _ = try cfg.addBlock();
    cfg.blocks.items[0].start_line = 1;
    cfg.blocks.items[0].end_line = 1;
    const lines = [_][]const u8{"allocator.free(buf);"};

    // fail_at is 0-indexed: 0..3 fails each of the four allocs in turn.
    var fail_at: usize = 0;
    while (fail_at < 4) : (fail_at += 1) {
        var single = SingleFailureAllocator{ .parent = parent, .fail_at = fail_at };
        const state = scanBlocksForPatterns(single.allocator(), &cfg, .{
            .lines = &lines,
            .func_line = 1,
            .alloc_name = "buf",
            .owner_vars = &.{},
            .managed_ptr = false,
        }, 1);
        try std.testing.expectError(error.OutOfMemory, state);
        // The leak detector on the parent fires the test when an earlier
        // alloc leaked — the ownership proof, no explicit count needed.
    }
}

test "ZA105: runCFGMemoryAnalyses frees r2 payloads when appendSlice OOMs (EPH-I0895, B45-1)" {
    const allocator = std.testing.allocator;
    const path = "sweep_defer_cap.zig";

    // The over-alloc-cap input (EPH-I0350 probe shape): more allocations
    // than max_mem_family_allocs, fewer lines than the line cap. It makes
    // analyzeCFGDeferCoverage return its alloc-cap skip note — the
    // DeferCoverage family's first message_owned payload — so the r2
    // transfer in runCFGMemoryAnalyses owns a payload that must be freed
    // on an appendSlice OOM (B45-1). One function never exercises that
    // append: the r1 transfer's growth leaves out enough slack, so a
    // later function's r2 append is the first to allocate. Six functions
    // cover the crossing for any ZA103 issue count.
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    const fn_count = 6;
    for (0..fn_count) |f| {
        const header = try std.fmt.allocPrint(
            allocator,
            "fn many{d}(allocator: std.mem.Allocator) !void {{\n",
            .{f},
        );
        defer allocator.free(header);
        try content.appendSlice(allocator, header);
        for (0..max_mem_family_allocs + 8) |i| {
            const line = try std.fmt.allocPrint(
                allocator,
                "    const b{d} = try allocator.alloc(u8, 64);\n",
                .{i},
            );
            defer allocator.free(line);
            try content.appendSlice(allocator, line);
        }
        for (0..max_mem_family_allocs + 8) |i| {
            const line = try std.fmt.allocPrint(allocator, "    _ = b{d};\n", .{i});
            defer allocator.free(line);
            try content.appendSlice(allocator, line);
        }
        try content.appendSlice(allocator, "}\n");
    }

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run).
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    try sweepCFGMemoryOnce(&probe, path, content.items);
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        if (sweepCFGMemoryOnce(&failing, path, content.items)) |_| {
            // Success iteration: the pipeline ran clean under the budget.
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
        }
        // Byte balance at every failure point is the leak proof. Pre-fix
        // the r2 transfer index leaks the alloc-cap note's owned message
        // when out.appendSlice OOMs (EPH-I0895, B45-1).
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

test "safety lists carry no owned payloads (EPH-I0483)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // band-B11 F13: runCFGSafetyAnalyses transfers r1/r2/r3 into out
    // with a bare appendSlice — an owned message in those lists would
    // leak on an OOM at the transfer (the array defer frees only the
    // backing; the B45-1 guards exist exactly for that class). The
    // null-safety, panic-pattern, and error families emit static message
    // strings only, so no guard is needed. This pin fails when a future
    // emission allocates a message into one of the safety lists without
    // adding the owns-payloads guard (see runCFGSafetyAnalyses doc).
    const content =
        \\fn helper() u8 { return 1; }
        \\fn probe(a: std.mem.Allocator, p: ?*u8, i: usize) u8 {
        \\    var q: ?*u8 = p;
        \\    _ = q.*;
        \\    const buf = try a.alloc(u8, 64);
        \\    defer a.free(buf);
        \\    _ = buf[i - 1];
        \\    const x = helper() catch unreachable;
        \\    _ = x;
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "sweep_safety.zig", content);
    defer run.deinit(allocator);

    var saw_safety = false;
    for (run.issues.items) |issue| {
        const is_safety = mem.eql(u8, issue.rule, RULE_CATCH_UNREACHABLE) or
            mem.eql(u8, issue.rule, RULE_ORELSE_UNREACHABLE) or
            mem.eql(u8, issue.rule, RULE_CATCH_UNDEFINED) or
            mem.eql(u8, issue.rule, RULE_OPTIONAL_UNWRAP_UNSAFE) or
            mem.eql(u8, issue.rule, RULE_ORELSE_QUESTION_UNSAFE) or
            mem.eql(u8, issue.rule, RULE_DECREMENT_WITHOUT_CHECK) or
            mem.eql(u8, issue.rule, RULE_INDEX_ARITHMETIC);
        if (is_safety) saw_safety = true;
        try std.testing.expect(!is_safety or !issue.message_owned);
    }
    // The fixture must actually reach the safety families: a silent run
    // would make the no-owned-payload assertion vacuous.
    try std.testing.expect(saw_safety);
}

test "ZA1xx: no-free collectors stay byte-balanced on put failure (EPH-I1007)" {
    const allocator = std.testing.allocator;
    const path = "sweep_collectors.zig";
    // The fixture drives >= 2 puts into each no-free collector map: the
    // arena-typed struct fields (collectNoFreeFieldNames, file-level scan),
    // the type-init and alias chain (collectNoFreeAllocatorNames — two
    // stdlib inits; the arena0-named params no longer drive the signature
    // arm since the arena name matches exactly, ADR-0007/EPH-I0387), and
    // the init + Allocator-param chain (collectAllAllocatorNames).
    // A map whose put fails after earlier puts held storage dropped that
    // storage pre-fix; byte balance at every fail index is the leak proof
    // (EPH-I1007).
    const content =
        \\const S = struct {
        \\    arena0: std.heap.ArenaAllocator,
        \\    arena1: std.heap.ArenaAllocator,
        \\    arena2: std.heap.ArenaAllocator,
        \\    arena3: std.heap.ArenaAllocator,
        \\    arena4: std.heap.ArenaAllocator,
        \\    arena5: std.heap.ArenaAllocator,
        \\    arena6: std.heap.ArenaAllocator,
        \\    arena7: std.heap.ArenaAllocator,
        \\    arena8: std.heap.ArenaAllocator,
        \\    arena9: std.heap.ArenaAllocator,
        \\    arena10: std.heap.ArenaAllocator,
        \\    arena11: std.heap.ArenaAllocator,
        \\};
        \\
        \\fn sweep(arena0: std.mem.Allocator, arena1: std.mem.Allocator, arena2: std.mem.Allocator, arena3: std.mem.Allocator, arena4: std.mem.Allocator, arena5: std.mem.Allocator, arena6: std.mem.Allocator, arena7: std.mem.Allocator, arena8: std.mem.Allocator, arena9: std.mem.Allocator, arena10: std.mem.Allocator, arena11: std.mem.Allocator) !void {
        \\    const a = std.heap.ArenaAllocator.init(arena0);
        \\    const a2 = std.heap.FixedBufferAllocator.init(arena1);
        \\    const b1 = arena0.allocator();
        \\    const b2 = b1.allocator();
        \\    const b3 = b2.allocator();
        \\    const b4 = b3.allocator();
        \\    const b5 = b4.allocator();
        \\    const b6 = b5.allocator();
        \\    const b7 = b6.allocator();
        \\    const b8 = b7.allocator();
        \\    const b9 = b8.allocator();
        \\    const b10 = b9.allocator();
        \\    const b11 = b10.allocator();
        \\    const buf = try arena0.alloc(u8, 64);
        \\    arena0.free(buf);
        \\    _ = a;
        \\    _ = a2;
        \\    _ = b11;
        \\}
    ;

    // Fixture shape pin: each collector's map reaches >= 2 puts on this
    // input, so the sweep below covers a leakable point (a put failure
    // after the map holds storage) for every collector (EPH-I1007). The
    // call shapes mirror the pipeline: the field collector scans the whole
    // file, the name collectors scan the function's lines with the
    // signature first, like collectMemSafetyAllocs and prescanErrdeferSets.
    var lines = std.ArrayListUnmanaged([]const u8).empty;
    defer lines.deinit(allocator);
    var line_iter = mem.splitScalar(u8, content, '\n');
    while (line_iter.next()) |line| try lines.append(allocator, line);

    var fn_start: usize = 0;
    while (fn_start < lines.items.len and
        !mem.startsWith(u8, mem.trim(u8, lines.items[fn_start], " \t\r"), "fn ")) fn_start += 1;
    try std.testing.expect(fn_start < lines.items.len);
    const fn_lines = lines.items[fn_start..];

    var no_free_fields = try collectNoFreeFieldNames(allocator, lines.items);
    defer no_free_fields.deinit(allocator);
    try std.testing.expect(no_free_fields.count() >= 2);

    var no_free_names = try collectNoFreeAllocatorNames(
        allocator,
        fn_lines,
        &no_free_fields,
    );
    defer no_free_names.deinit(allocator);
    try std.testing.expect(no_free_names.count() >= 2);

    var all_names = try collectAllAllocatorNames(allocator, fn_lines);
    defer all_names.deinit(allocator);
    try std.testing.expect(all_names.count() >= 2);

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run).
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    try sweepCFGMemoryOnce(&probe, path, content);
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        if (sweepCFGMemoryOnce(&failing, path, content)) |_| {
            // Success iteration: the pipeline ran clean under the budget.
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
        }
        // Byte balance at every failure point is the leak proof. Pre-fix
        // the three no-free collector maps drop their storage when a put
        // fails after earlier successful puts (EPH-I1007).
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

/// Count issues for a rule within one file (test assertion helper).
fn countRuleIssues(
    issues: []const Issue,
    file: []const u8,
    rule: []const u8,
) usize {
    var n: usize = 0;
    for (issues) |issue| {
        if (mem.eql(u8, issue.file, file) and mem.eql(u8, issue.rule, rule)) n += 1;
    }
    return n;
}

/// Assert exactly one ZA607 issue for `file`, reported at `line`, with
/// `needle` inside the message. `needle` carries the quoted var name
/// (the message form is `variable 'x' potentially read before
/// assignment`). A count-only assertion cannot see a wrong-line or
/// wrong-var attribution regression (EPH-I0243 pins emission order,
/// not the read site), so each DA family pins one read site here.
fn expectSingleDAIssue(
    run: *const CFGTestRun,
    file: []const u8,
    line: usize,
    needle: []const u8,
) !void {
    var matches: usize = 0;
    for (run.issues.items) |issue| {
        if (!mem.eql(u8, issue.file, file)) continue;
        if (!mem.eql(u8, issue.rule, RULE_DEFINITE_ASSIGNMENT)) continue;
        matches += 1;
        try std.testing.expectEqual(line, issue.line);
        try std.testing.expect(mem.indexOf(u8, issue.message, needle) != null);
    }
    try std.testing.expectEqual(@as(usize, 1), matches);
}

test "ZA105/ZA106/ZA101: over-line-cap function skips memory analysis with a note (EPH-I0350)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The family rescans the body per allocation (O(M x N^2) worst), so an
    // over-cap function skips ZA101/ZA102/ZA105/ZA106 with one note
    // (band-B02 F11). The note is a note: it never fails a gate.
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator,
        \\fn big(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\
    );
    for (0..max_mem_family_lines + 16) |_| {
        try content.appendSlice(allocator, "    _ = buf;\n");
    }
    try content.appendSlice(allocator, "}\n");

    var run = try runCFGMemoryTest(&diag, allocator, "test_over_line_cap.zig", content.items);
    defer run.deinit(allocator);

    // The skip note rides the family rule: count findings by severity, so
    // the note does not read as a fired ZA105.
    var findings: usize = 0;
    var noted = false;
    for (run.issues.items) |issue| {
        const in_family = mem.eql(u8, issue.rule, RULE_USE_AFTER_FREE) or
            mem.eql(u8, issue.rule, RULE_DOUBLE_FREE) or
            mem.eql(u8, issue.rule, RULE_ALLOC_NO_DEFER);
        if (in_family and issue.severity != .note) findings += 1;
        if (issue.severity == .note and mem.indexOf(u8, issue.message, "analysis cap") != null)
            noted = true;
    }
    try std.testing.expect(findings == 0);
    try std.testing.expect(noted);
}

test "ZA105/ZA106/ZA101: over-alloc-cap function skips memory analysis with a note (EPH-I0350)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The allocation-count cap bounds the M factor of O(M x N^2). A
    // function with more than max_mem_family_allocs tracked allocations
    // skips the family with a note.
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator, "fn many(allocator: std.mem.Allocator) !void {\n");
    for (0..max_mem_family_allocs + 8) |i| {
        const line = try std.fmt.allocPrint(
            allocator,
            "    const b{d} = try allocator.alloc(u8, 64);\n",
            .{i},
        );
        defer allocator.free(line);
        try content.appendSlice(allocator, line);
    }
    for (0..max_mem_family_allocs + 8) |i| {
        const line = try std.fmt.allocPrint(allocator, "    _ = b{d};\n", .{i});
        defer allocator.free(line);
        try content.appendSlice(allocator, line);
    }
    try content.appendSlice(allocator, "}\n");

    var run = try runCFGMemoryTest(&diag, allocator, "test_over_alloc_cap.zig", content.items);
    defer run.deinit(allocator);

    // The skip notes ride the family rules: count findings by severity, so
    // the notes do not read as fired ZA105/ZA101.
    var findings: usize = 0;
    var noted = false;
    for (run.issues.items) |issue| {
        const in_family = mem.eql(u8, issue.rule, RULE_USE_AFTER_FREE) or
            mem.eql(u8, issue.rule, RULE_DOUBLE_FREE) or
            mem.eql(u8, issue.rule, RULE_ALLOC_NO_DEFER);
        if (in_family and issue.severity != .note) findings += 1;
        if (issue.severity == .note and mem.indexOf(u8, issue.message, "analysis cap") != null)
            noted = true;
    }
    try std.testing.expect(findings == 0);
    try std.testing.expect(noted);
}

test "ZA103: over-line-cap function skips errdefer coverage with a note (EPH-I1006)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The ZA103 tail's per-allocation transfer walk rescans the body for
    // each try-alloc (O(M x N)), so the I0350 line cap bounds it too: an
    // over-cap function emits the note and zero ZA103 findings. The
    // trailing error return would fire a ZA103 gap under-cap, so the
    // zero-findings assert discriminates the skip from a vacuous pass
    // (EPH-I1006).
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator,
        \\fn big(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\
    );
    for (0..max_mem_family_lines + 16) |_| {
        try content.appendSlice(allocator, "    _ = buf;\n");
    }
    try content.appendSlice(allocator, "    return error.OutOfMemory;\n");
    try content.appendSlice(allocator, "}\n");

    var run = try runCFGMemoryTest(&diag, allocator, "test_errdefer_line_cap.zig", content.items);
    defer run.deinit(allocator);

    var z103_findings: usize = 0;
    var noted = false;
    for (run.issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER) and issue.severity != .note)
            z103_findings += 1;
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER) and
            issue.severity == .note and
            mem.indexOf(u8, issue.message, "analysis cap") != null)
            noted = true;
    }
    try std.testing.expect(z103_findings == 0);
    try std.testing.expect(noted);
}

test "ZA103: over-alloc-cap function skips errdefer coverage with a note (EPH-I1006)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The allocation-count cap bounds the M factor of the tail's O(M x N)
    // per-allocation transfer walks: an over-cap function emits the note
    // and zero ZA103 findings. Under-cap, every try-alloc without an
    // errdefer before the next try fires a gap, so the zero-findings
    // assert discriminates the skip (EPH-I1006).
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator, "fn many(allocator: std.mem.Allocator) !void {\n");
    for (0..max_mem_family_allocs + 8) |i| {
        const line = try std.fmt.allocPrint(
            allocator,
            "    const b{d} = try allocator.alloc(u8, 64);\n",
            .{i},
        );
        defer allocator.free(line);
        try content.appendSlice(allocator, line);
    }
    for (0..max_mem_family_allocs + 8) |i| {
        const line = try std.fmt.allocPrint(allocator, "    _ = b{d};\n", .{i});
        defer allocator.free(line);
        try content.appendSlice(allocator, line);
    }
    try content.appendSlice(allocator, "}\n");

    var run = try runCFGMemoryTest(&diag, allocator, "test_errdefer_alloc_cap.zig", content.items);
    defer run.deinit(allocator);

    var z103_findings: usize = 0;
    var noted = false;
    for (run.issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER) and issue.severity != .note)
            z103_findings += 1;
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER) and
            issue.severity == .note and
            mem.indexOf(u8, issue.message, "analysis cap") != null)
            noted = true;
    }
    try std.testing.expect(z103_findings == 0);
    try std.testing.expect(noted);
}

test "ZA101/ZA103: multi-line .alloc( with wrapped args is detected" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // zig-fmt canonical wrap: first line ends after `(` — the type first-arg
    // only becomes visible by joining continuation lines.
    const content =
        \\fn wrapped_alloc(allocator: std.mem.Allocator) !void {
        \\    const buf = try allocator.alloc(
        \\        u8,
        \\        4096,
        \\    );
        \\    const more = try allocator.alloc(u8, 64);
        \\    _ = more;
        \\    _ = buf;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_wrapped_alloc.zig", content);
    defer run.deinit(allocator);

    const file = "test_wrapped_alloc.zig";
    // band-T01 F3 (EPH-I0551): the fixture holds exactly two unprotected
    // allocs, so each rule must pin the exact count. A regression from
    // two findings to one, or a duplicate emission, fails here.
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_DEFER) == 2);
    // One errdefer gap, not two: `buf` is followed by the fallible
    // `more` alloc with no errdefer (gap), while `more` has no later
    // fallible op, so nothing covers it and nothing demands coverage.
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_ERRDEFER) == 1);
}

test "ZA101: third-arg allocator tracks realPathFileAlloc with arena suppression (EPH-I1113)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The 0.16 Io.Dir.realPathFileAlloc takes the allocator as the THIRD
    // call argument. Pre-fix neither findAllocCall nor the extractor
    // modeled the shape, so the unprotected gpa fn fired nothing (the
    // FN). The arena fn is the suppression discriminator: the same call
    // with an arena-named third arg must stay silent.
    const content =
        \\fn realpath_gpa(io: std.Io, sub: []const u8, gpa: std.mem.Allocator) !void {
        \\    const p = try std.Io.Dir.cwd().realPathFileAlloc(io, sub, gpa);
        \\    _ = p;
        \\}
        \\fn realpath_arena(io: std.Io, sub: []const u8, arena: std.mem.Allocator) !void {
        \\    const p = try std.Io.Dir.cwd().realPathFileAlloc(io, sub, arena);
        \\    _ = p;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_third_arg_alloc.zig", content);
    defer run.deinit(allocator);

    const file = "test_third_arg_alloc.zig";
    try std.testing.expect(countRuleIssues(run.issues.items, file, RULE_ALLOC_NO_DEFER) == 1);
    var gpa_line = false;
    var arena_line = false;
    for (run.issues.items) |issue| {
        if (!mem.eql(u8, issue.rule, RULE_ALLOC_NO_DEFER)) continue;
        if (issue.line == 2) gpa_line = true;
        if (issue.line == 6) arena_line = true;
    }
    try std.testing.expect(gpa_line);
    try std.testing.expect(!arena_line);
}

test "isTypeAllocFactory tab-separated type stays a factory (EPH-I1201)" {
    // B112 r1 F1 pin (the batch's explained A/B entry): allocCallerWord's
    // identBefore skips tabs, so `Type\t.alloc(T)` reads as a type
    // factory method. The pre-B112 walk stopped at the tab and classified
    // the call as an allocator call — a ZA101 false positive. The
    // lowercase receiver keeps its non-factory verdict on both paths.
    try std.testing.expect(isTypeAllocFactory("Type\t.alloc(T)", 5));
    try std.testing.expect(!isTypeAllocFactory("x\t.alloc(T)", 2));
}

