test "ZA101: far early return still warns, loop with post-loop defer stays silent (EPH-I0348 lock)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The far early-return shape (defer beyond the immediate window)
    // must fire through the linear fallback's dominance gate. The loop
    // shape has no exit between alloc and defer, so the fallback still
    // masks the documented loop-deadlock artifact (EPH-I0682 F6a).
    const content =
        \\fn leaky_far(allocator: std.mem.Allocator, c: bool) !void {
        \\    const x = try allocator.alloc(u8, 10);
        \\    if (c) {
        \\        return;
        \\    }
        \\    const a = 1;
        \\    const b = 2;
        \\    const d = 3;
        \\    const e = 4;
        \\    const f = 5;
        \\    const g = 6;
        \\    const h = 7;
        \\    defer allocator.free(x);
        \\    _ = x;
        \\}
        \\fn loop_ok(allocator: std.mem.Allocator, n: usize) !void {
        \\    const y = try allocator.alloc(u8, 10);
        \\    var i: usize = 0;
        \\    while (i < n) : (i += 1) {
        \\        _ = y;
        \\    }
        \\    defer allocator.free(y);
        \\    _ = y;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_early_far.zig", content);
    defer run.deinit(allocator);

    try std.testing.expect(countRuleIssues(
        run.issues.items,
        "test_early_far.zig",
        RULE_ALLOC_NO_DEFER,
    ) == 1);
}

test "ZA101: exit-free inner loop between alloc and free stays silent (EPH-I0116)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The F6a loop deadlock read an exit-free inner loop as uncovered:
    // the alloc always reaches the post-loop free, so the ZA101 was an
    // FP. Pre-fix nested_no_break fired; post-fix only the exit
    // shapes fire (break/return/try can bypass the free, so their
    // verdict stays FP-lean).
    const content =
        \\fn nested_no_break(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) {}
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn nested_break(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) break;
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn nested_return(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) return;
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn nested_try(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) try fail();
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn fail() !void {
        \\    return error.Bad;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_exit_free_loop.zig", content);
    defer run.deinit(allocator);

    // nested_break, nested_return, nested_try fire; nested_no_break stays
    // silent.
    try std.testing.expectEqual(
        @as(usize, 3),
        countRuleIssues(run.issues.items, "test_exit_free_loop.zig", RULE_ALLOC_NO_DEFER),
    );
}

test "ZA101: end-of-line try and bare return inside the loop stay loud (EPH-I1179)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // RED direction: the trailing-space keyword forms missed both exit
    // shapes — a `try` at end of line (the operand wrapped onto the
    // next line) and a bare `return;` in a multi-statement arm — so
    // the exit-free relaxation suppressed a genuine ZA101. The
    // word-bounded scan restores both; the clean control stays silent.
    const content =
        \\fn eol_try(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) try
        \\            fail();
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn mid_return(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) { j = 9; return; }
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn clean_control(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 10);
        \\    var j: u32 = 0;
        \\    while (j < 3) : (j += 1) {
        \\        if (c) {}
        \\    }
        \\    allocator.free(buf);
        \\}
        \\fn fail() !void {
        \\    return error.Bad;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_eol_exits_101.zig", content);
    defer run.deinit(allocator);

    // eol_try and mid_return fire; clean_control stays silent.
    try std.testing.expectEqual(
        @as(usize, 2),
        countRuleIssues(run.issues.items, "test_eol_exits_101.zig", RULE_ALLOC_NO_DEFER),
    );
}

