        \\    const buf = try allocator.alloc(u8, 64);
        \\    allocator.free(buf);
        \\    if (c) {
        \\        if (d) {
        \\            allocator.free(buf);
        \\        } else {
        \\            allocator.free(buf);
        \\        }
        \\    }
        \\    use(buf);
        \\}
        \\fn both(allocator: std.mem.Allocator, c: bool) !void {
        \\    const buf = try allocator.alloc(u8, 64);
        \\    allocator.free(buf);
        \\    if (c) {
