test "hasTestingCall matches std.testing call shapes (EPH-I0224)" {
    try std.testing.expect(hasTestingCall("const t = std.testing.expect(p.? == 1);"));
    try std.testing.expect(hasTestingCall("try testing.expectEqual(x, 1);"));
    try std.testing.expect(hasTestingCall("try std.testing.expectError(error.E, f());"));
    try std.testing.expect(hasTestingCall("try std.testing.expectEqualSlices(u8, a, b);"));
}

test "hasTestingCall rejects substrings, strings, and non-calls (EPH-I0224)" {
    try std.testing.expect(!hasTestingCall("const unexpected_total = p.? + 1;"));
    try std.testing.expect(!hasTestingCall("const n = protesting.count(p.?);"));
    try std.testing.expect(!hasTestingCall("const s = \".expect(\";"));
    try std.testing.expect(!hasTestingCall("const alloc = testing.allocator;"));
}

test "hasTestingCall is receiver-scoped: user methods and fields do not disarm (EPH-I0296)" {
    // A user method named expectToken on a non-testing receiver must not
    // suppress ZA801 (the pre-fix `.expect<tail>(` scan accepted it).
    try std.testing.expect(!hasTestingCall("tokens.expectToken(v.?);"));
    try std.testing.expect(!hasTestingCall("_ = self.expectEqual(p.?);"));
    // A user field named testing must not suppress (the pre-fix word-edge
    // check let the dot through).
    try std.testing.expect(!hasTestingCall("foo.testing.bar(p.?);"));
    try std.testing.expect(!hasTestingCall("mystd.testing.expect(p.?);"));
    // A renamed import is the documented false negative: the receiver is
    // not `testing`.
    try std.testing.expect(!hasTestingCall("t.expect(p.? == 1);"));
    // The real std.testing shapes still disarm, dot-prefixed by std or bare.
    try std.testing.expect(hasTestingCall("try std.testing.expect(p.? == 1);"));
    try std.testing.expect(hasTestingCall("try testing.expectEqual(p.?, 1);"));
}

test "hasOrelseOperator ignores string literal contents (EPH-I0224)" {
    try std.testing.expect(hasOrelseOperator("const v = p orelse 0;"));
    try std.testing.expect(!hasOrelseOperator("const v = p.? + msg(\"use orelse here\");"));
}

test "isInSafeContext masks trailing comment text (EPH-I0224)" {
    try std.testing.expect(!isInSafeContext("const v = p.? + 1; // expect this"));
    try std.testing.expect(!isInSafeContext("const v = p.? + 1; // std.testing.expect(v)"));
    try std.testing.expect(isInSafeContext("if (p) |x| {"));
    try std.testing.expect(isInSafeContext("const v = p orelse 0;"));
    try std.testing.expect(isInSafeContext("const t = std.testing.expect(p.? == 1);"));
}

test "analyzeCFGErrdeferCoverage detects missing errdefer (ZA103)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    // Missing errdefer before second try
    const test_content =
        \\fn bad_errdefer(alloc: std.mem.Allocator) !void {
        \\    const data = try alloc.alloc(u8, 100);
        \\    // MISSING errdefer here!
        \\    const more = try alloc.alloc(u8, 100);
        \\    errdefer alloc.free(more);
        \\    _ = data;
        \\}
    ;

    const analysis = try createTestFileAnalysis(allocator, "test_errdefer.zig", test_content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_errdefer.zig"), {});

    var issues = try analyzeCFGMemory(allocator, &graph);
    defer deinitIssues(&issues, allocator);

    // Should detect the missing errdefer
    var found_za103 = false;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER)) {
            found_za103 = true;
            break;
        }
    }
    try std.testing.expect(found_za103);
}

