        \\    pub fn reset(self: *Service) void {
        \\        self.state = 0;
        \\    }
        \\    pub fn connect(self: *Service) !void {
        \\        _ = self;
        \\    }
        \\    pub fn getStatus(self: *const Service) u32 {
        \\        return self.state;
        \\    }
        \\};
        \\fn use() void {
        \\    var svc = Service{ .state = 0 };
        \\    _ = svc.reset();
        \\    _ = svc.connect();
        \\    _ = svc.getStatus();
        \\}
    ;

