test "ephor:ignore above function suppresses entire scope" {
    const content =
        \\const a = foo() catch {};
        \\// ephor:ignore ZA201
        \\fn bad_function() void {
        \\    bar() catch {};
        \\    baz() catch {};
        \\}
        \\const b = qux() catch {};
    ;
    // Line 1: before ignore — not suppressed
    try std.testing.expect(!isInlineDisabled(content, 1, "ZA201"));
    // Line 3: function declaration line — suppressed (scope starts here)
    try std.testing.expect(isInlineDisabled(content, 3, "ZA201"));
    // Line 4: inside function body — suppressed
    try std.testing.expect(isInlineDisabled(content, 4, "ZA201"));
    // Line 5: inside function body — suppressed
    try std.testing.expect(isInlineDisabled(content, 5, "ZA201"));
    // Line 6: closing brace — suppressed (last line of scope)
    try std.testing.expect(isInlineDisabled(content, 6, "ZA201"));
    // Line 7: after function — not suppressed
    try std.testing.expect(!isInlineDisabled(content, 7, "ZA201"));
}

test "ephor:ignore above scope only suppresses matching rule" {
    const content =
        \\// ephor:ignore ZA201
        \\fn my_fn() void {
        \\    foo() catch {};
        \\    const x = val orelse unreachable;
        \\}
    ;
    // ZA201 suppressed inside scope
    try std.testing.expect(isInlineDisabled(content, 3, "ZA201"));
    // ZA203 NOT suppressed — different rule
    try std.testing.expect(!isInlineDisabled(content, 4, "ZA203"));
}

test "ephor:ignore above scope without rule suppresses all rules" {
    const content =
        \\// ephor:ignore
        \\fn my_fn() void {
        \\    foo() catch {};
        \\    const x = val orelse unreachable;
        \\}
    ;
    try std.testing.expect(isInlineDisabled(content, 3, "ZA201"));
    try std.testing.expect(isInlineDisabled(content, 4, "ZA203"));
}

test "ephor:ignore scope works with nested braces" {
    const content =
        \\// ephor:ignore ZA201
        \\fn outer() void {
        \\    if (true) {
        \\        foo() catch {};
        \\    }
        \\    bar() catch {};
        \\}
        \\const after = baz() catch {};
    ;
    // Lines 2-7: inside outer function scope — all suppressed
    try std.testing.expect(isInlineDisabled(content, 2, "ZA201"));
    try std.testing.expect(isInlineDisabled(content, 4, "ZA201"));
    try std.testing.expect(isInlineDisabled(content, 6, "ZA201"));
    try std.testing.expect(isInlineDisabled(content, 7, "ZA201"));
    // Line 8: after scope — not suppressed
    try std.testing.expect(!isInlineDisabled(content, 8, "ZA201"));
}

/// Assert one (line, ZA201) suppression verdict through BOTH the per-issue
/// rescan and the cached RuleFacts lookup. buildRuleFacts must mirror
/// isInlineDisabled branch-for-branch, so a verdict probed through only one
/// path leaves the mirror invariant unproven.
fn expectSuppression(content: []const u8, line_num: usize, want: bool) !void {
    try std.testing.expectEqual(want, isInlineDisabled(content, line_num, "ZA201"));
    var cache = IgnoreCache.init(std.testing.allocator);
    defer cache.deinit();
    const got = cache.isSuppressed(content, "fixture.zig", line_num, "ZA201");
    try std.testing.expectEqual(want, got);
}

test "ignore scope survives braces inside string literals" {
    const content =
        \\// ephor:ignore ZA201
        \\fn leaky() void {
        \\    const s = "}";
        \\    foo() catch {};
        \\}
        \\const after = bar() catch {};
    ;
    // The `}` inside the string is data: the scope closes at the real
    // closing brace on line 5, not at the string on line 3.
    try expectSuppression(content, 2, true);
    try expectSuppression(content, 3, true);
    try expectSuppression(content, 4, true);
    try expectSuppression(content, 5, true);
    try expectSuppression(content, 6, false);
}

test "ignore scope survives brace inside char literal" {
    const content =
        \\// ephor:ignore ZA201
        \\fn leaky() void {
        \\    const c = '}';
        \\    foo() catch {};
        \\}
        \\const after = bar() catch {};
    ;
    // `'}'` is char data: it must not close the scope early.
    try expectSuppression(content, 3, true);
    try expectSuppression(content, 4, true);
    try expectSuppression(content, 5, true);
    try expectSuppression(content, 6, false);
}

test "ignore scope ignores brace in trailing comment" {
    const content =
        \\// ephor:ignore ZA201
        \\fn leaky() void {
        \\    foo() catch {}; // }
        \\    bar() catch {};
        \\}
        \\const after = baz() catch {};
    ;
    // The `}` after `//` is comment text: the scope closes on line 5.
    try expectSuppression(content, 3, true);
    try expectSuppression(content, 4, true);
    try expectSuppression(content, 5, true);
    try expectSuppression(content, 6, false);
}

test "brace in comment does not open ignore scope" {
    const content =
        \\// ephor:ignore ZA201
        \\var x: u32 = 0; // {
        \\x += 1;
    ;
    // The only `{` is comment text, so no scope opens: the directive
    // suppresses just the next line.
    try expectSuppression(content, 2, true);
    try expectSuppression(content, 3, false);
}

test "multiline-string line braces do not perturb ignore scope" {
    const content =
        \\// ephor:ignore ZA201
        \\fn leaky() void {
        \\    const fixture =
        \\        \\} closing brace data
        \\    ;
        \\    foo() catch {};
        \\}
        \\const after = bar() catch {};
    ;
    // Line 4 is a multiline-string body: its `}` is string data, so the
    // scope stays open until the real closing brace on line 7.
    try expectSuppression(content, 2, true);
    try expectSuppression(content, 3, true);
