        .body = .{
            .lines = lines_list.items,
            .func_line = 1,
            .file_path = "test_conditional.zig",
        },
        .file_no_free_fields = null,
    });
    defer deinitIssues(&issues, allocator);

    // Should detect that defer is not on all paths
    var found_issue = false;
    for (issues.items) |issue| {
