test "definite-assignment worklist drains beyond the 2B+1 cap (EPH-I1058)" {
    // The bun cli/Arguments.zig parse crash (the release-blocking corpus
    // abort): a long chain of payload-ifs and nested-return ifs with the
    // var's assignment if/else near the start. The CFG builder
    // pre-creates each if's false-continuation block, so the inner
    // merges flow back to lower block ids; the flip wave then
    // re-enqueues nearly every downstream block. This shape has
    // B = 64 blocks and E = 94 included edges; the worklist enqueues
    // 130 entries — one past the former 2B+1 cap, which asserted and
    // aborted the whole scan (exit 134). The queue bound is
    // B + 2E + 1: each block's entry and exit flip false->true at most
    // once, and each flip re-enqueues the block's successors, so total
    // enqueues stay below B + 2E.
    const allocator = std.testing.allocator;
    const lines = [_][]const u8{
        "fn f(a: bool) void {",
        "    var v: u32 = undefined;",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        v = 2;",
        "    } else {",
        "        v = 3;",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    if (opt) |p| {",
        "        if (p > 0) { return; }",
        "    }",
        "    if (a) {",
        "        if (a) { return; }",
        "    }",
        "    _ = v;",
        "}",
    };
    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();
    var nb = try buildBlockNeighbors(allocator, &cfg);
    defer nb.deinit(allocator);
    const num_blocks = cfg.blocks.items.len;
    const num_edges = nb.succ_flat.len;
    // The analysis must complete: pre-fix, the 2B+1 queue overflowed on
    // this shape and the fail-loud assert aborted the run.
    var def_issues = try analyzeDefiniteAssignment(allocator, &cfg, &lines, 1);
    defer def_issues.deinit();
    // The drain pin: the worklist stays inside the B + 2E + 1 bound and
    // lands BEYOND the former 2B+1 cap (130 visits for 64 blocks), so
    // the fixture really exercises the overflow region. The gen set is
    // the production attribution for the var's assignments (the same
    // computeGenSetForVar the analysis path runs).
    var gs = try computeGenSetForVar(&.{
        .allocator = allocator,
        .cfg = &cfg,
        .lines = &lines,
        .func_line = 1,
        .num_blocks = num_blocks,
        .neighbors = &nb,
    }, "v", null);
    defer gs.deinit(allocator);
    const gen = gs.gen;
    const def_entry = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_entry);
    const def_exit = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_exit);
    @memset(def_entry, false);
    @memset(def_exit, false);
    const queue = try allocator.alloc(usize, num_blocks +| 2 *| num_edges +| 1);
    defer allocator.free(queue);
    const in_queue = try allocator.alloc(bool, num_blocks);
    defer allocator.free(in_queue);
    @memset(in_queue, false);
    const visits = runDefiniteAssignmentWorklist(&nb, .{
        .gen = gen,
        .def_entry = def_entry,
        .def_exit = def_exit,
        .num_blocks = num_blocks,
        .num_edges = num_edges,
    }, queue, in_queue);
    try std.testing.expect(visits > num_blocks *| 2 +| 1);
    try std.testing.expect(visits < num_blocks +| 2 *| num_edges +| 1);
}

test "definite-assignment worklist drains within the B+2E+1 bound (EPH-I0335, EPH-I1003, EPH-I1058)" {
    const allocator = std.testing.allocator;
    // A small branchy function. The queue-driven fixpoint must visit
    // each block at most twice (initial plus one re-visit per state
    // flip): the sweep form it replaced made up to 2B+1 full passes
    // over every edge. Pre-fix, a chain-shaped CFG of B blocks paid
    // O(B^2) visits; the drain is the hermetic pin.
    //
    // The loop condition caps visits at B + 2E + 1 (blocks plus twice
    // the included edges), so a <= assertion can never fail
    // (EPH-I1003, EPH-I1058): the cap exits only with visits ==
    // B + 2E + 1 and returns that exact value. The strict form
    // discriminates the two exits. It holds only when the queue
    // drained, and fails only when the cap truncated the run — the
    // F-13 under-approximation, where a read may report where a longer
    // run would prove coverage. The monotone bound says the drain
    // always comes first on the shapes the CFG builder produces
    // (loop-back preds are excluded).
    const lines = [_][]const u8{
        "fn f(a: bool) !void {",
        "    if (a) {",
        "        try g();",
        "    }",
        "    try h();",
        "}",
    };
    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();
    var nb = try buildBlockNeighbors(allocator, &cfg);
    defer nb.deinit(allocator);
    const num_blocks = cfg.blocks.items.len;
    const gen = try allocator.alloc(bool, num_blocks);
    defer allocator.free(gen);
    @memset(gen, false);
    const def_entry = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_entry);
    const def_exit = try allocator.alloc(bool, num_blocks);
    defer allocator.free(def_exit);
    @memset(def_entry, false);
    @memset(def_exit, false);
    const queue = try allocator.alloc(usize, num_blocks +| 2 *| nb.succ_flat.len +| 1);
    defer allocator.free(queue);
    const in_queue = try allocator.alloc(bool, num_blocks);
    defer allocator.free(in_queue);
    @memset(in_queue, false);
    const visits = runDefiniteAssignmentWorklist(&nb, .{
        .gen = gen,
        .def_entry = def_entry,
        .def_exit = def_exit,
        .num_blocks = num_blocks,
        .num_edges = nb.succ_flat.len,
    }, queue, in_queue);
    try std.testing.expect(visits < num_blocks +| 2 *| nb.succ_flat.len +| 1);
}

test "definite-assignment converges on a 10k-line adversarial function (EPH-I0335)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // 1000 undefined vars, each read inside four nested same-condition
    // ifs — the guard-walk and correlated-guard scans' worst shape.
    // Pre-fix, the 11k-line input hung the analyzer past five minutes
    // (the O(n^3) per-var scans and the O(B^2 * E) worklist); the
    // bounded scans and the queue worklist finish the 11k shape in
    // 10.7 s (A/B measured at dispatch on the ReleaseSafe binary). The
    // verdicts stay exact: every uncovered read still reports.
    var body: std.ArrayListUnmanaged([]const u8) = .empty;
    var owned: std.ArrayListUnmanaged([]const u8) = .empty;
    try body.append(allocator, "fn adversarial() void {");
    try body.append(allocator, "    var g: ?u32 = null;");
    var i: usize = 0;
    while (i < 1000) : (i += 1) {
        const decl = try std.fmt.allocPrint(
            allocator,
            "    var v{d}: u32 = undefined;",
            .{i},
        );
        try owned.append(allocator, decl);
        try body.append(allocator, decl);
        var d: usize = 0;
        while (d < 4) : (d += 1) {
            try body.append(allocator, "    if (g != null) {");
        }
        const read = try std.fmt.allocPrint(
            allocator,
            "    const r{d} = v{d};",
            .{ i, i },
        );
        try owned.append(allocator, read);
        try body.append(allocator, read);
        const fill = try std.fmt.allocPrint(
            allocator,
            "    if (r{d} == 0) {{ v{d} = 1; }}",
            .{ i, i },
        );
        try owned.append(allocator, fill);
        try body.append(allocator, fill);
        d = 0;
        while (d < 4) : (d += 1) {
            try body.append(allocator, "    }");
        }
    }
    try body.append(allocator, "}");
    const lines = try body.toOwnedSlice(allocator);
    defer {
        for (owned.items) |s| allocator.free(s);
        owned.deinit(allocator);
        allocator.free(lines);
    }

    var cfg = try buildCFG(allocator, "adversarial", 1, lines);
    defer cfg.deinit();

    var def_issues = try analyzeDefiniteAssignment(allocator, &cfg, lines, 1);
    defer def_issues.deinit();

    try std.testing.expectEqual(@as(usize, 1000), def_issues.count());
}

test "ZA607: same-function issues emit in source line order (EPH-I0243)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // EPH-I0243: one function with three undefined vars, each read on a
    // distinct line. The map iteration is hash order — the tigerbeetle
    // lsm/tree.zig capture shows it diverges from source order — so the
    // emission must stage and sort by (line, name) before appending.
    // Every ZA607 issue carries col 1 and the fixed rule, so line order
    // IS the full (file, line, col, rule) order here.
    const content =
        \\fn threeVars(a: bool, b: bool) u32 {
        \\    var zz: u32 = undefined;
        \\    var mm: u32 = undefined;
        \\    var aa: u32 = undefined;
        \\    if (a) return zz;
        \\    if (b) return mm;
        \\    return aa;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_i0243_order.zig", content);
    defer run.deinit(allocator);

    var lines_seen = std.ArrayListUnmanaged(usize).empty;
    defer lines_seen.deinit(allocator);
    for (run.issues.items) |issue| {
        if (!mem.eql(u8, issue.rule, RULE_DEFINITE_ASSIGNMENT)) continue;
        try lines_seen.append(allocator, issue.line);
    }
    try std.testing.expectEqual(@as(usize, 3), lines_seen.items.len);
    try std.testing.expectEqual(@as(usize, 5), lines_seen.items[0]);
    try std.testing.expectEqual(@as(usize, 6), lines_seen.items[1]);
    try std.testing.expectEqual(@as(usize, 7), lines_seen.items[2]);
}

test "analyzeDefiniteAssignment: OOM mid-run unwinds both maps (EPH-I0337)" {
    const allocator = std.testing.allocator;
    const lines = [_][]const u8{
        "fn f() u32 {",
        "    var x: u32 = undefined;",
        "    var y: u32 = undefined;",
        "    return x + y;",
        "}",
    };
    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Measure the cold-run allocation count so the sweep covers every
    // induced failure point (plus one no-failure run).
    var probe = std.testing.FailingAllocator.init(allocator, .{});
    {
        var def_issues = try analyzeDefiniteAssignment(probe.allocator(), &cfg, &lines, 1);
        def_issues.deinit();
    }
    const total_allocs = probe.allocations;

    var fail_index: usize = 0;
    while (fail_index <= total_allocs) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{
            .fail_index = fail_index,
        });
        var issues = analyzeDefiniteAssignment(failing.allocator(), &cfg, &lines, 1) catch |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            // Byte balance at the failure point is the leak proof: the
            // errdefers free the issues map and the undef-vars map on
            // the OOM path (band-B01b F-11).
            try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
            continue;
        };
        issues.deinit();
        try std.testing.expectEqual(failing.allocated_bytes, failing.freed_bytes);
    }
}

// ============================================================================
// CFG expression-brace guard tests (EPH-I0079 A1)
// ============================================================================

fn cfgHasEdge(cfg: *const ControlFlowGraph, from: usize, to: usize, kind: EdgeKind) bool {
    for (cfg.edges.items) |e| {
        if (e.from == from and e.to == to and e.kind == kind) return true;
    }
    return false;
}

test "buildCFG: struct literal close does not pop if block" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    var x: u32 = 0;", // 2
        "    if (cond) {", // 3
        "        const cfg = C{", // 4
        "            .a = 1,", // 5
        "        };", // 6
        "        x = 1;", // 7
        "    }", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Line 7 must stay in the if-true block, not fall through to the merge
    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(if_block, findBlockForLine(&cfg, 7));
}

test "buildCFG: call-arg close does not pop if block" {
