test "buildCFG: switch arm block close does not pop switch entry" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8) void {", // 1
        "    switch (x) {", // 2
        "        .a => {", // 3
        "            g();", // 4
        "        },", // 5
        "        .b => {", // 6
        "            h();", // 7
        "        },", // 8
        "    }", // 9
        "}", // 10
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // Both arms must branch from the switch header block; the first arm's
    // `},` close must not pop the switch entry before arm .b is wired up.
    const header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    const arm_a = findBlockForLine(&cfg, 4) orelse return error.TestUnexpectedResult;
    const arm_b = findBlockForLine(&cfg, 7) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, header, arm_a, .branch_true));
    try std.testing.expect(cfgHasEdge(&cfg, header, arm_b, .branch_true));
}

test "buildCFG: int, range, discard, and string prongs open arm blocks (EPH-I0679)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8, s: []const u8) void {", // 1
        "    switch (x) {", // 2
        "        1 => {", // 3
        "            g();", // 4
        "        },", // 5
        "        0...9 => {", // 6
        "            h();", // 7
        "        },", // 8
        "        _ => {", // 9
        "            i();", // 10
        "        },", // 11
        "    }", // 12
        "    switch (s) {", // 13
        "        \"a\" => {", // 14
        "            j();", // 15
        "        },", // 16
        "        else => {", // 17
        "            k();", // 18
        "        },", // 19
        "    }", // 20
        "}", // 21
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // EPH-I0679: every prong form branches from its switch header. Before
    // the fix these bodies attributed to the header (or the previous arm),
    // whose exit bit is unconditional.
    const int_header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    const str_header = findBlockForLine(&cfg, 13) orelse return error.TestUnexpectedResult;
    for ([_]usize{ 4, 7, 10 }) |body_line| {
        const arm = findBlockForLine(&cfg, body_line) orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(cfgHasEdge(&cfg, int_header, arm, .branch_true));
    }
    for ([_]usize{ 15, 18 }) |body_line| {
        const arm = findBlockForLine(&cfg, body_line) orelse
            return error.TestUnexpectedResult;
        try std.testing.expect(cfgHasEdge(&cfg, str_header, arm, .branch_true));
    }
}

test "buildCFG: single-line switch arms attribute to the header (EPH-I0750 approximation)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8) void {", // 1
        "    switch (x) { 1 => { g(); }, _ => { h(); }, }", // 2
        "}", // 3
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // EPH-I0750 documented approximation: a whole switch on one line
    // classifies as switch_start only, so no prong dispatches an arm
    // block and the arm bodies attribute to the header block. The
    // idiomatic per-line prong form (EPH-I0679) opens arm blocks. This
    // pin flips when prong dispatch lands, forcing the doc update.
    const single_line = "switch (v) { 1 => { x = 1; }, _ => {}, }";
    try std.testing.expectEqual(CFPattern.switch_start, detectCFPattern(single_line));
    // The same line's code-position arrow satisfies the prong test, so
    // the table ordering owns the residual, not the prong detector.
    try std.testing.expect(isSwitchArmLine(single_line));
    // The CFG evidence: the header block owns line 2 and branches to no
    // arm block.
    const header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    var arm_edges: usize = 0;
    for (cfg.edges.items) |e| {
        if (e.from == header and e.kind == .branch_true) arm_edges += 1;
    }
    try std.testing.expectEqual(@as(usize, 0), arm_edges);
}

test "detectCFPattern word-bounds the else/else-if prefixes (EPH-I0090)" {
    // The misfire: `} else ifx;` is an else branch whose braceless
    // statement is the identifier `ifx` — a raw startsWith read it as an
    // else-if arm and moved the branch boundary. `} elseif(` is a block
    // end plus a call on the same line, not an else arm at all.
    try std.testing.expectEqual(CFPattern.else_start, detectCFPattern("} else ifx;"));
    try std.testing.expectEqual(CFPattern.none, detectCFPattern("} elseif( x );"));
    // The real arm forms keep classifying: spaced, tight-paren, and the
    // Allman close-brace form with the condition on the next line.
    try std.testing.expectEqual(CFPattern.else_if, detectCFPattern("} else if (x) {"));
    try std.testing.expectEqual(CFPattern.else_if, detectCFPattern("} else if(x) {"));
    try std.testing.expectEqual(CFPattern.else_if, detectCFPattern("} else if"));
    try std.testing.expectEqual(CFPattern.else_start, detectCFPattern("} else {"));
    try std.testing.expectEqual(CFPattern.else_start, detectCFPattern("} else{"));
    try std.testing.expectEqual(CFPattern.else_start, detectCFPattern("} else"));
}

test "detectCFPattern strips a loop label before the table match (EPH-I0115)" {
    // A label hides the opener keyword, so the loop entry never existed
    // and bare break/continue inside bound to nothing (FN direction).
    // The labeled jump itself stays unclassified by design: line-based
    // analysis cannot tell a labeled loop break from a labeled block
    // break (EPH-I0094), so only the opener recognition is modeled.
    try std.testing.expectEqual(CFPattern.while_start, detectCFPattern("outer: while (c) {"));
    try std.testing.expectEqual(CFPattern.for_start, detectCFPattern("outer: for (x) |y| {"));
    try std.testing.expectEqual(CFPattern.switch_start, detectCFPattern("outer: switch (x) {"));
    // Documented bound pins: a labeled block opens no loop, and the
    // labeled jump forms stay .none (fall-through semantics).
    try std.testing.expectEqual(CFPattern.none, detectCFPattern("outer: {"));
    try std.testing.expectEqual(CFPattern.none, detectCFPattern("break :outer;"));
    try std.testing.expectEqual(CFPattern.none, detectCFPattern("continue :outer;"));
    // The unlabeled forms keep their classifications.
    try std.testing.expectEqual(CFPattern.while_start, detectCFPattern("while (c) {"));
    try std.testing.expectEqual(CFPattern.break_stmt, detectCFPattern("break;"));
    // A struct-field line never strips into a pattern: the fallbacks see
    // the original line and find nothing.
    try std.testing.expectEqual(CFPattern.none, detectCFPattern("name: u32,"));
}

test "isWhileLiteralTrue reads through a loop label (EPH-I0115)" {
    // A labeled `while (true)` keeps its literal-true treatment, so no
    // phantom zero-trip edge wires (the EPH-I0110 direction). Without
    // the strip the labeled form read false and blamed post-loop reads.
    try std.testing.expect(isWhileLiteralTrue("outer: while (true) {"));
    try std.testing.expect(isWhileLiteralTrue("outer: while ((true)) {"));
    try std.testing.expect(!isWhileLiteralTrue("outer: while (c) {"));
    try std.testing.expect(isWhileLiteralTrue("while (true) {"));
}

test "buildCFG: arrow text in a body string opens no phantom arm (EPH-I0679)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(x: u8) void {", // 1
        "    switch (x) {", // 2
        "        .a => {", // 3
        "            s = \"=>\";", // 4: string data, not a prong
        "        },", // 5
        "        .b => {", // 6
        "            g();", // 7
        "        },", // 8
        "    }", // 9
        "}", // 10
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // EPH-I0679 quote-mask guard: exactly two arms branch from the header.
    // An unmasked `=>` scan would read line 4 as a prong and open a third.
    const header = findBlockForLine(&cfg, 2) orelse return error.TestUnexpectedResult;
    var arm_count: usize = 0;
    for (cfg.edges.items) |e| {
        if (e.from == header and e.kind == .branch_true) arm_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), arm_count);
}

test "buildCFG: quoted braces do not corrupt depth; comment close counts" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    var x: u32 = 0;", // 2
        "    if (cond) {", // 3
        "        const s = \"{\";", // 4
        "        const c = '{';", // 5
        "        x = 1;", // 6
        "    } // trailing comment", // 7
        "    x = 2;", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(if_block, findBlockForLine(&cfg, 6));
    // `} // comment` is comment-aware now: it pops the if block.
    const after = findBlockForLine(&cfg, 8);
    try std.testing.expect(after != null);
    try std.testing.expect(if_block.? != after.?);
}

test "buildCFG: multiline opener tail braces do not corrupt depth (EPH-I0671)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    if (cond) {", // 2
        "        const s = \\\\ }", // 3: the tail `}` is string data
        "        x = 1;", // 4
        "    }", // 5
        "    x = 2;", // 6
        "}", // 7
    };
    // No-string baseline: same line count, a plain statement in place of the
    // multiline string.
    const baseline = [_][]const u8{
        "fn f(cond: bool) void {", // 1
        "    if (cond) {", // 2
        "        const s = 0;", // 3
        "        x = 1;", // 4
        "    }", // 5
        "    x = 2;", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();
    var base_cfg = try buildCFG(allocator, "f", 1, &baseline);
    defer base_cfg.deinit();

    // The tail `}` must not close the if body early: line 4 stays in the
    // if-true block and the structure matches the no-string baseline.
    try std.testing.expectEqual(base_cfg.blocks.items.len, cfg.blocks.items.len);
    const if_block = findBlockForLine(&cfg, 4);
    try std.testing.expect(if_block != null);
    try std.testing.expectEqual(findBlockForLine(&base_cfg, 4), if_block);
    const after = findBlockForLine(&cfg, 6);
    try std.testing.expect(after != null);
    try std.testing.expect(if_block.? != after.?);
}

test "scanLineForStatementEnd stops at a multiline opener (EPH-I0751)" {
    var depth: usize = 0;
    var mode: QuoteMode = .none;
    // Target text: const s = \\ foo(); bar(); — the tail semicolons are
    // string data, so the statement continues on a later line.
    try std.testing.expect(
        scanLineForStatementEnd("const s = \\\\ foo(); bar();", 0, &depth, &mode) == null,
    );
    try std.testing.expectEqual(@as(usize, 0), depth);
    // A real depth-0 semicolon still terminates the statement.
    depth = 0;
    mode = .none;
    try std.testing.expectEqual(
        @as(?usize, 6),
        scanLineForStatementEnd("foo();", 0, &depth, &mode),
    );
}

test "scanLineForParenClose stops at a multiline opener (EPH-I0751)" {
    var depth: usize = 1;
    var mode: QuoteMode = .none;
    // Target text: a, \\ b); c); — the tail parens are string data, so the
    // group closes on a later line.
    try std.testing.expect(scanLineForParenClose("a, \\\\ b); c);", 0, &depth, &mode) == null);
    try std.testing.expectEqual(@as(usize, 1), depth);
    // A real close paren still balances the group.
    depth = 1;
    mode = .none;
    try std.testing.expectEqual(@as(?usize, 5), scanLineForParenClose("a, b);", 0, &depth, &mode));
}

test "ForLoopTracker.checkLoopEnd ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data and must
    // not close the loop.
    var tracker: ForLoopTracker = .{ .in_loop = true };
    tracker.checkLoopEnd("const s = \\\\ }", 0);
    try std.testing.expect(tracker.in_loop);
    // A real net-negative brace line still ends the loop.
    tracker.checkLoopEnd("}", 0);
    try std.testing.expect(!tracker.in_loop);
}

test "hasOnelineLoopClose classifies one-line loop shapes (EPH-I0785)" {
    // The probe line: the braces balance within the code portion.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { sum +%= buf[x]; }"));
    // A trailing comment does not reopen the close.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } // done"));
    // A stray semicolon after the body still closes on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); };"));
    // A brace inside a string literal is data, not the body close.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { s = \"}\"; }"));
    // Multi-line header: the body brace stays open.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| {"));
    // A comment hides the real close: the body continues on later lines.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| { foo(); // }"));
    // A nested trailing close still leaves the body open.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| { if (y) { foo(); }"));
    // A header anonymous struct with a brace-less body on later lines.
    try std.testing.expect(!hasOnelineLoopClose("for (o.{ 1, 2 }) |x|"));
    // A brace-less body that ends on the line completes the loop
    // (EPH-I0789).
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| foo();"));
    // The body closes mid-line. The extra `}` belongs to an outer block.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } }"));
}

test "hasOnelineLoopClose closes brace-less and trailing-statement loops (EPH-I0789)" {
    // The probe shape: a brace-less body whose statement ends on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| sum +%= buf[x];"));
    // A trailing statement after the balanced body sits outside the loop.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } bar();"));
    // The else block after the balanced close sits outside the loop. Its
    // fills are not loop-carried.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| { foo(); } else {"));
    // A nested brace-less loop completes on the line.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| for (ys) |y| foo();"));
    // A `;` inside a char literal is data. The final `;` ends the body.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| c = ';';"));
    // Call-argument braces stay out of the body balance.
    try std.testing.expect(hasOnelineLoopClose("for (xs) |x| foo(.{ 1, 2 });"));
    // A bare header leaves the body to later lines: the multi-line
    // brace-less shape keeps the historical behavior.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x|"));
    // A body expression that continues past the line is not one-line.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| sum +%="));
    // A `;` in a multiline-string tail is string data, not the body end.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| s = \\\\x; y();"));
    // An unclosed call paren holds the body open past the line.
    try std.testing.expect(!hasOnelineLoopClose("for (xs) |x| foo(a,"));
}

test "computeBraceDepth ignores braces in a multiline opener tail (EPH-I0751)" {
    // Target text: const s = \\ } — the tail `}` is string data and must
    // not pay the caller's carried depth.
