    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (b) {", // 2
        "        if (a) {", // 3
        "            f();", // 4
        "        }", // 5
        "        x = 1;", // 6: no else — the deferred close wires the merge
        "    }", // 7
        "    h();", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const outer_false = cfgSucc(&cfg, cfg.entry_block, .branch_false) orelse
        return error.TestUnexpectedResult;
    const outer_true = findBlockForLine(&cfg, 3) orelse return error.TestUnexpectedResult;
    const inner_merge = cfgSucc(&cfg, outer_true, .branch_false) orelse
        return error.TestUnexpectedResult;
    const stmt_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(inner_merge, stmt_block);
    const h_block = findBlockForLine(&cfg, 8) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(outer_false, h_block);
    try std.testing.expect(cfgHasEdge(&cfg, stmt_block, h_block, .sequential));
}

test "buildCFG: lone close then next-line else wires four blocks" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool) void {", // 1
        "    if (a) {", // 2
        "        g();", // 3
        "    }", // 4: lone close defers the if entry into pending_else
        "    else {", // 5: claims the saved entry instead of popping again
        "        h();", // 6
        "    }", // 7
        "    i();", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // entry + true + else + merge: the deferred close paired with the else.
    try std.testing.expectEqual(@as(usize, 4), cfg.blocks.items.len);
    const entry = cfg.entry_block;
    const true_block = cfgSucc(&cfg, entry, .branch_true) orelse
        return error.TestUnexpectedResult;
    const else_block = cfgSucc(&cfg, entry, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 5), cfg.blocks.items[else_block].start_line);
    const g_block = findBlockForLine(&cfg, 3) orelse return error.TestUnexpectedResult;
    const h_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(true_block, g_block);
    try std.testing.expectEqual(else_block, h_block);
    const i_block = findBlockForLine(&cfg, 8) orelse return error.TestUnexpectedResult;
    try std.testing.expect(i_block != true_block);
    try std.testing.expect(i_block != else_block);
    try std.testing.expect(cfgHasEdge(&cfg, true_block, i_block, .sequential));
    try std.testing.expect(cfgHasEdge(&cfg, else_block, i_block, .sequential));
}

test "buildCFG: multi-line else-if chain pairs each close with its else" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (a) {", // 2
        "        g();", // 3
        "    }", // 4: defers the if entry
        "    else if (b) {", // 5: claims it, pushes the else-if entry
        "        h();", // 6
        "    }", // 7: defers the else-if entry
        "    else {", // 8: claims it
        "        j();", // 9
        "    }", // 10
        "    i();", // 11
        "}", // 12
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    const entry = cfg.entry_block;
    const g_block = findBlockForLine(&cfg, 3) orelse return error.TestUnexpectedResult;
    const h_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    const j_block = findBlockForLine(&cfg, 9) orelse return error.TestUnexpectedResult;
    // Three bodies, three distinct blocks.
    try std.testing.expect(g_block != h_block);
    try std.testing.expect(h_block != j_block);
    try std.testing.expect(g_block != j_block);
    // The chain branches from the entry: true body, then the else-if header.
    try std.testing.expectEqual(g_block, cfgSucc(&cfg, entry, .branch_true) orelse
        return error.TestUnexpectedResult);
    // The else-if condition is a real branch (EPH-I0087): the arm body sits
    // on the header's true edge, the final else body on its false edge.
    const elseif_header = cfgSucc(&cfg, entry, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(h_block, cfgSucc(&cfg, elseif_header, .branch_true) orelse
        return error.TestUnexpectedResult);
    try std.testing.expectEqual(j_block, cfgSucc(&cfg, elseif_header, .branch_false) orelse
        return error.TestUnexpectedResult);
    // One shared merge past the chain.
    const i_block = findBlockForLine(&cfg, 11) orelse return error.TestUnexpectedResult;
    try std.testing.expect(i_block != g_block);
    try std.testing.expect(i_block != h_block);
    try std.testing.expect(i_block != j_block);
    try std.testing.expect(cfgHasEdge(&cfg, h_block, i_block, .sequential));
    try std.testing.expect(cfgHasEdge(&cfg, j_block, i_block, .sequential));
}

test "buildCFG: bare Allman else-if line opens the chain (EPH-I0323)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (a) {", // 2
        "        g();", // 3
        "    }", // 4: lone close defers the if entry
        "    else if", // 5: bare else-if line, condition on the next line
        "    (b) { h(); }", // 6
        "    i();", // 7
        "}", // 8
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // The exact `else if` pattern claims the deferred close, so the chain
    // opens: the else body becomes the new condition header with a true
    // arm and a false fallthrough (pre-fix the bare line matched nothing,
    // the deferred close finished as no-else, and the chain vanished —
    // band-B01a F8).
    const entry = cfg.entry_block;
    const elseif_header = cfgSucc(&cfg, entry, .branch_false) orelse
        return error.TestUnexpectedResult;
    const arm = cfgSucc(&cfg, elseif_header, .branch_true) orelse
        return error.TestUnexpectedResult;
    const fallthrough = cfgSucc(&cfg, elseif_header, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(arm, findBlockForLine(&cfg, 6));
    // The arm and the fallthrough join one merge that holds the line after
    // the chain.
    const merge = findBlockForLine(&cfg, 7) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, arm, merge, .sequential));
    try std.testing.expect(cfgHasEdge(&cfg, fallthrough, merge, .sequential));
}

test "buildCFG: two closes on one line preserve the inner merge wiring (EPH-I0091)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (a) {", // 2
        "        if (b) {", // 3
        "            g();", // 4
        "        } }", // 5: both closes on one line
        "    h();", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // The second close must not overwrite the first deferral: the inner
    // merge wiring (inner body -> inner merge, inner merge -> post-outer
    // block) must survive (pre-fix: pending_else holds only one entry, so
    // the second close drops the inner entry and the inner body wires
    // straight to the outer merge — EPH-I0091).
    const entry = cfg.entry_block;
    const outer_true = cfgSucc(&cfg, entry, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_body = cfgSucc(&cfg, outer_true, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_merge = cfgSucc(&cfg, outer_true, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, inner_body, inner_merge, .sequential));
    const h_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, inner_merge, h_block, .sequential));
}

test "buildCFG: text between two same-line closes keeps the inner fall-through (EPH-I0317)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (a) {", // 2
        "        if (b) {", // 3
        "            g();", // 4
        "        } h(); }", // 5: close, text, close on one line
        "    i();", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // The first close defers the inner entry, and the text between the
    // closes keeps the deferral pending. The second close then hits the
    // EPH-I0091 finish-before-overwrite guard in handleBlockEndOrDefer,
    // which wires the inner body into the inner merge before it claims
    // the slot. This line has no else keyword, so finishDeferredBeforeElse
    // never runs here; the pin guards the interleaved-text variant the
    // two-closes-one-line EPH-I0091 test lacks.
    const entry = cfg.entry_block;
    const outer_true = cfgSucc(&cfg, entry, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_body = cfgSucc(&cfg, outer_true, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_merge = cfgSucc(&cfg, outer_true, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, inner_body, inner_merge, .sequential));
    const i_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, inner_merge, i_block, .sequential));
}

test "buildCFG: else after two same-line closes pairs with the outer entry (EPH-I0317)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool, b: bool) void {", // 1
        "    if (a) {", // 2
        "        if (b) {", // 3
        "            g();", // 4
        "        } } else {", // 5: both closes and the else on one line
        "            h();", // 6
        "        }", // 7
        "    i();", // 8
        "}", // 9
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // The second close precedes the else keyword, so the walk skips it and
    // the else must claim the entry THAT close would have popped — the
    // outer if. The deferred inner entry is finished first (pre-fix: the
    // else claimed the inner deferral, the outer entry lingered, and the
    // inner body never wired its fall-through — band-B01a F1).
    const entry = cfg.entry_block;
    const outer_true = cfgSucc(&cfg, entry, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_body = cfgSucc(&cfg, outer_true, .branch_true) orelse
        return error.TestUnexpectedResult;
    const inner_merge = cfgSucc(&cfg, outer_true, .branch_false) orelse
        return error.TestUnexpectedResult;
    // The first entry's fall-through edge survives the else claim.
    try std.testing.expect(cfgHasEdge(&cfg, inner_body, inner_merge, .sequential));
    // The else body sits on the entry's false edge and owns the h(); line.
    const else_body = cfgSucc(&cfg, entry, .branch_false) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(else_body, findBlockForLine(&cfg, 6));
    // The true path (through the inner merge) and the else path join one
    // merge that holds the line after the construct.
    const merge = findBlockForLine(&cfg, 8) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, inner_merge, merge, .sequential));
    try std.testing.expect(cfgHasEdge(&cfg, else_body, merge, .sequential));
}

test "buildCFG: Allman else brace after same-line if is a control open (EPH-I0089)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    const lines = [_][]const u8{
        "fn f(a: bool) void {", // 1
        "    if (a) { f(); } else", // 2: same-line if, bare else
        "    {", // 3: Allman else brace on the NEXT line
        "        g();", // 4
        "    }", // 5
        "    h();", // 6
        "}", // 7
    };

    var cfg = try buildCFG(allocator, "f", 1, &lines);
    defer cfg.deinit();

    // The Allman else `{` must claim the else entry as a control open, so
    // its close pops the else block and the fn's trailing `}` finds a
    // balanced stack (pre-fix: the else brace classifies .expr, the
    // else_open_pending dies at the line boundary, and the trailing close
    // leaves the else entry lingering — EPH-I0089).
    const entry = cfg.entry_block;
    const else_arm = cfgSucc(&cfg, entry, .branch_false) orelse
        return error.TestUnexpectedResult;
    const body_block = findBlockForLine(&cfg, 4) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(else_arm, body_block);
    const merge = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cfgHasEdge(&cfg, else_arm, merge, .sequential));
    // The else close pops its entry and wires to the merge: the trailing
    // `h();` line is the merge, never a block left open by a lingering
    // entry (pre-fix the entry lingered — EPH-I0089).
    const h_block = findBlockForLine(&cfg, 6) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(merge, h_block);
}

