        \\            .a => {
        \\                break;
        \\            },
        \\            .b => {
        \\                y = 1;
        \\            },
        \\            else => {
        \\                y = 1;
        \\            },
        \\        }
        \\        use(y);
        \\    }
        \\}
    ;
