    // line 6 is a potential undefined read and must be reported.
    const content =
        \\fn singleBranch(cond: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        x = 1;
        \\    }
        \\    return x;
        \\}
