test "ZA607: one-line else-if chain unassigned path stays silent (EPH-I0872, documented residual)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // r2_d.zig: `if (a) { x = 1; } else if (b) { return 1; } return x;`
    // stays silent though the A=false,B=false path reads uninitialized
    // x. The chain line records no column spans (else-if lines are
    // excluded from span recording), so the if-arm's fill gens the entry
    // block and covers every downstream path. The chain parsers collect
    // branches only past a depth-zero close, so the same-line else-if
    // arm never joins the list; the residual is documented at
    // buildEarlyReturnMemo and pinned here (EPH-I0872, adjudicated
    // documentation-arm per the plan).
    const content =
        \\fn f(a: bool, b: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (a) { x = 1; } else if (b) { return 1; }
        \\    return x;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_i0872_chain.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        0,
        countRuleIssues(run.issues.items, "da_i0872_chain.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "ZA607: multi-line else-if chain split fires on the unassigned path (EPH-I0872, EPH-I1063)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // t4.zig: the A=false,B=true path runs sink() and leaves x
    // uninitialized at the trailing read — a real uninitialized read.
    // Pre-EPH-I1063 the line-start else-if never claimed the deferred
    // if entry (the residual pinned silence here): the final else line
    // had no pattern, `x = 2` landed in the merge block, and the
    // trailing read stayed covered. The EPH-I1063 claim makes the
    // chain split arm by arm, so the b-arm's fallthrough reaches the
    // merge without an assignment and the read fires at the warning
    // grade (the chain grades arm by arm). The one-line twin above
    // keeps its documented silence (EPH-I0872).
    const content =
        \\fn sink() void {}
        \\fn f(a: bool, b: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (a) { x = 1; }
        \\    else if (b) { sink(); }
        \\    else { x = 2; }
        \\    return x;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_i0872_mlchain.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_i0872_mlchain.zig", RULE_DEFINITE_ASSIGNMENT),
    );
    for (run.issues.items) |issue| {
        if (!mem.eql(u8, issue.rule, RULE_DEFINITE_ASSIGNMENT)) continue;
        try std.testing.expect(issue.line == 7);
        try std.testing.expect(issue.severity == .warning);
    }
}

test "ZA607: one-line chain with all arms filling stays silent (EPH-I0113)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The issue's exact repro: the chain link and the final bare else
    // share one line (`} else if (d) { x = 2; } else {`) and every arm
    // fills x. Pre-fix the second handleElse read the bare else as a
    // chain link (elseChainsIntoIf scanned the whole line's first else)
    // and opened a phantom arm, so the fill attribution leaked across
    // the fallthrough path. The position-aware chain test plus the
    // post-else arm spans must keep the read silent — every path fills.
    const content =
        \\fn use(v: u32) void {
        \\    _ = v;
        \\}
        \\fn f(c: bool, d: bool) void {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        x = 1;
        \\    } else if (d) { x = 2; } else {
        \\        x = 3;
        \\    }
        \\    use(x);
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_i0113_allfill.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        0,
        countRuleIssues(run.issues.items, "da_i0113_allfill.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

