test "isAssignmentOp rejects switch prong arrow and comparisons" {
    // EPH-I0082: `=>` is a switch prong, not an assignment — accepting it
    // blinded the read scan to genuine reads in prong position and poisoned
    // the gen set with a non-assignment.
    try std.testing.expect(isAssignmentOp("= 1;"));
    try std.testing.expect(isAssignmentOp("="));
    try std.testing.expect(!isAssignmentOp("== 1;"));
    try std.testing.expect(!isAssignmentOp("=> 1,"));
    try std.testing.expect(!isAssignmentOp(">= 1;"));
    try std.testing.expect(!isAssignmentOp("x = 1;"));
}

test "hasModifyingMethodCall scans every occurrence" {
    // EPH-I0082: the first occurrence may be a different variable (box);
    // checking only it missed the genuine receiver later on the line.
    try std.testing.expect(hasModifyingMethodCall("box.append(1); x.append(2);", "x"));
    try std.testing.expect(!hasModifyingMethodCall("box.append(1);", "x"));
    try std.testing.expect(!hasModifyingMethodCall("foo.x.append(1);", "x"));
}

test "hasModifyingMethodCall skips whitespace-spaced dot receivers (EPH-I0790)" {
    // `foo . list.append(1)` mutates foo's field through a spaced dot,
    // not the local list. The identifier boundary stays on the immediate
    // byte, so a space-separated preceding token keeps the local verdict.
    try std.testing.expect(!hasModifyingMethodCall("foo . list.append(1);", "list"));
    try std.testing.expect(!hasModifyingMethodCall("foo .\tlist.append(1);", "list"));
    try std.testing.expect(hasModifyingMethodCall("list.append(1);", "list"));
}

test "blockContainsAssignment scans every occurrence with word boundaries" {
    // EPH-I0082: a read occurrence (x == 1) must not hide a later genuine
    // assignment on the same line, and `box = 1` must not count for x.
    const lines = [_][]const u8{ "x == 1; x = 2;", "}" };
    try std.testing.expect(blockContainsAssignment(&lines, 0, 1, "x"));
    const other = [_][]const u8{"box = 1;"};
    try std.testing.expect(!blockContainsAssignment(&other, 0, 1, "x"));
    const field = [_][]const u8{"foo.x = 1;"};
    try std.testing.expect(!blockContainsAssignment(&field, 0, 1, "x"));
}

test "blockContainsAssignment skips whitespace-spaced dot field writes (EPH-I0790)" {
    // `foo . x = 1` writes foo's field through a spaced dot, not the
    // local x.
    const spaced = [_][]const u8{"foo . x = 1;"};
    try std.testing.expect(!blockContainsAssignment(&spaced, 0, 1, "x"));
    const local = [_][]const u8{"x = 1;"};
    try std.testing.expect(blockContainsAssignment(&local, 0, 1, "x"));
}

test "nextAssignmentOccurrence skips whitespace-spaced dot field writes (EPH-I0790)" {
    // `foo . buf = 1` writes foo's field through a spaced dot, so the
    // occurrence is no assignment target of the local buf.
    var s: usize = 0;
    var scan = AssignmentScanCtx{
        .cls = LineClassifier.init("foo . buf = 1;"),
        .comment_start = null,
    };
    try std.testing.expect(nextAssignmentOccurrence("foo . buf = 1;", "buf", &s, &scan) == null);
    s = 0;
    scan = AssignmentScanCtx{
        .cls = LineClassifier.init("foo .\tbuf = 1;"),
        .comment_start = null,
    };
    try std.testing.expect(nextAssignmentOccurrence("foo .\tbuf = 1;", "buf", &s, &scan) == null);
    s = 0;
    scan = AssignmentScanCtx{ .cls = LineClassifier.init("buf = 1;"), .comment_start = null };
    try std.testing.expect(nextAssignmentOccurrence("buf = 1;", "buf", &s, &scan) != null);
}

test "hasSliceOccurrence skips whitespace-spaced dot field slices (EPH-I0795)" {
    // `foo . x[i]` reads foo's field through a spaced dot, never the local x.
    try std.testing.expect(!hasSliceOccurrence("foo . x[i]", "x"));
    try std.testing.expect(!hasSliceOccurrence("foo .\tx[i]", "x"));
    try std.testing.expect(!hasSliceOccurrence("foo.x[i]", "x"));
    try std.testing.expect(hasSliceOccurrence("x[i]", "x"));
}

test "nextFillCallOccurrence keeps verdict parity on spaced-dot occurrences (EPH-I0795)" {
    // The dot guard's spacing never changes this verdict: a return needs
    // '&' (call arm) or '(' (builtin arm) immediately left of the name, so
    // a spaced-dot occurrence always falls through. The guard converges on
    // hasLeftDot for consistency. The pin locks the parity.
    var s: usize = 0;
    try std.testing.expect(nextFillCallOccurrence("foo . buf;", "buf", &s) == null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("foo.buf;", "buf", &s) == null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("fill(&buf);", "buf", &s) != null);
}

test "findVarUseOnLine skips whitespace-spaced dot field reads (EPH-I0795)" {
    // `foo . item == 1` reads foo's field through a spaced dot, never the
    // local item.
    try std.testing.expect(findVarUseOnLine("foo . item == 1;", "item") == null);
    try std.testing.expect(findVarUseOnLine("foo.item == 1;", "item") == null);
    try std.testing.expect(findVarUseOnLine("item == 1;", "item") != null);
}

test "isReturnTupleElement skips whitespace-spaced dot field elements (EPH-I0795)" {
    // `foo . buf` inside the tuple is foo's field through a spaced dot,
    // never the local buf as an element.
    const spaced = ".{ foo . buf, 0 }";
    const spaced_region: TupleElementRegion = .{ .from = 0, .to = spaced.len };
    try std.testing.expect(!isReturnTupleElement(spaced, "buf", spaced_region));
    const immediate = ".{ foo.buf, 0 }";
    const imm_region: TupleElementRegion = .{ .from = 0, .to = immediate.len };
    try std.testing.expect(!isReturnTupleElement(immediate, "buf", imm_region));
    const plain = ".{ buf, 0 }";
    const plain_region: TupleElementRegion = .{ .from = 0, .to = plain.len };
    try std.testing.expect(isReturnTupleElement(plain, "buf", plain_region));
}

test "isDirectFreeOfVar skips whitespace-spaced dot receivers (EPH-I0796)" {
    // `foo . buf.free()` frees foo's field through a spaced dot, never the
    // local buf.
    try std.testing.expect(!isDirectFreeOfVar("foo . buf.free();", "buf"));
    try std.testing.expect(!isDirectFreeOfVar("foo.buf.free();", "buf"));
    try std.testing.expect(isDirectFreeOfVar("buf.free();", "buf"));
    try std.testing.expect(isDirectFreeOfVar("alloc.free(buf);", "buf"));
}

test "isDirectFreeOfVar keeps sibling and paren-nested ranges element accesses (EPH-I1010)" {
    // The chained shape `buf[a..][b]` reads one element of a view; the
    // paren-nested shape `buf[f(a..b)]` cannot parse in Zig but must not
    // fabricate a view either. The endpoint-paren view and the plain view
    // still count as frees of the tracked var.
    try std.testing.expect(!isDirectFreeOfVar("allocator.free(buf[1..][0]);", "buf"));
    try std.testing.expect(!isDirectFreeOfVar("allocator.free(buf[f(a..b)]);", "buf"));
    try std.testing.expect(isDirectFreeOfVar("allocator.free(buf[1..]);", "buf"));
    try std.testing.expect(isDirectFreeOfVar("allocator.free(buf[(a + b) .. (c + d)]);", "buf"));
}

test "isStructFieldUndefined accepts whitespace-spaced dot fields (EPH-I0796)" {
    // `. field = undefined` inits a struct field through a spaced dot: the
    // field is undefined, never a variable declaration.
    try std.testing.expect(isStructFieldUndefined(". field = undefined", 8));
    try std.testing.expect(isStructFieldUndefined(".field = undefined", 7));
    try std.testing.expect(!isStructFieldUndefined("field = undefined", 6));
}

test "isGuardAssignment skips whitespace-spaced dot field writes (EPH-I0796)" {
    // `foo . guard = true` writes foo's field through a spaced dot, never
    // the guard local.
    try std.testing.expect(!isGuardAssignment("foo . guard = true;", "guard"));
    try std.testing.expect(!isGuardAssignment("foo .\tguard = true;", "guard"));
    try std.testing.expect(!isGuardAssignment("foo.guard = true;", "guard"));
    try std.testing.expect(isGuardAssignment("guard = true;", "guard"));
}

test "hasDirectFill accepts a whitespace-spaced dot chain pointer (EPH-I0796)" {
    // `&opts. buf` passes a field pointer through a spaced dot: the
    // call-fill heuristic fills through it the same as `&opts.buf`.
    try std.testing.expect(hasDirectFill("fill(&opts.buf);", "buf"));
    try std.testing.expect(hasDirectFill("fill(&opts. buf);", "buf"));
    try std.testing.expect(!hasDirectFill("use(buf);", "buf"));
}

test "isPlainCallName rejects whitespace-spaced dot method calls (EPH-I0804)" {
    // `foo . bar(` is a method call through a spaced dot: the immediate-
    // byte guard read content[fn_start - 1], so the space masked the
    // receiver and the call read as plain (EPH-I0804).
    try std.testing.expect(!isPlainCallName("foo . bar(", 6, "bar"));
    try std.testing.expect(!isPlainCallName("foo .\tbar(", 6, "bar"));
    try std.testing.expect(!isPlainCallName("foo.bar(", 4, "bar"));
    try std.testing.expect(isPlainCallName("plain(", 0, "plain"));
}

test "hasAmpBeforeChain reaches the amp across spaced chain dots (EPH-I0805)" {
    // `&opts . buf` is a pointer to opts's field: the walk read immediate
    // bytes only, so the space before the dot broke the chain and the
    // fill pointer evaded Pattern 1 (EPH-I0805).
    try std.testing.expect(hasAmpBeforeChain("&opts . buf", 8));
    try std.testing.expect(hasAmpBeforeChain("&opts .\tbuf", 8));
    try std.testing.expect(hasAmpBeforeChain("&opts. buf", 7));
    try std.testing.expect(hasAmpBeforeChain("&opts.buf", 6));
    try std.testing.expect(!hasAmpBeforeChain("opts . buf", 8));
    try std.testing.expect(!hasAmpBeforeChain("call(&x, opts . buf)", 16));
}

test "hasDirectFill accepts a spaced-dot chain pointer with space before the dot (EPH-I0805)" {
    // `&opts . buf` fills through the same spaced-dot chain as the
    // EPH-I0796 forms: Pattern 1 must not depend on where the space sits.
    try std.testing.expect(hasDirectFill("fill(&opts . buf);", "buf"));
    try std.testing.expect(hasDirectFill("fill(&opts. buf);", "buf"));
    try std.testing.expect(hasDirectFill("fill(&opts.buf);", "buf"));
    try std.testing.expect(!hasDirectFill("use(opts . buf);", "buf"));
}

test "hasDirectFill rejects an infix bitwise-and chain (EPH-I0814)" {
    // `flags & opts.buf` is bitwise-and, not a chain prefix: the widened
    // walk crossed the space and read the infix amp as the leading '&',
    // masking the ZA607 read-before-undefined report (EPH-I0814).
    try std.testing.expect(!hasDirectFill("const m = flags & opts.buf;", "buf"));
    try std.testing.expect(!hasAmpBeforeChain("flags & opts.buf", 13));
}

test "hasAmpBeforeChain keeps prefix address-of positions (EPH-I0814)" {
    // The infix rejection must not eat genuine prefix address-of: after a
    // keyword, an operator, `(`, `,`, `;`, `=` — the amp starts the chain.
    try std.testing.expect(hasAmpBeforeChain("return &opts . buf", 15));
    try std.testing.expect(hasAmpBeforeChain("x = &opts . buf", 12));
    try std.testing.expect(hasAmpBeforeChain("f(&opts.buf)", 8));
    try std.testing.expect(hasAmpBeforeChain("( &opts.buf )", 8));
}

test "hasDirectFill keeps prefix address-of shapes (EPH-I0814)" {
    // The same prefix positions through the consumer: a keyword, `=`, or
    // `(` before the amp keeps the fill verdict (EPH-I0814).
    try std.testing.expect(hasDirectFill("const p = &opts . buf;", "buf"));
    try std.testing.expect(hasDirectFill("return &opts . buf;", "buf"));
    try std.testing.expect(hasDirectFill("use(&opts.buf);", "buf"));
    try std.testing.expect(hasDirectFill("use( &opts.buf );", "buf"));
}

test "hasAmpBeforeChain discriminates by the byte right of the amp (EPH-I0815)" {
    // zig fmt pads binary operators symmetrically, so an infix '&' has
    // space/tab right on fmt-clean code and a prefix `&` never does. The
    // left-side enumeration cannot see past `)`, `*`, `?`, and block
    // labels (EPH-I0815).
    try std.testing.expect(!hasAmpBeforeChain("p.* & opts.buf", 11));
    try std.testing.expect(!hasAmpBeforeChain("p.? & opts.buf", 11));
    try std.testing.expect(!hasAmpBeforeChain("'a' & opts.buf", 11));
    try std.testing.expect(hasAmpBeforeChain("if (flag) &opts.buf else null", 16));
    try std.testing.expect(hasAmpBeforeChain("break :blk &opts.buf", 17));
}

test "hasDirectFill takes the right-side amp verdict (EPH-I0815)" {
    // The same discrimination through the consumer: deref, unwrap, and
    // char-literal operands keep the ZA607 read-before-undefined report;
    // an if-else value and a labeled break value still fill (EPH-I0815).
    try std.testing.expect(!hasDirectFill("const m = p.* & opts.buf;", "buf"));
    try std.testing.expect(!hasDirectFill("const m = p.? & opts.buf;", "buf"));
    try std.testing.expect(!hasDirectFill("const m = 'a' & opts.buf;", "buf"));
    try std.testing.expect(hasDirectFill("const p = if (flag) &opts.buf else null;", "buf"));
    try std.testing.expect(hasDirectFill("const v = blk: { if (flag) break :blk &opts.buf; };", "buf"));
}

test "hasAmpBeforeChain bridges the amp-paren shape (EPH-I0816)" {
    // `use(&(opts.buf))` groups the chain operand: the walk stopped at
    // the `(` before reaching the amp, so the fill credit the plain
    // `use(&opts.buf)` form receives was denied (EPH-I0816). The bridge
    // crosses the paren only when `&` (or a nested paren) sits
    // immediately left. A call paren (`use(foo(opts.buf))`) and the
    // fmt-clean infix shape (`flags & (opts.buf)`) still stop the walk.
    const paren = "use(&(opts.buf));";
    try std.testing.expect(hasAmpBeforeChain(paren, mem.indexOf(u8, paren, "buf").?));
    const nested = "use(&((opts.buf)));";
    try std.testing.expect(hasAmpBeforeChain(nested, mem.indexOf(u8, nested, "buf").?));
    const call = "use(foo(opts.buf));";
    try std.testing.expect(!hasAmpBeforeChain(call, mem.indexOf(u8, call, "buf").?));
    const infix = "const m = flags & (opts.buf);";
    try std.testing.expect(!hasAmpBeforeChain(infix, mem.indexOf(u8, infix, "buf").?));
}

test "hasDirectFill credits the amp-paren chain pointer (EPH-I0816)" {
    // Pattern 1 gives `use(&(opts.buf))` the same fill credit as
    // `use(&opts.buf)`: the paren groups the chain operand, the amp
    // still prefixes it. The fmt-clean infix shape (`flags & (opts.buf)`)
    // keeps the EPH-I0814 rejection through the consumer (EPH-I0816).
    try std.testing.expect(hasDirectFill("use(&(opts.buf));", "buf"));
    try std.testing.expect(hasDirectFill("return &(opts.buf);", "buf"));
    try std.testing.expect(hasDirectFill("use((&opts.buf));", "buf"));
    try std.testing.expect(!hasDirectFill("use(foo(opts.buf));", "buf"));
    try std.testing.expect(!hasDirectFill("const m = flags & (opts.buf);", "buf"));
}

test "hasDirectFill credits the amp-paren bare name (EPH-I0822)" {
    // `use(&(x))` groups the bare name the same as the chain form: the
    // amp still prefixes it, so Pattern 1 must give the fill credit
    // `use(&x)` receives (EPH-I0822). The bare-name arm crosses the paren
    // through the same bridge — `&` or `(` immediately left — so a call
    // paren (`use(foo(x))`), a plain grouping read (`use((x))`), and the
    // fmt-clean infix shape (`flags & (x)`) still stop it.
    try std.testing.expect(hasDirectFill("use(&(x));", "x"));
    try std.testing.expect(hasDirectFill("use(&((x)));", "x"));
    try std.testing.expect(hasDirectFill("return &(x);", "x"));
    try std.testing.expect(hasDirectFill("use(foo(&(x)));", "x"));
    try std.testing.expect(hasDirectFill("use((&x));", "x"));
    try std.testing.expect(!hasDirectFill("use(foo(x));", "x"));
    try std.testing.expect(!hasDirectFill("use((x));", "x"));
    try std.testing.expect(!hasDirectFill("use(&x, (y));", "y"));
    try std.testing.expect(!hasDirectFill("const m = flags & (x);", "x"));
}

test "nextFillCallOccurrence bridges the amp-paren bare name (EPH-I0822)" {
    // The walk-level fill-call arm needs '&' immediately left of the
    // name, so `use(&(x))` evaded the statement-precise credit. The
    // grouping paren bridges through the same walk as the line-level
    // Pattern 1 arm; the non-call forms stay unmatched (EPH-I0822).
    var s: usize = 0;
    try std.testing.expect(nextFillCallOccurrence("use(&(x));", "x", &s) != null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("use(&((x)));", "x", &s) != null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("return &(x);", "x", &s) == null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("const p = &(x);", "x", &s) == null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("use(foo(x));", "x", &s) == null);
    s = 0;
    try std.testing.expect(nextFillCallOccurrence("use((x));", "x", &s) == null);
    s = 0;
    // The bridge must not shadow the bare @memset/@memcpy dest arm.
    try std.testing.expect(nextFillCallOccurrence("@memset(x, 0);", "x", &s) != null);
}

test "ZA607: parenthesized bare-name amp fill stays silent (EPH-I0822)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // End-to-end parity: `use(&(x))` and `use(&((x)))` silence the read
    // the same as `use(&x)`, while the plain grouping read `use((x))` and
    // the by-value call read `use(foo(x))` keep the ZA607 report. The
    // conditional forms exercise the gen-set path: the fill sits inside an
    // if-block, so the collection-time fill-before-use scan cannot drop
    // the var — the statement-precise gen and the fill-line read
    // exemption must carry the parity (EPH-I0822).
    const content =
        \\fn parenFill() u32 {
        \\    var x: u32 = undefined;
        \\    use(&(x));
        \\    return x;
        \\}
        \\fn nestedFill() u32 {
        \\    var x: u32 = undefined;
        \\    use(&((x)));
        \\    return x;
        \\}
        \\fn plainFill() u32 {
        \\    var x: u32 = undefined;
        \\    use(&x);
        \\    return x;
        \\}
        \\fn plainRead() u32 {
        \\    var x: u32 = undefined;
        \\    use((x));
        \\    return x;
        \\}
        \\fn callRead() u32 {
        \\    var x: u32 = undefined;
        \\    use(foo(x));
        \\    return x;
        \\}
        \\fn parenFillCond(cond: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        use(&(x));
        \\        return x;
        \\    }
        \\    return 0;
        \\}
        \\fn plainFillCond(cond: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        use(&x);
        \\        return x;
        \\    }
        \\    return 0;
        \\}
        \\fn plainReadCond(cond: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (cond) {
        \\        use((x));
        \\        return x;
        \\    }
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_parenfill_bare.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        3,
        countRuleIssues(run.issues.items, "da_parenfill_bare.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "isStructFieldPattern accepts whitespace-spaced dot fields (EPH-I0796)" {
    // `. field` through a spaced dot is still struct field notation.
    try std.testing.expect(isStructFieldPattern(". field = undefined", 8));
    try std.testing.expect(isStructFieldPattern(".field = undefined", 7));
    try std.testing.expect(!isStructFieldPattern("field = undefined", 6));
}

test "ZA607: or-guard read not suppressed by other-var assignment in body" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // EPH-I0082 repro: blockContainsAssignment matched "x" inside "box" and
    // accepted the `=` after it, so isOrShortCircuitSafe suppressed the
    // genuine condition read of x.
    const content =
        \\fn reproCondOnly(c: bool) void {
        \\    var x: u32 = undefined;
        \\    if (c or x == 1) {
        \\        box = 1;
        \\    }
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_orguard.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_orguard.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "ZA607: or-guard read fires outside a loop and without a null guard" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // EPH-I0330 (band-B01b F-04): the loop narrative needs a loop and a
    // guard that is null at the if. This shape has neither: on the
    // c == false path the RHS `x == 1` reads uninitialized x. It was
    // pinned silent before the fix — that pin recorded the false
    // negative.
    const content =
        \\fn negOr(c: bool) void {
        \\    var x: u32 = undefined;
        \\    if (c or x == 1) {
        \\        x = 1;
        \\    }
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_orguard_neg.zig", content);
    defer run.deinit(allocator);

    try expectSingleDAIssue(&run, "da_orguard_neg.zig", 3, "'x'");
}

test "ZA607: correlated-guard read not suppressed by other-var assignment" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // EPH-I0082: same name-blindness via the isCorrelatedGuardRead call
    // site of blockContainsAssignment — `box = 1` is not an x assignment.
    const content =
        \\fn reproCorr(c: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        box = 1;
        \\    }
        \\    if (c) {
        \\        return x;
        \\    }
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_corrguard.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_corrguard.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "ZA607: correlated guard with genuine assignment stays silent" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Genuine correlated assignment must keep suppressing (x is read only
    // under the same guard that assigned it).
    const content =
        \\fn negCorr(c: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        x = 1;
        \\    }
        \\    if (c) {
        \\        return x;
        \\    }
        \\    return 0;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_corr_neg.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        0,
        countRuleIssues(run.issues.items, "da_corr_neg.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "positionsInSameBlock is exact on same-line and sibling shapes (EPH-I0331)" {
    // Same-line pair inside one brace pair: the same block.
    const same_line = [_][]const u8{"if (c1) { guard = 1; x = 2; }"};
    const gpos = mem.indexOf(u8, same_line[0], "guard").?;
    const xpos = mem.indexOf(u8, same_line[0], "x = 2").?;
    try std.testing.expect(positionsInSameBlock(
        &same_line,
        .{ .line = 0, .col = gpos },
        .{ .line = 0, .col = xpos },
        0,
    ));

    // Same-line pair after the block closed: different blocks.
    const after_close = [_][]const u8{"if (c1) { guard = 1; } x = 2;"};
    const gpos2 = mem.indexOf(u8, after_close[0], "guard").?;
    const xpos2 = mem.indexOf(u8, after_close[0], "x = 2").?;
    try std.testing.expect(!positionsInSameBlock(
        &after_close,
        .{ .line = 0, .col = gpos2 },
        .{ .line = 0, .col = xpos2 },
        0,
    ));

    // Adjacent lines inside one multi-line block: the same block. The
    // columns are trimmed-space (the caller rule): the fixture lines
    // carry their own indent, and the occurrences sit at trimmed col 0.
    const multi = [_][]const u8{
        "if (c1) {",
        "    guard = 1;",
        "    x = 2;",
        "}",
    };
    try std.testing.expect(positionsInSameBlock(
        &multi,
        .{ .line = 1, .col = 0 },
        .{ .line = 2, .col = 0 },
        1,
    ));

    // Sibling one-line branches: the c1 block closes on the guard's line.
    const siblings = [_][]const u8{
        "if (c1) { guard = 1; }",
        "if (c2) { x = 2; }",
    };
    const gpos3 = mem.indexOf(u8, siblings[0], "guard").?;
    const xpos3 = mem.indexOf(u8, siblings[1], "x = 2").?;
    try std.testing.expect(!positionsInSameBlock(
        &siblings,
        .{ .line = 0, .col = gpos3 },
        .{ .line = 1, .col = xpos3 },
        0,
    ));

    // The else-arm dip: the depth recovers on the `} else {` line, but
    // the dip below the guard depth closes the guard block.
    const else_dip = [_][]const u8{
        "if (c1) {",
        "    guard = 1;",
        "} else {",
        "    x = 2;",
        "}",
    };
    try std.testing.expect(!positionsInSameBlock(
        &else_dip,
        .{ .line = 1, .col = 0 },
        .{ .line = 3, .col = 0 },
        1,
    ));

    // A nested block that opens and closes inside the guard block does
    // not split it: the pair stays in the same block.
    const nested_balanced = [_][]const u8{
        "if (c1) {",
        "    guard = 1;",
        "    { z = 1; }",
        "    x = 2;",
        "}",
    };
    try std.testing.expect(positionsInSameBlock(
        &nested_balanced,
        .{ .line = 1, .col = 0 },
        .{ .line = 3, .col = 0 },
        1,
    ));

    // Indented lines with trimmed-space columns, as the callers pass
    // them: the scan must run on the trimmed slices (EPH-I0842).
    const indented_same = [_][]const u8{"    if (c1) { guard = 1; x = 2; }"};
    const is_t = mem.trim(u8, indented_same[0], " \t\r");
    const gpos4 = mem.indexOf(u8, is_t, "guard").?;
    const xpos4 = mem.indexOf(u8, is_t, "x = 2").?;
    try std.testing.expect(positionsInSameBlock(
        &indented_same,
        .{ .line = 0, .col = gpos4 },
        .{ .line = 0, .col = xpos4 },
        0,
    ));

    // The one-line else arm on an indented line: the else `{` sits in
    // the prefix slice a raw-line scan skips, so the guard depth reads
    // one too low and the block-closing dip is absorbed (EPH-I0842).
    const indented_else = [_][]const u8{
        "    if (c1) { guard = 1; } else { guard = 1; }",
        "    if (c2) { x = 2; }",
    };
    const g5_t = mem.trim(u8, indented_else[0], " \t\r");
    const x5_t = mem.trim(u8, indented_else[1], " \t\r");
    const gpos5 = mem.indexOf(u8, g5_t, "guard").?;
    const xpos5 = mem.indexOf(u8, x5_t, "x = 2").?;
    try std.testing.expect(!positionsInSameBlock(
        &indented_else,
        .{ .line = 0, .col = gpos5 },
        .{ .line = 1, .col = xpos5 },
        1,
    ));

    // Indented multi-line block: the pair stays in the same block.
    const indented_multi = [_][]const u8{
        "    if (c1) {",
        "        guard = 1;",
        "        x = 2;",
        "    }",
    };
    try std.testing.expect(positionsInSameBlock(
        &indented_multi,
        .{ .line = 1, .col = 0 },
        .{ .line = 2, .col = 0 },
        1,
    ));
}

test "correlationPair normalizes reversed same-line columns (EPH-I0850)" {
    // The reversed else-arm one-liner: the var occurrence leads the
    // guard on the line, and the closing brace between them splits the
    // blocks. The normalized pair scans the real region — the reversed
    // order scanned an empty region and read the pair as the same
    // block, silencing the uninitialized read (EPH-I0850).
    const rev_else = [_][]const u8{"if (c2) { x = 2; } else { guard = 1; }"};
    const e_t = mem.trim(u8, rev_else[0], " \t\r");
    const xpos = mem.indexOf(u8, e_t, "x = 2").?;
    const gpos = mem.indexOf(u8, e_t, "guard").?;
    const pair = correlationPair(.{ .line = 0, .col = gpos }, 0, xpos, 0);
    try std.testing.expectEqual(@as(usize, 0), pair.a.line);
    try std.testing.expectEqual(xpos, pair.a.col);
    try std.testing.expectEqual(gpos, pair.b.col);
    try std.testing.expect(!positionsInSameBlock(&rev_else, pair.a, pair.b, 0));

    // The genuinely same-block shape: the var occurrence leads the guard
    // inside one brace pair. The normalized pair keeps the correlation.
    const rev_same = [_][]const u8{"if (c1) { x = 2; guard = 1; }"};
    const s_t = mem.trim(u8, rev_same[0], " \t\r");
    const xs = mem.indexOf(u8, s_t, "x = 2").?;
    const gs = mem.indexOf(u8, s_t, "guard").?;
    const same_pair = correlationPair(.{ .line = 0, .col = gs }, 0, xs, 0);
    try std.testing.expectEqual(xs, same_pair.a.col);
    try std.testing.expectEqual(gs, same_pair.b.col);
    try std.testing.expect(positionsInSameBlock(&rev_same, same_pair.a, same_pair.b, 0));
}

test "guardNullAtOrIf tracks the null state across assignments (EPH-I0330)" {
    // Null declaration with no later assignment: null at the if.
    const clean = [_][]const u8{
        "var g: ?u32 = null;",
        "var x: u32 = undefined;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(guardNullAtOrIf(&clean, 2, "g"));

    // A non-null assignment before the if: non-null at the if.
    const assigned = [_][]const u8{
        "var g: ?u32 = null;",
        "g = 5;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&assigned, 2, "g"));

    // A non-null assignment balanced by a later null assignment: null at
    // the if again.
    const reset = [_][]const u8{
        "var g: ?u32 = null;",
        "g = 5;",
        "g = null;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(guardNullAtOrIf(&reset, 3, "g"));

    // A non-null assignment after a non-assignment occurrence on the same
    // line: every occurrence is scanned, so the first occurrence does not
    // hide the assignment that follows it (EPH-I0843).
    const late = [_][]const u8{
        "var g: ?u32 = null;",
        "use(&g); g = 5;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&late, 2, "g"));

    // A parameter guard never gets a null declaration.
    const param = [_][]const u8{
        "if (guard == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&param, 0, "guard"));

    // A same-line null-then-non-null pair ends non-null: the last
    // occurrence's own RHS decides (EPH-I0851).
    const reordered = [_][]const u8{
        "var g: ?u32 = null;",
        "g = null; g = 5;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&reordered, 2, "g"));

    // The reverse pair ends null: the last occurrence still decides.
    const ends_null = [_][]const u8{
        "var g: ?u32 = null;",
        "g = 5; g = null;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(guardNullAtOrIf(&ends_null, 2, "g"));

    // Another variable's null assignment on the guard's line never
    // counts: the guard's own assignment stays non-null (EPH-I0851).
    const other_null = [_][]const u8{
        "var g: ?u32 = null;",
        "g = 5; other = null;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&other_null, 2, "g"));

    // The guard's declaration line carrying another variable's null
    // initializer: the guard's own initializer decides, non-null
    // (EPH-I0852).
    const decl_other_null = [_][]const u8{
        "var g: ?u32 = 5; var o: ?u32 = null;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(!guardNullAtOrIf(&decl_other_null, 1, "g"));

    // The mirror: the guard's own initializer is null, the other
    // variable's is not (EPH-I0852).
    const decl_own_null = [_][]const u8{
        "var g: ?u32 = null; var o: ?u32 = 5;",
        "if (g == null or x == 1) {",
    };
    try std.testing.expect(guardNullAtOrIf(&decl_own_null, 1, "g"));
}

test "isNullGuardDecl classifies the guard's own initializer (EPH-I0852)" {
    // The guard's own initializer decides; another variable's null on
    // the line never counts.
    try std.testing.expect(!isNullGuardDecl("var g: ?u32 = 5; var o: ?u32 = null;", "g"));
    try std.testing.expect(isNullGuardDecl("var g: ?u32 = null; var o: ?u32 = 5;", "g"));
    try std.testing.expect(isNullGuardDecl("var g: ?u32 = null;", "g"));
    try std.testing.expect(!isNullGuardDecl("var g: ?u32 = 5;", "g"));
    // A later direct assignment on the same line overrides the
    // initializer: the last write decides (EPH-I0851 semantics).
    try std.testing.expect(isNullGuardDecl("var g: ?u32 = 5; g = null;", "g"));
    try std.testing.expect(!isNullGuardDecl("var g: ?u32 = null; g = 5;", "g"));
    // A non-declaration line is never a null-guard declaration.
    try std.testing.expect(!isNullGuardDecl("g = null;", "g"));
}

test "lastGuardWriteIsNull classifies the final occurrence (EPH-I0851)" {
    // A trailing non-null assignment overrides an earlier null one.
    try std.testing.expect(!lastGuardWriteIsNull("g = null; g = 5;", "g"));
    // A trailing null assignment ends null.
    try std.testing.expect(lastGuardWriteIsNull("g = 5; g = null;", "g"));
    // Another variable's null assignment never counts.
    try std.testing.expect(!lastGuardWriteIsNull("g = 5; other = null;", "g"));
    // A `== null` comparison is not an assignment at all.
    try std.testing.expect(!lastGuardWriteIsNull("if (g == null) {", "g"));
    // No assignment on the line: not a null write.
    try std.testing.expect(!lastGuardWriteIsNull("use(&g);", "g"));
}

test "allGuardAssignsCorrelate ignores other-var null writes (EPH-I0851)" {
    // The guard's own non-null assignment must correlate even when the
    // line also nulls another variable: the read must fire (probe
    // ng_other_null shape).
    const uncorrelated = [_][]const u8{
        "var guard: ?u32 = null;",
        "var x: u32 = undefined;",
        "var other: ?u32 = null;",
        "if (c) {",
        "    guard = 1; other = null;",
        "}",
        "if (guard) |_| {",
    };
    try std.testing.expect(!allGuardAssignsCorrelate(&uncorrelated, 7, "guard", "x"));

    // The same line with a genuine x assignment in the block correlates.
    const correlated = [_][]const u8{
        "var guard: ?u32 = null;",
        "var x: u32 = undefined;",
        "var other: ?u32 = null;",
        "if (c) {",
        "    guard = 1; other = null;",
        "    x = 2;",
        "}",
        "if (guard) |_| {",
    };
    try std.testing.expect(allGuardAssignsCorrelate(&correlated, 7, "guard", "x"));

    // A line whose final guard write is null needs no correlation.
    const null_line = [_][]const u8{
        "var guard: ?u32 = null;",
        "var x: u32 = undefined;",
        "guard = 5; guard = null;",
        "if (guard) |_| {",
    };
    try std.testing.expect(allGuardAssignsCorrelate(&null_line, 3, "guard", "x"));

    // A spaced-dot field write (`foo . x = 1`) is not a direct
    // assignment occurrence of x: the hasLeftDot correlation path must
    // reject it (EPH-I0854).
    const dot_field = "foo . x = 1;";
    const x_pos = mem.indexOf(u8, dot_field, "x").?;
    try std.testing.expect(!isDirectAssignOccurrence(dot_field, "x", x_pos));
}

test "orGuardVariable requires a trailing null equality (EPH-I0330)" {
    try std.testing.expectEqualStrings("g", orGuardVariable("if (g == null").?);
    try std.testing.expectEqualStrings("g", orGuardVariable("if (g  == null").?);
    try std.testing.expect(orGuardVariable("if (c") == null);
    try std.testing.expect(orGuardVariable("if (g != null") == null);
    try std.testing.expect(orGuardVariable("if (g == null and") == null);
}

test "guardDominatesRead requires shared enclosures (EPH-I0329)" {
    // Top-level guard and read: no enclosures, dominated.
    const top = [_][]const u8{
        "fn f(c: bool) u32 {",
        "    var x: u32 = undefined;",
        "    if (c) {",
        "        x = 1;",
        "    }",
        "    if (c) {",
        "        return x;",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(guardDominatesRead(&top, 2, 5));

    // Guard-if inside another if, read at top level: not dominated.
    const in_if = [_][]const u8{
        "fn f(a: bool, c: bool) u32 {",
        "    var x: u32 = undefined;",
        "    if (a) {",
        "        if (c) {",
        "            x = 1;",
        "        }",
        "    }",
        "    if (c) {",
        "        return x;",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(!guardDominatesRead(&in_if, 3, 7));

    // Guard-if inside a loop, read at top level: not dominated.
    const in_loop = [_][]const u8{
        "fn f(items: []const bool, c: bool) u32 {",
        "    var x: u32 = undefined;",
        "    for (items) |_| {",
        "        if (c) {",
        "            x = 1;",
        "        }",
        "    }",
        "    if (c) {",
        "        return x;",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(!guardDominatesRead(&in_loop, 3, 8));

    // Guard and read share the loop enclosure: dominated (the loop gates
    // both equally, so the read cannot run without the guard-if running).
    const shared = [_][]const u8{
        "fn f(items: []const bool, c: bool) u32 {",
        "    for (items) |_| {",
        "        if (c) {",
        "            x = 1;",
        "        }",
        "        if (c) {",
        "            return x;",
        "        }",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(guardDominatesRead(&shared, 2, 5));

    // Guard inside a bare block: the block runs unconditionally, so the
    // guard stays dominated.
    const in_bare = [_][]const u8{
        "fn f(c: bool) u32 {",
        "    var x: u32 = undefined;",
        "    {",
        "        if (c) {",
        "            x = 1;",
        "        }",
        "    }",
        "    if (c) {",
        "        return x;",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(guardDominatesRead(&in_bare, 3, 8));

    // Guard inside an else arm, read at top level: not dominated.
    const in_else = [_][]const u8{
        "fn f(a: bool, c: bool) u32 {",
        "    if (a) {",
        "    } else {",
        "        if (c) {",
        "            x = 1;",
        "        }",
        "    }",
        "    if (c) {",
        "        return x;",
        "    }",
        "    return 0;",
        "}",
    };
    try std.testing.expect(!guardDominatesRead(&in_else, 3, 8));
}

test "guardDominatesRead reaches a divergent opener beyond the window (EPH-I0847)" {
    // The guard-if sits 45 lines above the read, past the 40-line
    // lookback. The old walk saw no enclosures and presumed dominance
    // vacuously; the walk to the function top finds if (a), which the
    // read does not share — the guard-if does not dominate.
    var far: [57][]const u8 = undefined;
    far[0] = "fn f(a: bool, c: bool) u32 {";
    far[1] = "    var x: u32 = undefined;";
    far[2] = "    if (a) {";
    far[3] = "        if (c) {";
    far[4] = "            x = 1;";
    far[5] = "        }";
    far[6] = "    }";
    var fi: usize = 7;
    while (fi < 51) : (fi += 1) far[fi] = "    _ = 0;";
    far[51] = "    if (c) {";
    far[52] = "        return x;";
    far[53] = "    }";
    far[54] = "    return 0;";
    far[55] = "}";
    try std.testing.expect(!guardDominatesRead(&far, 3, 52));

    // The same distance with a top-level guard-if: no enclosures on
    // either side, so dominance holds and the read stays silent.
    var safe: [56][]const u8 = undefined;
    safe[0] = "fn g(c: bool) u32 {";
    safe[1] = "    var x: u32 = undefined;";
    safe[2] = "    if (c) {";
    safe[3] = "        x = 1;";
    safe[4] = "    }";
    var si: usize = 5;
    while (si < 50) : (si += 1) safe[si] = "    _ = 0;";
    safe[50] = "    if (c) {";
    safe[51] = "        return x;";
    safe[52] = "    }";
    safe[53] = "    return 0;";
    safe[54] = "}";
    try std.testing.expect(guardDominatesRead(&safe, 2, 51));

    // A shared far enclosure still dominates: both the guard-if and the
    // read sit inside if (a), so the read cannot run without the guard.
    var shared: [57][]const u8 = undefined;
    shared[0] = "fn h(a: bool, c: bool) u32 {";
    shared[1] = "    var x: u32 = undefined;";
    shared[2] = "    if (a) {";
    shared[3] = "        if (c) {";
    shared[4] = "            x = 1;";
    shared[5] = "        }";
    var hi: usize = 6;
    while (hi < 50) : (hi += 1) shared[hi] = "        _ = 0;";
    shared[50] = "        if (c) {";
    shared[51] = "            return x;";
    shared[52] = "        }";
    shared[53] = "    }";
    shared[54] = "    return 0;";
    shared[55] = "}";
    try std.testing.expect(guardDominatesRead(&shared, 3, 51));
}

test "ZA607: far divergent guard-if fires past the 40-line window (EPH-I0847)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The guard-if is nested in if (c), the read is not, and 42 padding
    // lines separate them. The vacuous dominance beyond the 40-line
    // lookback suppressed the read before the fix (EPH-I0847); the
    // c == false, cond == true path reads uninitialized x.
    var content = std.ArrayListUnmanaged(u8).empty;
    defer content.deinit(allocator);
    try content.appendSlice(allocator,
        \\fn farDivergent(c: bool, cond: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        if (cond) { x = 2; }
        \\    }
        \\
    );
    var pi: usize = 0;
    while (pi < 42) : (pi += 1) {
        const pad = try std.fmt.allocPrint(allocator, "    _ = {d};\n", .{pi});
        defer allocator.free(pad);
        try content.appendSlice(allocator, pad);
    }
    try content.appendSlice(allocator,
        \\    if (cond) {
        \\        return x;
        \\    }
        \\    return 0;
        \\}
        \\
    );
    var run = try runCFGMemoryTest(&diag, allocator, "da_i0847_far.zig", content.items);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_i0847_far.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "isMethodCallAt rejects a leading-dot receiver (EPH-I0332)" {
    const other = "other.x.init();";
    var cls = LineClassifier.init(other);
    const xpos = mem.indexOf(u8, other, "x").?;
    try std.testing.expect(!isMethodCallAt(other, xpos, "x", &cls));

    const spaced = "other . x.init();";
    var cls2 = LineClassifier.init(spaced);
    const xpos2 = mem.indexOf(u8, spaced, "x").?;
    try std.testing.expect(!isMethodCallAt(spaced, xpos2, "x", &cls2));

    const local = "x.init();";
    var cls3 = LineClassifier.init(local);
    try std.testing.expect(isMethodCallAt(local, 0, "x", &cls3));
}

test "hasInitCallOnVar requires the local as the receiver root (EPH-I0332)" {
    try std.testing.expect(hasInitCallOnVar("x.init();", "x"));
    try std.testing.expect(hasInitCallOnVar("env.pool.init(gpa, size);", "env"));
    try std.testing.expect(hasInitCallOnVar("x.foo.init();", "x"));
    try std.testing.expect(!hasInitCallOnVar("other.x.init();", "x"));
    try std.testing.expect(!hasInitCallOnVar("other . x.init();", "x"));
    try std.testing.expect(!hasInitCallOnVar("box.init();", "x"));
    // The &x call-argument form keeps the fill verdict via hasDirectFill.
    try std.testing.expect(isFillPattern("foo.init(&x);", "x"));
}

test "blockContainsAssignment counts only the guard block's top level (EPH-I0329)" {
    // Nested assignment inside the guard block: not top level.
    const nested = [_][]const u8{
        "if (c) {",
        "    if (d) {",
        "        x = 1;",
        "    }",
        "}",
    };
    try std.testing.expect(!blockContainsAssignment(&nested, 0, 5, "x"));

    // One-line nested form: the same verdict.
    const nested_oneline = [_][]const u8{"if (c) { if (d) { x = 1; } }"};
    try std.testing.expect(!blockContainsAssignment(&nested_oneline, 0, 1, "x"));

    // One-line top-level assignment: counts.
    const oneline = [_][]const u8{"if (c) { x = 1; }"};
    try std.testing.expect(blockContainsAssignment(&oneline, 0, 1, "x"));

    // Brace-on-next-line opener: the assignment is still top level.
    const brace_next = [_][]const u8{
        "if (c)",
        "{",
        "    x = 1;",
        "}",
    };
    try std.testing.expect(blockContainsAssignment(&brace_next, 0, 4, "x"));

    // Brace-less guard body: the first statement is the body.
    const braceless = [_][]const u8{
        "if (c)",
        "    x = 1;",
    };
    try std.testing.expect(blockContainsAssignment(&braceless, 0, 2, "x"));

    // An assignment after the guard block closes is not inside it.
    const after = [_][]const u8{
        "if (c) {",
        "}",
        "x = 1;",
    };
    try std.testing.expect(!blockContainsAssignment(&after, 0, 3, "x"));

    // Loop-carried assignment at the loop body's top level counts (the
    // documented exception — sig cmd.zig `for (0..3)` class).
    const loop_carried = [_][]const u8{
        "if (c) {",
        "    for (items) |_| {",
        "        x = 1;",
        "    }",
        "}",
    };
    try std.testing.expect(blockContainsAssignment(&loop_carried, 0, 5, "x"));

    // An assignment nested in a conditional inside the loop body never
    // counts: the loop may run while the conditional arm does not.
    const loop_nested_if = [_][]const u8{
        "if (c) {",
        "    for (items) |_| {",
        "        if (d) {",
        "            x = 1;",
        "        }",
        "    }",
        "}",
    };
    try std.testing.expect(!blockContainsAssignment(&loop_nested_if, 0, 7, "x"));
}

