        \\    const d = buf[0..n];
        \\    use(d);
        \\}
        \\fn useThenSliceRead(n: usize) void {
        \\    var buf: [8]u8 = undefined;
        \\    use(buf); const d = buf[0..n];
        \\    use(d);
        \\}
    ;
