test "findFillCallOccurrence matches call-arg dests only" {
    // The fill-call classes: `&x` passed to a call, and the bare
    // `@memset(x` / `@memcpy(x` dest. The match column is the call's open
    // paren. Slice-index forms (`&x[0]`, `@memset(x[0..], v)`) are
    // Pattern-2 territory and must NOT match — they keep whole-line
    // coverage (EPH-I0102). A non-call `&x` (`const p = &x;`) is
    // untrackable aliasing, not a fill.
    try std.testing.expectEqual(@as(?usize, 4), findFillCallOccurrence("fill(&x);", "x"));
    try std.testing.expectEqual(@as(?usize, 12), findFillCallOccurrence("use(x); fill(&x);", "x"));
    try std.testing.expectEqual(@as(?usize, 7), findFillCallOccurrence("@memset(x, 0);", "x"));
    try std.testing.expectEqual(@as(?usize, 7), findFillCallOccurrence("@memcpy(x, y);", "x"));
    try std.testing.expectEqual(@as(?usize, null), findFillCallOccurrence("const p = &x;", "x"));
    try std.testing.expectEqual(@as(?usize, null), findFillCallOccurrence("foo(&x[0]);", "x"));
    try std.testing.expectEqual(
        @as(?usize, null),
        findFillCallOccurrence("@memset(x[0..4], 0);", "x"),
    );
    try std.testing.expectEqual(
        @as(?usize, null),
        findFillCallOccurrence("const d = x[0..4];", "x"),
    );
    try std.testing.expectEqual(@as(?usize, null), findFillCallOccurrence("use(x);", "x"));
}

test "isVirtualElseLine rejects the switch-prong else arrow (EPH-I0096)" {
    // A switch prong `else => { ... }` is an arm, not a brace-less else
    // body: treating it as a virtual else would claim a deferred if entry
    // that the prong close already consumed. The `=>` rejection is cheap
    // latent hardening (EPH-I0096).
    try std.testing.expect(!isVirtualElseLine("else => {"));
    try std.testing.expect(!isVirtualElseLine("else =>"));
    try std.testing.expect(!isVirtualElseLine("else => x,"));
    // The non-prong virtual else shapes keep their verdict.
    try std.testing.expect(isVirtualElseLine("else x = 1;"));
    try std.testing.expect(isVirtualElseLine("else return;"));
}

test "hasInlineElseReturn anchors on the real else token (EPH-I0097)" {
    // Substring anchoring: an identifier containing `else` (elsewhere) or
    // a string literal carrying `else` before the real keyword mis-anchors
    // the inline-return check, so a genuine `else return;` is missed
    // (EPH-I0097).
    try std.testing.expect(hasInlineElseReturn("x = elsewhere(); } else return;"));
    try std.testing.expect(hasInlineElseReturn("const s = \"else\"; } else return;"));
    // No real else token: never an inline-else return.
    try std.testing.expect(!hasInlineElseReturn("const s = \"else return\";"));
    try std.testing.expect(!hasInlineElseReturn("x = elsewhere;"));
    // The plain shapes keep their verdicts.
    try std.testing.expect(hasInlineElseReturn("} else return;"));
    try std.testing.expect(hasInlineElseReturn("} else return x;"));
    try std.testing.expect(!hasInlineElseReturn("} else {"));
}

test "ZA607: multi-else line classifies by the chain link else (EPH-I1176, documented residual)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Documented residual (EPH-I1176, the EPH-I0826 pattern):
    // hasInlineElseReturn anchors on the FIRST else token of the line.
    // On `} else if (d) { x = 2; } else return;` the check classifies
    // against the chain link, so the final bare else's inline return is
    // not marked — the both-false path then looks like it falls through
    // to the post-chain read, which over-warns. The verdict is correct
    // (every path either fills x or returns), so the pin locks the
    // fail-safe over-warn: a change that silences it must carry the
    // position-aware else classification, and a change that keeps the
    // warning keeps the site honest.
    const content =
        \\fn multiElseLine(c: bool, d: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        return 0;
        \\    } else if (d) { x = 2; } else return;
        \\    use(x);
        \\    return 1;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_fc_multi_else.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_fc_multi_else.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "ZA607: return-terminal deferred close wires no merge edge (EPH-I1176/EPH-I1188)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // finishPendingElse now carries the is_return check its sibling
    // handleBlockEnd always had (fixed under the I1188 kick-back; the
    // I1176 record carried the gap as a documented residual): a
    // return-terminal deferred body wires no fall-through edge, so the
    // merge's only pred is the false branch and the read fires on the
    // path that reaches it unfilled. The pre-fix shape fired too (the
    // AND-meet kept the meet uncovered), so the verdict is the pin: a
    // change that silences it must prove the return path fills x.
    const content =
        \\fn spuriousEdgeShape(c: bool) u32 {
        \\    var x: u32 = undefined;
        \\    if (c) {
        \\        x = 1;
        \\        return 0;
        \\    }
        \\    use(x);
        \\    return 1;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_fc_ret_deferred.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        1,
        countRuleIssues(run.issues.items, "da_fc_ret_deferred.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

test "unmatchedOpenParenBefore masks parens inside strings (EPH-I0340)" {
    // `f("(", a)`: the string's unpaired `(` used to shift the backward
    // scan onto the string's paren — the call paren was missed. The
    // literal-masked scan finds f's `(`.
    try std.testing.expectEqual(@as(?usize, 1), unmatchedOpenParenBefore("f(\"(\", a)", 8));
    // Unmasked regions keep the call paren verdict.
    try std.testing.expectEqual(@as(?usize, 1), unmatchedOpenParenBefore("f(g(a), x)", 9));
    try std.testing.expectEqual(@as(?usize, 3), unmatchedOpenParenBefore("f(g(a))", 5));
}

test "isContainerParenHeader masks parens inside strings (EPH-I0340)" {
    // `switch ("(", y) {`: the string's unpaired `(` used to name the
    // header and the switch keyword was missed (depth drift, band-B01b
    // F-14). The literal-masked scan names `switch`.
    try std.testing.expect(isContainerParenHeader("switch (\"(\", y) {", 14));
    try std.testing.expect(!isContainerParenHeader("f(\"(\", y) {", 10));
    // The EPH-I0126 call-arg shape: the string inside the header call
    // carries the unpaired paren, and the scan still names `switch`.
    try std.testing.expect(isContainerParenHeader("switch (f(\"(\")) {", 14));
    try std.testing.expect(!isContainerParenHeader("f(g(\"(\")) {", 8));
}

test "findFillCallOccurrence grouping-paren non-call matches (EPH-I0123 doc)" {
    // The doc arm of EPH-I0123: unmatchedOpenParenBefore cannot tell a
    // grouping paren from a call paren, so a parenthesized `(&x)` outside
    // any call is matched as a call-fill (`const p = (&x);`). The behavior
    // is pinned as the documented approximation — a non-call address that
    // the fill analysis treats as a call-fill (FN direction). The
    // EPH-I0822 bridge form `&(x)` keeps the no-match verdict: its paren
    // sits at the name and the scan looks before the amp.
    try std.testing.expect(findFillCallOccurrence("const p = (&x);", "x") != null);
    try std.testing.expectEqual(@as(?usize, null), findFillCallOccurrence("const p = &(x);", "x"));
    try std.testing.expectEqual(@as(?usize, null), findFillCallOccurrence("const p = &x;", "x"));
}

test "ZA607: payload capture of a filled same-name var is silent" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Flow tui.zig shape (EPH-I0102 A/B): the loop-body `var arg` is
    // filled by the extract and guarded. The later `for (args[0..n])
    // |arg|` introduces a NEW payload binding whose uses are
    // indistinguishable from the tracked var's — the name-keyed analysis
    // drops payload-shadowed vars rather than guess (EPH-I0102).
    const content =
        \\fn extract(p: *[]const u8) bool {
        \\    p.* = "x";
        \\    return true;
        \\}
        \\fn payloadShadows(len: usize) !void {
        \\    var args: [4][]const u8 = undefined;
        \\    var n: usize = 0;
        \\    var i = len;
        \\    while (i > 0 and n < 4) : (i -= 1) {
        \\        var arg: []const u8 = undefined;
        \\        if (extract(&arg)) {
        \\            args[n] = arg;
        \\            n += 1;
        \\        } else return error.Invalid;
        \\    }
        \\    for (args[0..n]) |arg| {
        \\        consume(arg);
        \\    }
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "da_fc_payload.zig", content);
    defer run.deinit(allocator);

    try std.testing.expectEqual(
        0,
        countRuleIssues(run.issues.items, "da_fc_payload.zig", RULE_DEFINITE_ASSIGNMENT),
    );
}

