test "parseVersionFromZon rejects a dot-segment payload (EPH-I0668)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Regression: the value reached buildPackageUrl unchecked, so a
    // dot-segment version steered the fetch URL into another repo's
    // archive path. The strict gate must refuse it at the ingest point.
    const dot_segment =
        \\.{
        \\    .name = .ephor,
        \\    .version = "x/../../../../org/repo/archive/v9.9.9",
        \\}
    ;
    // The pre-fix parser dupes the payload; the free keeps the RED probe
    // (gate removed) a clean assertion failure, not a leak panic.
    const ver = parseVersionFromZon(allocator, dot_segment);
    if (ver) |v| allocator.free(v);
    try std.testing.expect(ver == null);
}

test "parseVersionFromZon rejects a newline payload (EPH-I0668)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Regression: a newline inside the value sailed into the URL splice,
    // the config splice, the cache write, and the render path. Strict
    // X.Y.Z only: the newline byte fails the digit grammar.
    const newline_payload = ".{ .version = \"0.15.0\nmore\" }";
    const ver = parseVersionFromZon(allocator, newline_payload);
    if (ver) |v| allocator.free(v);
    try std.testing.expect(ver == null);
}

test "parseVersionFromZon skips a non-strict occurrence and keeps the real key (EPH-I0668)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // A commented marker whose value is not strict must not shadow the
    // live key: the loop continues to the next .version occurrence.
    const content =
        \\.{
        \\    // .version = "9.9.9-beta.1"
        \\    .name = .ephor,
        \\    .version = "0.9.0",
        \\}
    ;
    const ver = parseVersionFromZon(allocator, content).?;
    defer allocator.free(ver);
    try std.testing.expectEqualStrings("0.9.0", ver);
}

// --- Update cache test seam ---
// resolveLatestVersion takes the fetcher as a function pointer so tests can
// count calls and control the result without touching the network.
// Reset-at-start, not save+restore (band-T04 F-4): sound under zig's
// sequential test runner because every test in this family calls
// resetFetchSeam before its first assert. A parallel runner would need
// save+restore (or per-test state) for these two globals.
var test_fetch_calls: usize = 0;
var test_fetch_result: ?[]const u8 = null;

fn testFetchFn(_: std.Io, allocator: Allocator) ?[]const u8 {
    test_fetch_calls += 1;
    const v = test_fetch_result orelse return null;
    return allocator.dupe(u8, v) catch null;
}

fn resetFetchSeam(result: ?[]const u8) void {
    test_fetch_calls = 0;
    test_fetch_result = result;
}

/// Absolute path of `name` inside the tmp dir (the cache fns are path-based).
fn tmpFilePath(allocator: Allocator, tmp: *std.testing.TmpDir, name: []const u8) ![]const u8 {
    const dir_path = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(dir_path);
    return std.fs.path.join(allocator, &.{ dir_path, name });
}

test "updateCheckDisabled is presence-only" {
    try std.testing.expect(!updateCheckDisabled(null));
    try std.testing.expect(updateCheckDisabled(""));
    try std.testing.expect(updateCheckDisabled("0"));
    try std.testing.expect(updateCheckDisabled("1"));
}

test "isCacheFresh boundary and fail-closed cases" {
    const now: i64 = 1_800_000_000;
    try std.testing.expect(isCacheFresh(now, now));
    try std.testing.expect(isCacheFresh(now - UPDATE_CACHE_MAX_AGE_S + 1, now));
    // Exactly 24h old is stale (pinned boundary).
    try std.testing.expect(!isCacheFresh(now - UPDATE_CACHE_MAX_AGE_S, now));
    try std.testing.expect(!isCacheFresh(-1, now));
    // Future epochs: tolerated inside the skew window, stale beyond it.
    try std.testing.expect(isCacheFresh(now + UPDATE_CACHE_FUTURE_SKEW_S, now));
    try std.testing.expect(!isCacheFresh(now + UPDATE_CACHE_FUTURE_SKEW_S + 1, now));
}

