test "readUpdateCache rejects a suffix-carrying version replay (EPH-I0203)" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // RED5-6: parseSemver's suffix stripping let `99.0.0-<ESC>` validate
    // and replay the FULL bytes into the render path. The strict tag
    // grammar rejects the whole entry instead.
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "cache",
        .data = "1800000000\n99.0.0-\x1b[2J\n",
    });
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    try std.testing.expect(readUpdateCache(std.testing.io, allocator, path) == null);
}

test "updateBannerText sanitizes hostile version bytes before the render (EPH-I0203)" {
    const allocator = std.testing.allocator;
    // A poisoned cache/API tag reaches the banner only through the
    // sanitizer: the ESC sequence becomes a visible '?' and no control
    // byte survives into the printed box.
    const banner = try updateBannerText(allocator, "99.0.0-\x1b[2J");
    defer allocator.free(banner);
    try std.testing.expect(mem.indexOf(u8, banner, "\x1b") == null);
    try std.testing.expect(mem.indexOf(u8, banner, "ephor v99.0.0-?") != null);
    // A clean strict version renders unchanged.
    const clean = try updateBannerText(allocator, "0.15.0");
    defer allocator.free(clean);
    try std.testing.expect(mem.indexOf(u8, clean, "ephor v0.15.0 available") != null);
}

test "readUpdateCache fails closed on an oversized cache file (band-T04 F-6)" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // A parseable header under filler sized one byte over the current
    // UPDATE_CACHE_MAX_BYTES (4096): the test pins rejection-over-parse.
    // Without the cap the entry would parse (valid epoch + semver), so
    // only the size limit can produce null. The fixture size is a literal
    // on purpose: derived from the constant, a cap raise would scale the
    // fixture in lockstep and the pin would stay green through the very
    // regression it exists to catch. A cap raise or a dropped limit makes
    // this expect flip (and the returned version would also trip the
    // leak-checking allocator); the round-trip test above pins sub-cap
    // acceptance.
    const header = "1800000000\n1.0.0\n";
    const big = try allocator.alloc(u8, 4097);
    defer allocator.free(big);
    @memcpy(big[0..header.len], header);
    @memset(big[header.len..], 'x');
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "cache", .data = big });
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    try std.testing.expect(readUpdateCache(std.testing.io, allocator, path) == null);
}

test "writeUpdateCache replaces a planted symlink and sets 0600 (EPH-I0167)" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // Victim the planted symlink points at.
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "victim", .data = "victim" });
    try tmp.dir.symLink(std.testing.io, "victim", "cache", .{});
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);

    const now: i64 = 1_800_000_000;
    writeUpdateCache(
        .{ .io = std.testing.io, .allocator = allocator, .now = now },
        path,
        "1.2.3",
    );

    // The victim keeps its bytes: the write must not have followed the link.
    const victim = try tmp.dir.readFileAlloc(std.testing.io, "victim", allocator, .limited(64));
    defer allocator.free(victim);
    try std.testing.expectEqualStrings("victim", victim);

    // The cache path is now a regular file holding the entry.
    const stat = try tmp.dir.statFile(std.testing.io, "cache", .{ .follow_symlinks = false });
    try std.testing.expect(stat.kind == .file);
    const cached = readUpdateCache(std.testing.io, allocator, path) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(cached.version);
    try std.testing.expectEqualStrings("1.2.3", cached.version);
    try std.testing.expectEqual(now, cached.epoch);

    // Owner-only mode on the published file (POSIX permissions only).
    // Windows exclusion mirrors writeUpdateCache: toMode exists only on
    // the POSIX File.Permissions enum (EPH-I1068).
    if (comptime @import("builtin").os.tag != .windows and std.posix.mode_t != u0) {
        try std.testing.expectEqual(
            @as(std.posix.mode_t, update_cache_file_mode),
            stat.permissions.toMode() & 0o777,
        );
    }
}

test "resolveLatestVersion returns fresh cache without fetching" {
