test "parseVersionFromTagsApi ignores a \"name\" mention inside a message field (EPH-I0281)" {
    const allocator = std.testing.allocator;
    // A release note that quotes "name": "v9.9.9" is message text, not a
    // tag key. The valid-JSON wire form escapes the embedded quotes
    // (\"name\"); the string-context gate rejects the raw match and the
    // semver-max comes from the real element keys only.
    const json =
        \\[{"name": "v0.14.2", "message": "see \"name\": \"v9.9.9\" for the pin"},
        \\ {"name": "v0.14.3"}]
    ;
    const ver = parseVersionFromTagsApi(allocator, json) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(ver);
    try std.testing.expectEqualStrings("0.14.3", ver);
}

test "parseVersionFromTagsApi rejects a name match inside a raw string value (EPH-I0281)" {
    const allocator = std.testing.allocator;
    // The discriminating shape: a malformed body whose message value
    // carries UNESCAPED quotes, so the raw "name": "v9.9.9" sequence
    // appears at a non-key position. This is the only shape the pre-fix
    // scan minted a message candidate from — on valid JSON the
    // serializer's escapes already failed extractTagName. The gate is the
    // explicit structure guarantee, so the spoofed 9.9.9 must not win.
    const json =
        \\[{"name": "v0.14.2", "message": "x "name": "v9.9.9" y"}]
    ;
    const ver = parseVersionFromTagsApi(allocator, json) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(ver);
    try std.testing.expectEqualStrings("0.14.2", ver);
}

test "parseVersionFromTagsApi returns null for garbage input" {
    const allocator = std.testing.allocator;
    try std.testing.expect(parseVersionFromTagsApi(allocator, "not json") == null);
    try std.testing.expect(parseVersionFromTagsApi(allocator, "{\"name\": 42}") == null);
    try std.testing.expect(parseVersionFromTagsApi(allocator, "") == null);
}

test "buildCurlFetchArgv pins the https clamp flags (EPH-I0156)" {
    // Pre-fix both spawns were inline argv literals that could drift apart.
    // The builder is the single source. The flags block non-https schemes
    // (redirects included), so a hostile network cannot turn the fetch into
    // a local file read.
    const argv = buildCurlFetchArgv("curl", "5", "https://example.invalid/tags");
    try std.testing.expectEqualStrings("curl", argv[0]);
    try std.testing.expectEqualStrings("-sL", argv[1]);
    try std.testing.expectEqualStrings("--max-time", argv[2]);
    try std.testing.expectEqualStrings("5", argv[3]);
    try std.testing.expectEqualStrings("--proto", argv[4]);
    try std.testing.expectEqualStrings("=https", argv[5]);
    try std.testing.expectEqualStrings("--proto-redir", argv[6]);
    try std.testing.expectEqualStrings("=https", argv[7]);
    try std.testing.expectEqualStrings("https://example.invalid/tags", argv[8]);
}

test "requireStrictExplicitVersion accepts null and strict X.Y.Z (EPH-I0155)" {
    var diag = testDiagCtx();
    const good = [_]?[]const u8{ null, "0.14.3", "10.20.30" };
    for (good) |value| {
        try requireStrictExplicitVersion(&diag, std.testing.allocator, value);
        // The gate's acceptance grammar is exactly the I0193 tag grammar.
        try std.testing.expect(value == null or isStrictSemverTag(value.?));
    }
}

test "requireStrictExplicitVersion rejects non-strict values (EPH-I0155)" {
    var diag = testDiagCtx();
    diag.cli_diagnostics_enabled = false;
    // "v1.2.3" fails: buildPackageUrl prepends the v itself. "1.2.3-beta.1"
    // fails: the I0193 tag grammar has no suffix. "" fails: no components.
    const bad = [_][]const u8{
        "garbage", "1.2", "1.2.3.4", "v1.2.3", "1.2.3-beta.1", "", "../1.2.3",
    };
    for (bad) |value| {
        try std.testing.expectError(
            error.InvalidVersion,
            requireStrictExplicitVersion(&diag, std.testing.allocator, value),
        );
    }
}

test "upgradeFloorAllows blocks downgrades without force (EPH-I0193)" {
    try std.testing.expect(!upgradeFloorAllows("0.14.3", "0.13.0", false));
    try std.testing.expect(upgradeFloorAllows("0.14.3", "0.13.0", true));
    try std.testing.expect(upgradeFloorAllows("0.14.3", "0.14.3", false));
    try std.testing.expect(upgradeFloorAllows("0.14.3", "0.15.0", false));
    // Unparseable targets pass the floor: EPH-I0166 owns flag validation.
    try std.testing.expect(upgradeFloorAllows("0.14.3", "garbage", false));
}

