test "writeFileAtomic replaces a planted symlink without following it (EPH-I0194)" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // Victim the planted symlink points at.
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "victim.txt",
        .data = "victim",
    });
    try tmp.dir.symLink(std.testing.io, "victim.txt", CONFIG_FILENAME, .{});

    const target_path = try tmpFilePath(allocator, &tmp, CONFIG_FILENAME);
    defer allocator.free(target_path);
    try writeFileAtomic(std.testing.io, std.Io.Dir.cwd(), target_path, "new-content");

    // The victim keeps its bytes: the write must not have followed the link.
    const victim = try tmp.dir.readFileAlloc(
        std.testing.io,
        "victim.txt",
        allocator,
        .limited(64),
    );
    defer allocator.free(victim);
    try std.testing.expectEqualStrings("victim", victim);

    // The link is replaced by a regular file holding the new content.
    const stat = try tmp.dir.statFile(std.testing.io, CONFIG_FILENAME, .{
        .follow_symlinks = false,
    });
    try std.testing.expect(stat.kind == .file);
    const written = try tmp.dir.readFileAlloc(
        std.testing.io,
        CONFIG_FILENAME,
        allocator,
        .limited(64),
    );
    defer allocator.free(written);
    try std.testing.expectEqualStrings("new-content", written);

    // Success leaves no temp files behind.
    var it = tmp.dir.iterate();
    var entries: usize = 0;
    while (try it.next(std.testing.io)) |entry| {
        entries += 1;
        const is_expected = mem.eql(u8, entry.name, "victim.txt") or
            mem.eql(u8, entry.name, CONFIG_FILENAME);
        try std.testing.expect(is_expected);
    }
    try std.testing.expectEqual(@as(usize, 2), entries);
}

test "buildIntegrationUpdate ignores forged markers in strings and comments (EPH-I0168)" {
    // The start marker sits inside a string, the end marker inside a
    // comment. Pre-fix the raw indexOf matched both and the splice cut at
    // the forged positions, corrupting the file.
    const allocator = std.testing.allocator;
    const content =
        \\const std = @import("std");
        \\const note = "    // Ephor static analysis";
        \\// ephor_upgrade_step.dependOn(&ephor_upgrade_cmd.step);
        \\pub fn build(b: *std.Build) void {
        \\    _ = b;
        \\}
        \\
    ;
    const update = try buildIntegrationUpdate(allocator, content);
    try std.testing.expect(update == .no_markers);
}

test "buildIntegrationUpdate rejects a forged end marker inside a string (EPH-I0168)" {
    // The start marker is real, but the only end marker sits in a string
    // after it. Pre-fix the splice cut through the string text.
    const allocator = std.testing.allocator;
    const content =
        \\pub fn build(b: *std.Build) void {
        \\    _ = b;
        \\    // Ephor static analysis
        \\    const ephor_dep = 1;
        \\    const help = "ephor_upgrade_step.dependOn(&ephor_upgrade_cmd.step);";
        \\}
        \\
    ;
    const update = try buildIntegrationUpdate(allocator, content);
    try std.testing.expect(update == .no_markers);
}

test "buildIntegrationUpdate rejects a marker that follows code on its line (EPH-I0168)" {
    // The start marker text follows real tokens. isCodeMatch passes it
    // (the match starts before the comment opener), so the line anchor is
    // the filter that rejects it.
    const allocator = std.testing.allocator;
    const content =
        \\pub fn build(b: *std.Build) void {
        \\    _ = b;
        \\    call(    // Ephor static analysis
        \\        1,
        \\    );
        \\    ephor_upgrade_step.dependOn(&ephor_upgrade_cmd.step);
        \\}
        \\
    ;
    const update = try buildIntegrationUpdate(allocator, content);
    try std.testing.expect(update == .no_markers);
}

test "buildIntegrationUpdate replaces an outdated block (EPH-I0168)" {
    const allocator = std.testing.allocator;
    const content =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = 1;
        \\    _ = exe;
        \\    _ = b;
        \\    // Ephor static analysis
        \\    const ephor_dep = b.dependency("ephor", .{});
        \\    _ = ephor_dep;
        \\    ephor_upgrade_step.dependOn(&ephor_upgrade_cmd.step);
        \\}
        \\
    ;
    const update = try buildIntegrationUpdate(allocator, content);
    const new_content = switch (update) {
        .replaced => |nc| nc,
        else => return error.TestUnexpectedResult,
    };
    defer allocator.free(new_content);

    // The canonical block landed between the preserved prefix and suffix.
    try std.testing.expect(mem.indexOf(u8, new_content, EPHOR_BUILD_BLOCK) != null);
    try std.testing.expect(mem.startsWith(u8, new_content, "pub fn build"));
    try std.testing.expect(mem.endsWith(u8, new_content, "}\n"));
    // The replaced text is gone.
    try std.testing.expect(mem.indexOf(u8, new_content, "const ephor_dep = 1") == null);
}

test "buildIntegrationUpdate reports an already-canonical block (EPH-I0168)" {
    const allocator = std.testing.allocator;
    const content = "pub fn build(b: *std.Build) void {\n    _ = b;\n" ++
        EPHOR_BUILD_BLOCK ++ "\n}\n";
    const update = try buildIntegrationUpdate(allocator, content);
    try std.testing.expect(update == .current);
}

test "buildIntegrationUpdate replaces the v0.11.x snippet block (EPH-I0055)" {
    // The marker-pair patching carries two pairs: the canonical block and
    // the old v0.11.x snippet. The old pair must splice to the canonical
    // block like the new one, and both old markers must be gone after.
    const allocator = std.testing.allocator;
    const content =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = 1;
        \\    _ = exe;
        \\    _ = b;
        \\    // === Ephor Static Analysis ===
        \\    const ephor_exe = b.addExecutable(.{ .name = "ephor" });
        \\    ephor_step.dependOn(&b.addRunArtifact(ephor_exe).step);
        \\}
        \\
    ;
    const update = try buildIntegrationUpdate(allocator, content);
    const new_content = switch (update) {
        .replaced => |nc| nc,
        else => return error.TestUnexpectedResult,
    };
    defer allocator.free(new_content);

    try std.testing.expect(mem.indexOf(u8, new_content, EPHOR_BUILD_BLOCK) != null);
    try std.testing.expect(mem.startsWith(u8, new_content, "pub fn build"));
    try std.testing.expect(mem.endsWith(u8, new_content, "}\n"));
    try std.testing.expect(mem.indexOf(u8, new_content, "=== Ephor Static Analysis ===") == null);
    try std.testing.expect(mem.indexOf(u8, new_content, "ephor_exe") == null);
}

test "updateBuildFnScanBraces: only code braces move the depth (EPH-I0055)" {
    var scan: BuildFnScan = .{ .in_build_fn = true, .brace_depth = 1 };
    // Braces inside a string, a char literal, and a comment are data.
    updateBuildFnScanBraces(&scan, "const s = \"{ }\";", 0);
    updateBuildFnScanBraces(&scan, "const c = '}';", 1);
    updateBuildFnScanBraces(&scan, "// { }", 2);
    try std.testing.expectEqual(@as(i32, 1), scan.brace_depth);
    try std.testing.expect(scan.build_fn_end == null);
    try std.testing.expect(scan.in_build_fn);
    // A real code brace opens; its matching close returns to depth 1.
    updateBuildFnScanBraces(&scan, "if (x) {", 3);
    try std.testing.expectEqual(@as(i32, 2), scan.brace_depth);
    updateBuildFnScanBraces(&scan, "}", 4);
    try std.testing.expectEqual(@as(i32, 1), scan.brace_depth);
    try std.testing.expect(scan.build_fn_end == null);
    // The close that reaches depth 0 ends the build fn at that line.
    updateBuildFnScanBraces(&scan, "}", 5);
    try std.testing.expectEqual(@as(i32, 0), scan.brace_depth);
    try std.testing.expectEqual(@as(?usize, 5), scan.build_fn_end);
    try std.testing.expect(!scan.in_build_fn);
}

test "updateBuildFnScanBraces: multiline string braces are data (EPH-I0055)" {
    var scan: BuildFnScan = .{ .in_build_fn = true, .brace_depth = 1 };
    // A `\\` opener makes the rest of the line string data, and a body
    // line (leading `\\`) returns early from LiteralState.forLine, so an
    // unbalanced brace inside the format string cannot close the build
    // fn early (EPH-I0512 doc).
    updateBuildFnScanBraces(&scan, "const s = \\\\", 0);
    try std.testing.expectEqual(@as(i32, 1), scan.brace_depth);
    updateBuildFnScanBraces(&scan, "\\\\ unbalanced { }", 1);
    try std.testing.expectEqual(@as(i32, 1), scan.brace_depth);
    try std.testing.expect(scan.build_fn_end == null);
    try std.testing.expect(scan.in_build_fn);
    // A real close after the multiline string still ends the fn.
    updateBuildFnScanBraces(&scan, "}", 2);
    try std.testing.expectEqual(@as(?usize, 2), scan.build_fn_end);
    try std.testing.expect(!scan.in_build_fn);
}

test "zigContentParses gates the replacement on a clean parse (EPH-I0168)" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // The spawn routes through tool_zig_path: a zig binary reachable via
    // PATH (or the EPHOR_ZIG_PATH override) is a test-host requirement
    // here, exactly as it is for runFmtCheck (band-T04 F-1). The bare
    // "zig" default resolves through PATH; an absolute-path toolchain
    // host sets EPHOR_ZIG_PATH for the test run.
    try std.testing.expect(
        zigContentParses(std.testing.io, allocator, tmp.dir, "pub fn build() void {}\n"),
    );
    try std.testing.expect(
        !zigContentParses(std.testing.io, allocator, tmp.dir, "pub fn build( void {\n"),
    );

    // Both runs cleaned their temp file: no litter in the project dir.
    var it = tmp.dir.iterate();
    try std.testing.expect((try it.next(std.testing.io)) == null);
}

test "resolveToolFromEnv falls back to the bare name when unset (EPH-I0154)" {
    var diag = testDiagCtx();
    // Null override and null PATH: nothing to resolve, the bare name
    // keeps the late-spawn failure behavior.
    try std.testing.expectEqualStrings("zig", resolveToolFromEnv(&diag, .zig, null, null));
    try std.testing.expectEqualStrings("curl", resolveToolFromEnv(&diag, .curl, null, null));
}

test "resolveToolFromEnv accepts an absolute override that resolves (EPH-I0154)" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    // A fixture inside tmpDir, not a host path: the test asserts the
    // resolution branch, not the host's /bin/sh (band-T04 F-2).
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "sh", .data = "" });
    const tool_path = try tmpFilePath(allocator, &tmp, "sh");
    defer allocator.free(tool_path);
    try std.testing.expectEqualStrings(
        tool_path,
        resolveToolFromEnv(&diag, .zig, tool_path, null),
    );
}

test "resolveToolFromEnv resolves the bare name through PATH absolutely (EPH-I0163)" {
    // RED5-9 arm: the spawn path resolves to an absolute path at
    // startup, so the executed binary is fixed before any scan input is
    // read. The first PATH entry naming an existing non-directory wins;
    // a PATH that names no tool falls back to the bare name.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "zig", .data = "" });
    const tool_path = try tmpFilePath(allocator, &tmp, "zig");
    defer allocator.free(tool_path);
    const path_dir = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(path_dir);
    try std.testing.expectEqualStrings(
        tool_path,
        resolveToolFromEnv(&diag, .zig, null, path_dir),
    );

    // A PATH that names no zig keeps the bare name.
    var tmp2 = std.testing.tmpDir(.{});
    defer tmp2.cleanup();
    const empty_dir = try tmp2.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(empty_dir);
    try std.testing.expectEqualStrings(
        "zig",
        resolveToolFromEnv(&diag, .zig, null, empty_dir),
    );
}

test "resolveToolFromEnv warns and falls back on a relative override (EPH-I0154)" {
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    try std.testing.expectEqualStrings(
        "zig",
        resolveToolFromEnv(&diag, .zig, "tools/zig", null),
    );
    // The warning reaches the capture in-process (EPH-I1051): the sink
    // replaced the mute-and-state-only assertion shape, and this positive
    // control proves the capture catches the diagnostic the I0314 test
    // asserts absent.
    try std.testing.expect(
        std.mem.indexOf(u8, capture.slice(), "not an absolute path") != null,
    );
}

test "resolveToolFromEnv empty override falls back to the bare name (EPH-I0314, value-level pin)" {
    // Value-level fallback-semantics pin: an empty override is not an
    // override, so it resolves to the bare name like an unset var. The
    // warning-absence half is asserted in-process via the capture sink
    // (EPH-I1051): pre-fix, the empty value tripped the "not an absolute
    // path" warning, which the gate-level full-suite stderr grep used to
    // enforce. The sink makes the absence assertable without the grep
    // (the relative-override test is the positive control proving the
    // capture catches that warning).
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    try std.testing.expectEqualStrings("zig", resolveToolFromEnv(&diag, .zig, "", null));
    try std.testing.expectEqualStrings("curl", resolveToolFromEnv(&diag, .curl, "", null));
    try std.testing.expectEqual(@as(usize, 0), capture.len);
}

test "resolveToolFromEnv warns and falls back on a directory override (EPH-I0312)" {
    var diag = testDiagCtx();
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    diag.cli_diagnostics_enabled = false;
    // A directory passes the pre-fix existence-only access() check and
    // fails confusingly at the late spawn; the not-dir gate catches it here.
    try std.testing.expectEqualStrings(
        "zig",
        resolveToolFromEnv(&diag, .zig, "/bin", null),
    );
}

test "resolveToolFromEnv warns and falls back on an unresolvable override (EPH-I0154)" {
    var diag = testDiagCtx();
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    diag.cli_diagnostics_enabled = false;
    try std.testing.expectEqualStrings(
        "zig",
        resolveToolFromEnv(&diag, .zig, "/nonexistent/ephor-i0154/zig", null),
    );
}

// Zon fixture for the EPH-I0271 write guard: a consumer project that
// depends on ephor. The hash is the real 0.13.5 value recorded in-tree.
const analysis_write_guard_zon =
    \\.{
    \\    .name = .fixture,
    \\    .version = "0.1.0",
    \\    .dependencies = .{
    \\        .ephor = .{
    \\            .url = "https://codeberg.org/RhyosLabs/ephor/archive/v0.13.5.tar.gz",
    \\            .hash = "ephor-0.13.5-p-Eoi8l4DwBnPTjUIikRbM-wANkuFfCs_4rXnR6ggX-M",
    \\        },
    \\    },
    \\    .paths = .{"src"},
    \\}
    \\
;

// Config fixture for the EPH-I0271 write guard.
const analysis_write_guard_config =
    \\{
    \\  "version": "0.13.5",
    \\  "path_dir": "src",
    \\  "entries": ["src/x.zig"]
    \\}
    \\
;

/// Drive the in-process analyzer battery of the .check command against
/// cfg.path (EPH-I0271). Mirrors the .check arm in main: the known-issues
/// probe, the scan, the orphan pass, then every file-touching analyzer.
/// Excludes runFmtCheck: it spawns `zig fmt --check`, a read-only
/// subprocess. The battery stays subprocess-free; the one spawn in this
/// family lives in the dedicated zigContentParses test, which needs
/// the same zig binary through tool_zig_path (PATH, or the
/// EPHOR_ZIG_PATH override) (band-T04 F-1).
fn runCheckAnalysisBattery(diag: *DiagCtx, allocator: Allocator, cfg: *Config) !void {
    try loadKnownIssues(diag, allocator, cfg);
    var g = ImportGraph.init(allocator, diag);
    defer g.deinit();
    g.scan_root = cfg.path;
    try scanPath(&g, cfg.path);
    // The fixture entry sits under the scan root, so .check's extra
    // single-file entry scan no-ops; markReachable still needs the entry.
    for (cfg.entries.items) |e| try g.markReachable(e);
    try g.markBuildPathReferences(cfg);

    var orphan_issues = try g.getOrphanIssues(allocator, cfg);
    defer deinitIssues(&orphan_issues, allocator);
    var cfg_mem_issues = try analyzeCFGMemory(allocator, &g);
    defer deinitIssues(&cfg_mem_issues, allocator);
    var cast_issues = try analyzeIntCastGuards(allocator, &g);
    defer deinitIssues(&cast_issues, allocator);
    var err_issues = try analyzeErrors(allocator, &g);
    defer deinitIssues(&err_issues, allocator);
    var ignored_issues = try analyzeIgnoredErrors(allocator, &g);
    defer deinitIssues(&ignored_issues, allocator);
    var unused_issues = try analyzeUnused(allocator, &g);
    defer deinitIssues(&unused_issues, allocator);
    var cx_issues = try analyzeComplexity(allocator, &g, cfg.thresholds);
    defer deinitIssues(&cx_issues, allocator);
    var style_issues = try analyzeStyle(allocator, &g, cfg.thresholds);
    defer deinitIssues(&style_issues, allocator);
    var naming_issues = try analyzeNaming(allocator, &g, cfg.error_naming);
    defer deinitIssues(&naming_issues, allocator);
    var test_issues = try analyzeTests(allocator, &g, null);
    defer deinitIssues(&test_issues, allocator);
    var conc_issues = try analyzeConcurrency(allocator, &g);
    defer deinitIssues(&conc_issues, allocator);
    var ast_stats = ast_tier.Stats{};
    var ast_issues = try analyzeAstTier(allocator, &g, &ast_stats, null);
    defer deinitIssues(&ast_issues, allocator);
}

/// Snapshot of the two manifest files the EPH-I0271 write guard watches.
const ManifestSnapshot = struct {
    zon: []u8,
    config: []u8,

    fn deinit(self: ManifestSnapshot, allocator: Allocator) void {
        allocator.free(self.zon);
        allocator.free(self.config);
    }
};

/// Read both manifest fixtures from dir. WHY: the write-guard test
/// snapshots the pair before and after the battery. One helper keeps the
/// test under the 50-line limit and keeps the 4096-byte bound in one
/// place.
fn readManifestSnapshot(allocator: Allocator, dir: std.Io.Dir) !ManifestSnapshot {
    const zon = try dir.readFileAlloc(
        std.testing.io,
        "build.zig.zon",
        allocator,
        .limited(4096),
    );
    errdefer allocator.free(zon);
    const config = try dir.readFileAlloc(
        std.testing.io,
        CONFIG_FILENAME,
        allocator,
        .limited(4096),
    );
    return .{ .zon = zon, .config = config };
}

/// Write the fixture manifests and one source file into tmp. WHY: the
/// EPH-I0271 write guard needs a consumer-project layout the analysis
/// battery can scan but must never write.
fn writeManifestFixture(tmp: *std.testing.TmpDir) !void {
    try tmp.dir.createDirPath(std.testing.io, "src");
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "build.zig.zon",
        .data = analysis_write_guard_zon,
    });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = CONFIG_FILENAME,
        .data = analysis_write_guard_config,
    });
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "src/x.zig",
        .data = "fn x() void {}\n",
    });
}

test "analysis path never writes project manifest files (EPH-I0271)" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // Fixture: the manifests install/upgrade own, plus one source file.
    try writeManifestFixture(&tmp);
    const dir_path = try tmpDirPath(allocator, &tmp);
    defer allocator.free(dir_path);

    const before = try readManifestSnapshot(allocator, tmp.dir);
    defer before.deinit(allocator);

    // A Config pointing at the fixture, as `ephor check <dir>` builds it.
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try setOwnedPath(allocator, &cfg, dir_path);
    // Ownership of the duped entry moves to cfg.entries on append (the
    // same single-expression transfer the CLI parsers use).
    try cfg.entries.append(
        allocator,
        try std.fmt.allocPrint(allocator, "{s}/src/x.zig", .{dir_path}),
    );

    try runCheckAnalysisBattery(&diag, allocator, &cfg);

    const after = try readManifestSnapshot(allocator, tmp.dir);
    defer after.deinit(allocator);

    // A future writer in the analysis path flips one of these red.
    try std.testing.expectEqualStrings(before.zon, after.zon);
    try std.testing.expectEqualStrings(before.config, after.config);

    // No new files in the fixture root: no ephor.json creation, no
    // .ephor-ignore, no zon backups.
    var it = tmp.dir.iterate();
    var root_entries: usize = 0;
    while (try it.next(std.testing.io)) |entry| {
        root_entries += 1;
        const expected = mem.eql(u8, entry.name, "build.zig.zon") or
            mem.eql(u8, entry.name, CONFIG_FILENAME) or
            mem.eql(u8, entry.name, "src");
        try std.testing.expect(expected);
    }
    try std.testing.expectEqual(@as(usize, 3), root_entries);

    // The guard also covers one directory deep (band-T04 F-5): a stray
    // write inside src/ (a log file, a backup) must flip this red too.
    var src_dir = try tmp.dir.openDir(std.testing.io, "src", .{ .iterate = true });
    defer src_dir.close(std.testing.io);
    var src_it = src_dir.iterate();
    var src_entries: usize = 0;
    while (try src_it.next(std.testing.io)) |entry| {
        src_entries += 1;
        try std.testing.expect(mem.eql(u8, entry.name, "x.zig"));
    }
    try std.testing.expectEqual(@as(usize, 1), src_entries);
}

// ============================================================================
// Config Migration Tests (migrateThresholds / buildMissingKeysJson)
// ============================================================================

const MigrateInsertCase = struct {
    name: []const u8,
    input: []const u8,
    expected: []const u8,
};

const MigrateNullCase = struct {
    name: []const u8,
    input: []const u8,
};

const MissingKeysCase = struct {
    name: []const u8,
    mig: MissingThresholdKeys,
    expected: []const u8,
};

/// Characterization pins: byte-exact migration output per case.
const migrate_insert_cases = [_]MigrateInsertCase{
    .{
        .name = "only max_cyclomatic missing inserts only cyclo",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cognitive": 12
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_cognitive": 12,
        \\    "max_cyclomatic": 10
        \\  }
        \\}
        ,
    },
    .{
        .name = "only max_cognitive missing inserts only cog, value 99 preserved",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 99
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 99,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "neither key present inserts both, cyclo then cog",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "trailing comma in body gets no leading comma on insert",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "empty thresholds object fills at derived indent",
        .input =
        \\{
        \\  "thresholds": {}
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\  "max_cyclomatic": 10,
        \\  "max_cognitive": 15
        \\}
        \\}
        ,
    },
    .{
        .name = "nested thresholds uses close_indent + 2 as entry indent",
        .input =
        \\{
        \\    "outer": {
        \\        "thresholds": {
        \\            "max_cyclomatic": 15
        \\        }
        \\    }
        \\}
        ,
        // Inserted entry lands at close_indent(8)+2=10 spaces, NOT aligned
        // with the sibling key at 12 — the algorithm derives indent from the
        // closing brace only. Valid JSON; cosmetic misalignment is the pin.
        .expected =
        \\{
        \\    "outer": {
        \\        "thresholds": {
        \\            "max_cyclomatic": 15,
        \\          "max_cognitive": 15
        \\        }
        \\    }
        \\}
        ,
    },
    .{
        .name = "disable array and content outside thresholds stay byte-identical",
        .input =
        \\{
        \\  "version": "0.13.0",
        \\  "disable": ["ZA305", "ZA306"],
        \\  "thresholds": {
        \\    "max_cyclomatic": 99
        \\  },
        \\  "strict": true
        \\}
        ,
        .expected =
        \\{
        \\  "version": "0.13.0",
        \\  "disable": ["ZA305", "ZA306"],
        \\  "thresholds": {
        \\    "max_cyclomatic": 99,
        \\    "max_cognitive": 15
        \\  },
        \\  "strict": true
        \\}
        ,
    },
    .{
        // EPH-I0511: a string VALUE mentioning "thresholds" must not
        // anchor the splice; the real key after it must. Pre-fix the
        // value's quote was the first raw match and the "x" object
        // received the migration (corruption).
        .name = "value mention before the real key does not retarget the splice",
        .input =
        \\{
        \\  "note": "thresholds",
        \\  "x": { },
        \\  "thresholds": {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "note": "thresholds",
        \\  "x": { },
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        // EPH-I0511: a COMMENT mentioning "thresholds" with braces must
        // not anchor the splice. Pre-fix the comment's quote was the
        // first raw match and the comment's `{`/`}` pair became the
        // "object": the migration inserted keys into comment text.
        .name = "comment mention does not anchor the splice",
        .input =
        \\{
        \\  // "thresholds" { } keys live here
        \\  "thresholds": {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  // "thresholds" { } keys live here
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        // EPH-I0065: the object-opener check skips whitespace and `//`
        // comments but still requires the first CODE char after the colon
        // to be `{`. A comment between the colon and the brace stays a
        // valid span, so the migration still runs.
        .name = "comment between the colon and the brace still migrates (EPH-I0065)",
        .input =
        \\{
        \\  "thresholds": // keys for the complexity gate
        \\  {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": // keys for the complexity gate
        \\  {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        // EPH-I1171: findConfigKey accepts whitespace between the key and
        // its colon (findKeySeparator walks past spaces), so the
        // migration must too. The F3 walk started at a fixed offset past
        // the key, landed on the colon, and silently skipped this valid
        // hand-edited shape.
        .name = "spaced colon between the key and its value still migrates (EPH-I1171)",
        .input =
        \\{
        \\  "thresholds" : {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds" : {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 10,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
};

const migrate_null_cases = [_]MigrateNullCase{
    .{
        .name = "both keys present is a no-op",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 15,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "no thresholds key at all",
        .input =
        \\{
        \\  "version": "0.14.0"
        \\}
        ,
    },
    .{
        .name = "thresholds is not an object",
        .input = "{\"thresholds\": 5}",
    },
    .{
        // EPH-I0065: a scalar thresholds key followed by ANOTHER object
        // must stay inert. Pre-fix the brace scan bound the next object's
        // brace, so the migration inserted threshold keys into "x".
        .name = "scalar thresholds before another object is not an anchor (EPH-I0065)",
        .input = "{\"thresholds\": 5, \"x\": {\"deep\": 1}}",
    },
    .{
        // EPH-I0065: the key must bind an object value, so a string value
        // before another object stays inert too (the pre-fix scan found
        // the next object's brace past the string).
        .name = "string thresholds value before another object is not an anchor (EPH-I0065)",
        .input = "{\"thresholds\": \"none\", \"x\": {\"deep\": 1}}",
    },
    .{
        // EPH-I0511: a string VALUE mentioning "thresholds" with no real
        // thresholds key must not anchor the splice into the next object.
        // Pre-fix the migration inserted threshold keys into the
        // "something" object (corruption); now it no-ops.
        .name = "value mention with no thresholds object is not an anchor",
        .input =
        \\{
        \\  "note": "thresholds",
        \\  "something": {
        \\    "deep": 1
        \\  }
        \\}
        ,
    },
    .{
        .name = "empty content",
        .input = "",
    },
};

