const VersionRewriteCase = struct {
    name: []const u8,
    input: []const u8,
    /// Expected rewrite output; null expects a no-op (null return).
    expected: ?[]const u8,
};

/// EPH-I0511 rewrite pins: the "version" anchor must sit in code in key
/// position, and the splice must fail closed on any other shape. Pre-fix
/// the raw substring matches hit comments, string values, and stray
/// braces, splicing the version into the user's config at arbitrary
/// quote pairs.
const version_rewrite_cases = [_]VersionRewriteCase{
    .{
        .name = "comment version anchor stays inert; field inserted",
        .input =
        \\// "version": "0.9.9" (schema note)
        \\{
        \\  "path_dir": "src"
        \\}
        ,
        .expected =
        \\// "version": "0.9.9" (schema note)
        \\{
        \\  "version": "0.14.3",
        \\  "path_dir": "src"
        \\}
        ,
    },
    .{
        .name = "real key replaced byte-exactly",
        .input = "{\"version\": \"0.9.9\", \"path_dir\": \"src\"}",
        .expected = "{\"version\": \"0.14.3\", \"path_dir\": \"src\"}",
    },
    .{
        .name = "leading comment brace does not receive the insertion",
        .input =
        \\// the { is a placeholder
        \\{
        \\  "path_dir": "src"
        \\}
        ,
        .expected =
        \\// the { is a placeholder
        \\{
        \\  "version": "0.14.3",
        \\  "path_dir": "src"
        \\}
        ,
    },
    .{
        .name = "version VALUE does not anchor the replace",
        .input = "{\"path_dir\": \"version\", \"disable\": [\"ZA305\"]}",
        .expected = "{\n  \"version\": \"0.14.3\",\"path_dir\": \"version\", \"disable\": [\"ZA305\"]}",
    },
    .{
        .name = "number value no-ops instead of splicing",
        .input = "{\"version\": 5, \"path_dir\": \"src\"}",
        .expected = null,
    },
    .{
        .name = "missing colon no-ops the replace and inserts a field",
        .input = "{\"version\" \"0.9.9\"}",
        .expected = "{\n  \"version\": \"0.14.3\",\"version\" \"0.9.9\"}",
    },
};

test "buildVersionUpdatedConfig ignores version anchors in comments and strings (EPH-I0511)" {
    for (&version_rewrite_cases) |*case| {
        const maybe_actual = buildVersionUpdatedConfig(
            std.testing.allocator,
            case.input,
            "0.14.3",
        );
        if (case.expected == null) {
            if (maybe_actual) |actual| {
                std.debug.print("case '{s}': expected null, got:\n{s}\n", .{ case.name, actual });
                std.testing.allocator.free(actual);
                try std.testing.expect(false);
            }
            continue;
        }
        if (maybe_actual == null) {
            std.debug.print("case '{s}': expected rewrite, got null\n", .{case.name});
            try std.testing.expect(false);
            continue;
        }
        defer std.testing.allocator.free(maybe_actual.?);
        std.testing.expectEqualStrings(case.expected.?, maybe_actual.?) catch {
            std.debug.print("case '{s}' failed\n", .{case.name});
            try std.testing.expect(false);
        };
    }
}

test "fnReturnsType detects literal type return" {
    // Returns type → TitleCase required
    try std.testing.expect(fnReturnsType("fn Point(T: type) type {", 8));
    try std.testing.expect(fnReturnsType("fn ShortList(comptime T: type, comptime n: usize) type {", 12));
    try std.testing.expect(fnReturnsType("pub fn MakeStruct(comptime T: type) type {", 12));
}

test "fnReturnsType detects error union type return" {
    // Returns !type → still TitleCase
    try std.testing.expect(fnReturnsType("fn MakeType(x: u32) !type {", 11));
}

test "fnReturnsType rejects non-type returns" {
    // Returns T, not type → camelCase
    try std.testing.expect(!fnReturnsType("fn foo(T: type) T {", 6));
    try std.testing.expect(!fnReturnsType("fn doubleIt(comptime T: type, value: T) T {", 11));
    try std.testing.expect(!fnReturnsType("fn init(allocator: std.mem.Allocator) !Self {", 7));
    try std.testing.expect(!fnReturnsType("fn parse() !void {", 8));
    try std.testing.expect(!fnReturnsType("fn getValue() u32 {", 11));
}

test "fnReturnsType handles nested fn type params" {
    // Inner fn returns type, but outer fn returns void → camelCase
    try std.testing.expect(!fnReturnsType("fn register(cb: fn(type) type, x: u32) void {", 11));
}

test "fnReturnsType rejects type-prefixed identifiers" {
    // "typedef" is not "type"
    try std.testing.expect(!fnReturnsType("fn foo() typedef {", 6));
}

test "fnReturnsType ignores parens inside string-literal defaults (EPH-I0465)" {
    // The `)` and `(` inside the default value are string data: the balance
    // must close on the real param-list `)`, so the `type` return is seen
    // and the factory is not misreported as a plain fn.
    try std.testing.expect(fnReturnsType("fn Make(a: []const u8 = \")\") type {", 7));
    try std.testing.expect(fnReturnsType("fn Make2(a: []const u8 = \"(\") type {", 8));
}

test "fnReturnsType ignores parens inside a comment (EPH-I0465)" {
    // The `)` and `type` in the comment are prose: without masking they
    // close the balance early and fake a `type` return.
    try std.testing.expect(!fnReturnsType("fn Make(a: u32, // ) type", 7));
}

