test "registerFnSignature guard masks fn ( in strings (EPH-I0975)" {
    var ctx = TypeContext.init();
    defer ctx.deinit(std.testing.allocator);
    const sctx = FnSigCtx{ .a = std.testing.allocator, .lines = &.{}, .idx = 0 };
    // A string carrying `fn (` is not a signature: the guard rejects it
    // before any registration.
    const pat_line = "const pat = \"fn (\";";
    try std.testing.expect(!try registerFnSignature(sctx, pat_line, null, &ctx));
    // The real signature still registers.
    try std.testing.expect(try registerFnSignature(sctx, "fn g() void {", null, &ctx));
}

test "registerFnSignature resolves zig-fmt-wrapped signatures (EPH-I0388)" {
    var ctx = TypeContext.init();
    defer ctx.deinit(std.testing.allocator);

    // band-B04 F2: the return type sat on a continuation line, so the
    // wrapped method registered nothing and its ReturnKind stayed
    // unknown. The continuation scan must register the method under the
    // enclosing type (self on line 2) with the closer's return kind.
    const lines = [_][]const u8{
        "pub fn processSomething(",
        "    self: *Foo,",
        "    allocator: std.mem.Allocator,",
        "    input: []const u8,",
        ") !void {",
        "    _ = input;",
    };
    const sctx = FnSigCtx{ .a = std.testing.allocator, .lines = &lines, .idx = 0 };
    try std.testing.expect(try registerFnSignature(sctx, lines[0], "Foo", &ctx));
    const methods = ctx.struct_methods.get("Foo");
    try std.testing.expect(methods != null);
    try std.testing.expectEqual(ReturnKind.error_union, methods.?.get("processSomething").?);

    // Wrapped top-level fn with a fn-pointer param: nested parens on a
    // continuation line must not close the scan early.
    const lines2 = [_][]const u8{
        "fn scan(",
        "    comptime T: type,",
        "    cb: fn(u8) void = null,",
        ") void {",
    };
    const sctx2 = FnSigCtx{ .a = std.testing.allocator, .lines = &lines2, .idx = 0 };
    try std.testing.expect(try registerFnSignature(sctx2, lines2[0], null, &ctx));
    try std.testing.expectEqual(ReturnKind.void_type, ctx.function_returns.get("scan").?);

    // Wrapped error-set return: `error{OutOfMemory}!T {` on the closer
    // line must resolve as an error union, not .value (the error-set
    // braces are balanced, never a body boundary).
    const lines3 = [_][]const u8{
        "fn edits(",
        "    allocator: std.mem.Allocator,",
        "    encoding: u32,",
        ") error{OutOfMemory}!std.ArrayList(u8) {",
        "    _ = encoding;",
    };
    const sctx3 = FnSigCtx{ .a = std.testing.allocator, .lines = &lines3, .idx = 0 };
    try std.testing.expect(try registerFnSignature(sctx3, lines3[0], null, &ctx));
    try std.testing.expectEqual(ReturnKind.error_union, ctx.function_returns.get("edits").?);
}

test "registerFnSignature falls through on fn-pointer-typed decls (EPH-I0395)" {
    var ctx = TypeContext.init();
    defer ctx.deinit(std.testing.allocator);
    const sctx = FnSigCtx{ .a = std.testing.allocator, .lines = &.{}, .idx = 0 };
    // band-B04 F10: the fn-paren guard matches a fn-pointer TYPE
    // annotation too; such lines are var declarations and must not be
    // consumed as signatures (registerVarDecl then registers the var).
    try std.testing.expect(!try registerFnSignature(
        sctx,
        "const f: fn (u8) void = g;",
        null,
        &ctx,
    ));
    try std.testing.expect(!try registerFnSignature(
        sctx,
        "var f: *const fn (u8) void = &g;",
        null,
        &ctx,
    ));
    try std.testing.expect(!try registerFnSignature(
        sctx,
        "const f: ?fn (u8) void = null;",
        null,
        &ctx,
    ));
    // A real signature still registers.
    try std.testing.expect(try registerFnSignature(sctx, "fn g() void {", null, &ctx));
    try std.testing.expect(ctx.function_returns.count() == 1);
}

test "parseFileTypeContext registers fn-pointer-typed vars (EPH-I0395)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    const content =
        \\const f: fn (u8) void = g;
        \\fn g(x: u8) void { _ = x; }
        \\
    ;
    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    // The fall-through observable: the fn-pointer var registers under
    // its declaration (extractVarTypeName yields "fn" for the
    // annotation), and the line never reaches the signature tables.
    try std.testing.expect(ctx.var_types.get("f") != null);
    try std.testing.expectEqual(ReturnKind.void_type, ctx.function_returns.get("g").?);
    try std.testing.expect(ctx.function_returns.get("f") == null);
}

test "parseFileTypeContext: fn-pointer shadow does not erase a real var type (EPH-I1043)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    // A later fn-pointer-typed shadow (`const w: fn (u8) void = ...`)
    // used to overwrite the earlier real type with the inert "fn": the
    // method-call resolution for the real type degraded to .unknown. The
    // shadow must not erase an existing var_types entry (EPH-I1043).
    const content =
        \\const W = struct {
        \\    fn call(self: *W) void {}
        \\};
        \\const w = W{};
        \\fn f() void {
        \\    const w: fn (u8) void = W.call;
        \\    _ = w.call();
        \\}
        \\
    ;
    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    try std.testing.expectEqualStrings("W", ctx.var_types.get("w").?);
    try std.testing.expectEqual(
        ReturnKind.void_type,
        resolveReturnKind(&ctx, "_ = w.call()"),
    );
}

test "parseFileTypeContext registers pub-prefixed fn-pointer vars (EPH-I1044)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    // `pub const f: fn (u8) void = g;` did not match the var/const-only
    // decl guards: the F10 gate never fired, the line was consumed as a
    // signature, and the var stayed absent from var_types. The
    // pub-prefixed form must fall through like the plain form (EPH-I1044).
    const content =
        \\pub const f: fn (u8) void = g;
        \\fn g(x: u8) void { _ = x; }
        \\
    ;
    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    try std.testing.expect(ctx.var_types.get("f") != null);
    try std.testing.expect(ctx.function_returns.get("f") == null);
}

test "parseFileTypeContext skips signatures embedded in string literals (EPH-I0396)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    // band-B04 F11: a string literal carrying a full `fn name(...) T`
    // signature on a CODE line must not register a bogus entry. The
    // EPH-I0975 code-position masking covers the fn-paren guard; this
    // pin locks the full-signature shape end-to-end through the context
    // builder (top-level and struct-field strings alike).
    const content =
        \\const pat = "fn foo() void";
        \\const Wrapper = struct {
        \\    const doc = "fn bar(x: u8) u32;";
        \\    fn real(self: *Wrapper) u32 { return 0; }
        \\};
        \\
    ;
    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    try std.testing.expect(ctx.function_returns.get("foo") == null);
    try std.testing.expect(ctx.function_returns.get("bar") == null);
    const methods = ctx.struct_methods.get("Wrapper");
    try std.testing.expect(methods != null);
    try std.testing.expect(methods.?.get("bar") == null);
    try std.testing.expectEqual(ReturnKind.value, methods.?.get("real").?);
}

test "parseFileTypeContext registers wrapped method signatures (EPH-I0388)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    const content =
        \\const Wrapped = struct {
        \\    pub fn format(
        \\        self: *Wrapped,
        \\        buf: []u8,
        \\    ) !void {
        \\        _ = buf;
        \\    }
        \\};
        \\fn helper(
        \\    n: usize,
        \\    s: []const u8,
        \\    a: std.mem.Allocator,
        \\    b: std.mem.Allocator,
        \\    c: std.mem.Allocator,
        \\    d: std.mem.Allocator,
        \\    e: std.mem.Allocator,
        \\    f: std.mem.Allocator,
        \\    g: std.mem.Allocator,
        \\    h: std.mem.Allocator,
        \\) bool {
        \\    _ = n;
        \\    _ = s;
        \\    _ = a;
        \\    _ = b;
        \\    _ = c;
        \\    _ = d;
        \\    _ = e;
        \\    _ = f;
        \\    _ = g;
        \\    _ = h;
        \\}
    ;

    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

    const methods = ctx.struct_methods.get("Wrapped");
    try std.testing.expect(methods != null);
    try std.testing.expectEqual(ReturnKind.error_union, methods.?.get("format").?);
    try std.testing.expectEqual(ReturnKind.value, ctx.function_returns.get("helper").?);
}

test "extractMethodTarget stops at the previous dot (EPH-I0394 pin)" {
    // band-B04 F8: `self.list.clear(` resolves the receiver `list` —
    // name-identity, not object-identity (disclosed residual). The pin
    // locks the documented behavior so a field-aware change is deliberate.
    const line = "self.list.clear(x);";
    const dot = mem.indexOf(u8, line, ".clear(").?;
    try std.testing.expectEqualStrings("list", extractMethodTarget(line, dot).?);
    // A plain receiver resolves the same way.
    const line2 = "list.clear(x);";
    const dot2 = mem.indexOf(u8, line2, ".clear(").?;
    try std.testing.expectEqualStrings("list", extractMethodTarget(line2, dot2).?);
}

test "isMethodOnStdlibVar matches receivers by name identity (EPH-I0394 pin)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const a = gpa.allocator();

    var vars = std.StringHashMapUnmanaged(void){};
    defer vars.deinit(a);
    try vars.put(a, "list", {});

    // A field receiver borrows the local's tracking: `list` in
    // stdlib_vars covers `self.list.clear(` and `list.clear(` alike
    // (name-identity, the disclosed F8 behavior).
    const patterns = [_][]const u8{".clear("};
    try std.testing.expect(isMethodOnStdlibVar("self.list.clear();", &vars, &patterns));
    try std.testing.expect(isMethodOnStdlibVar("list.clear();", &vars, &patterns));
    // No tracked receiver: the dot-pattern must not match.
    try std.testing.expect(!isMethodOnStdlibVar("other.clear();", &vars, &patterns));
    // Universal patterns (no leading dot) always apply.
    const universal = [_][]const u8{"debug.print"};
    try std.testing.expect(isMethodOnStdlibVar("debug.print(\"x\");", &vars, &universal));
}

test "extractFnName accepts quoted names (EPH-I0922)" {
    // The quoted-name arm findRealFnDef uses (EPH-I0442, pubFnNameAt):
    // `fn @"quoted"()` yields the inner content, the spelling a call
    // site shares. Malformed quotes and fn-pointer shapes stay null.
    try std.testing.expectEqualStrings(
        "weird-name",
        extractFnName("fn @\"weird-name\"() void {").?,
    );
    try std.testing.expectEqualStrings("a-b", extractFnName("pub fn @\"a-b\"(x: u32) !void {").?);
    try std.testing.expect(extractFnName("fn @\"unterminated() void {}") == null);
    try std.testing.expect(extractFnName("cb: *const fn () void,") == null);
}

