}

test "extractVarTypeName skips pointer qualifiers in annotations" {
    try std.testing.expectEqualStrings("Q", extractVarTypeName("var z: *const Q = undefined;").?);
    try std.testing.expectEqualStrings(
        "T",
        extractVarTypeName("var t: *volatile T = undefined;").?,
    );
    try std.testing.expectEqualStrings("Q", extractVarTypeName("var q: ?*const Q = undefined;").?);
}

test "extractVarTypeName skips allowzero qualifier (EPH-I0071)" {
    // `*allowzero u8` used to yield the garbage key "allowzero"; the
    // qualifier must be skipped like `volatile ` (I0057 precedent).
    try std.testing.expectEqualStrings(
        "u8",
        extractVarTypeName("var z: *allowzero u8 = undefined;").?,
    );
    try std.testing.expectEqualStrings(
        "u8",
        extractVarTypeName("var z: *allowzero const u8 = undefined;").?,
    );
}

test "extractVarTypeName skips slice and array prefixes" {
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var s: []u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var a: [4]u8 = undefined;").?);
    try std.testing.expectEqualStrings("u8", extractVarTypeName("var m: [*c]u8 = undefined;").?);
}

test "extractVarTypeName skips align specs and compound qualifier chains" {
    try std.testing.expectEqualStrings(
        "u8",
        extractVarTypeName("var p: *align(4) u8 = undefined;").?,
    );
    try std.testing.expectEqualStrings(
        "u8",
        extractVarTypeName("var p: *align(4) const u8 = undefined;").?,
    );
    try std.testing.expectEqualStrings(
        "u8",
        extractVarTypeName("var p: [*c]const u8 = undefined;").?,
    );
    // Pathological nested parens: simple )-scan must fall to A-null, not mis-skip
    try std.testing.expect(
        extractVarTypeName("var p: *align(@alignOf(u8)) u8 = undefined;") == null,
    );
}

test "extractVarTypeName skips error-union prefixes" {
    try std.testing.expectEqualStrings(
        "Foo",
        extractVarTypeName("var e: error{X}!Foo = undefined;").?,
    );
    try std.testing.expectEqualStrings(
        "Foo",
        extractVarTypeName("var e: anyerror!Foo = undefined;").?,
    );
    try std.testing.expectEqualStrings("Foo", extractVarTypeName("var e: !Foo = undefined;").?);
}

test "extractVarTypeName qualified annotation does not block RHS inference" {
    const t1 = extractVarTypeName("var z: *const Q = Q.init();");
    try std.testing.expect(t1 != null);
    try std.testing.expectEqualStrings("Q", t1.?);
}

test "extractVarTypeName returns null for qualifier-only annotation" {
    try std.testing.expect(extractVarTypeName("var q: *const = undefined;") == null);
}

test "extractMethodCall extracts receiver and method" {
    const r1 = extractMethodCall("_ = list.clear()");
    try std.testing.expect(r1 != null);
    try std.testing.expectEqualStrings("list", r1.?.receiver);
    try std.testing.expectEqualStrings("clear", r1.?.method);

    const r2 = extractMethodCall("_ = logger.reset()");
    try std.testing.expect(r2 != null);
    try std.testing.expectEqualStrings("logger", r2.?.receiver);
    try std.testing.expectEqualStrings("reset", r2.?.method);
}

test "extractMethodCall returns null for non-method calls" {
    try std.testing.expect(extractMethodCall("_ = someFunction()") == null);
    try std.testing.expect(extractMethodCall("const x = 42;") == null);
}

test "extractMethodCall returns the last call on a multi-call line (EPH-I0398)" {
    // band-B04 F12: the scan resolves the LAST receiver.method( match.
    // The pin locks the disclosed last-match behavior so a
    // position-resolved rewrite must update the test and the doc.
    const r = extractMethodCall("_ = a.reset(); _ = b.clear()");
    try std.testing.expect(r != null);
    try std.testing.expectEqualStrings("b", r.?.receiver);
    try std.testing.expectEqualStrings("clear", r.?.method);
}

