        \\    }
        \\    pub fn process(self: *MyStruct) !void {
        \\    }
        \\    pub fn count(self: *const MyStruct) u32 {
        \\    }
        \\};
    ;

    var ctx = try parseFileTypeContext(a, content);
    defer ctx.deinit(a);

