test "extractMultilineFirstArg skips type param for type-first patterns" {
    // Direct unit lock for the type-first multiline branch. End-to-end flows
    // join continuation lines first (joinParenContinuation), so this branch is
    // only reachable when extraction on the joined line yields nothing.
    const type_first_lines = [_][]const u8{
        "    const out = try std.mem.replaceOwned(",
        "        u8, arena, input, \"a\", \"b\");",
    };
    const type_first_arg = extractMultilineFirstArg(type_first_lines[0], &type_first_lines, 0);
    try std.testing.expectEqualStrings("arena", type_first_arg.?);

    const first_arg_lines = [_][]const u8{
        "    const dst = try tuple_info.types.dupe(",
        "        arena,",
        "        ip,",
        "    );",
    };
    const first_arg = extractMultilineFirstArg(first_arg_lines[0], &first_arg_lines, 0);
    try std.testing.expectEqualStrings("arena", first_arg.?);
}

test "no FP for non-memory alloc method (ZA103)" {
    var diag = testDiagCtx();
    // Non-allocator structs can have .alloc() methods (e.g. SPIR-V register allocation).
    // These should NOT trigger ZA101/ZA103 since they do not allocate heap memory.
    // std.mem.Allocator.alloc() always takes a type as first arg (u8, MyStruct, etc.).
    // Non-memory .alloc() takes runtime values (ids, counts, etc.).
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    const test_content =
        \\const std = @import("std");
        \\const CodeGen = struct {
        \\    data: []u8,
        \\    pub fn alloc(self: *CodeGen, ty_id: u32, init: ?u32) !u32 {
        \\        _ = self; _ = ty_id; _ = init;
        \\        return 42;
        \\    }
        \\};
        \\fn emitCode(cg: *CodeGen) !void {
        \\    const tmp_id = try cg.alloc(object_ty_id, null);
        \\    const result_id = try cg.alloc(child_ty_id, null);
        \\    process(tmp_id, result_id);
        \\}
    ;

    const analysis = try createTestFileAnalysis(allocator, "test_nonmem_alloc.zig", test_content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_nonmem_alloc.zig"), {});

    var issues = try analyzeCFGMemory(allocator, &graph);
    defer deinitIssues(&issues, allocator);

    for (issues.items) |issue| {
        // Single-file fixture: the file filter is a no-op —
        // assert rule-absence across all issues (EPH-I1147).
        // Non-memory .alloc() should NOT trigger memory warnings
        try std.testing.expect(!mem.eql(u8, issue.rule, RULE_ALLOC_NO_DEFER));
        try std.testing.expect(!mem.eql(u8, issue.rule, RULE_ALLOC_NO_ERRDEFER));
    }
}

