    // only a bool: neither carries undefined buffer bytes, so the
    // pre-I1170 classifier fired ZA204 on both (verified live).
    const test_content =
        \\const std = @import("std");
        \\fn sliceLen() usize {
        \\    var buf: [32]u8 = undefined;
        \\    buf[0] = 1;
        \\    return buf[0..4].len;
        \\}
        \\fn compare(other: [32]u8) bool {
        \\    var buf: [32]u8 = undefined;
        \\    buf[0] = 1;
        \\    return buf == other;
        \\}
    ;

