test "ZA201 silent on split catch verdict line (EPH-I0424 pin)" {
    // `catch\nunreachable;` is ZA202's split-verdict form, never ZA201.
    const next = [_][]const u8{"    unreachable;"};
    const issue = checkSilentCatch(.{
        .t = "    foo() catch",
        .path = "test.zig",
        .line = 1,
