// ============================================================================
// ZA304 Suppression Tests — data dispatch functions
// ============================================================================

test "isDataDispatchFunction recognizes fromJson" {
    try std.testing.expect(isDataDispatchFunction("fromJson"));
    try std.testing.expect(isDataDispatchFunction("fromJsonObject"));
    try std.testing.expect(isDataDispatchFunction("parseJson"));
    try std.testing.expect(isDataDispatchFunction("deserialize"));
    try std.testing.expect(isDataDispatchFunction("loadConfig"));
    try std.testing.expect(isDataDispatchFunction("applyEnvVar"));
    // Prefix matches
    try std.testing.expect(isDataDispatchFunction("parseBlock"));
    try std.testing.expect(isDataDispatchFunction("parseTransaction"));
    try std.testing.expect(isDataDispatchFunction("parseReceipt"));
    try std.testing.expect(isDataDispatchFunction("parseLog"));
    try std.testing.expect(isDataDispatchFunction("decodeHeader"));
    try std.testing.expect(isDataDispatchFunction("encodeResponse"));
    try std.testing.expect(isDataDispatchFunction("applyConfig"));
}

test "isDataDispatchFunction rejects regular names" {
    try std.testing.expect(!isDataDispatchFunction("processBlock"));
    try std.testing.expect(!isDataDispatchFunction("handleRequest"));
    try std.testing.expect(!isDataDispatchFunction("init"));
    try std.testing.expect(!isDataDispatchFunction(""));
}

test "branchLimit applies the pattern multipliers" {
    // EPH-I0276: the flat arm covers flat SWITCH dispatchers only — a
    // flat if-chain keeps the base limit (the local-struct ZA304 pin).
    const flat_switch = ComplexityState{
        .cognitive = 10,
        .cyclomatic = 10,
        .switch_arms = 8,
        .max_nest = 2,
    };
    try std.testing.expectEqual(@as(usize, 24), branchLimit(12, &flat_switch));
    const flat_chain = ComplexityState{ .cognitive = 10, .cyclomatic = 10, .max_nest = 2 };
    try std.testing.expectEqual(@as(usize, 12), branchLimit(12, &flat_chain));
    const dd = ComplexityState{ .is_data_dispatch = true };
    try std.testing.expectEqual(@as(usize, 96), branchLimit(12, &dd));
    const tf = ComplexityState{ .is_type_factory = true };
    try std.testing.expectEqual(@as(usize, 36), branchLimit(12, &tf));
    const plain = ComplexityState{};
    try std.testing.expectEqual(@as(usize, 12), branchLimit(12, &plain));
    // EPH-I0277: a data table outranks every other pattern (20x).
    const dt = ComplexityState{ .is_data_table = true, .is_data_dispatch = true };
    try std.testing.expectEqual(@as(usize, 240), branchLimit(12, &dt));
}

test "dt and flat tags are rule-gated (EPH-I0276, EPH-I0277)" {
    // The tags name the multiplier that governed the finding. A rule the
    // pattern does not govern (ZA302 nesting, ZA303 params) carries no
    // tag — a wrong-cause claim in the product output (review F1).
    try std.testing.expect(dtTagApplies(RULE_FUNC_TOO_LONG));
    try std.testing.expect(dtTagApplies(RULE_TOO_MANY_BRANCHES));
    try std.testing.expect(dtTagApplies(RULE_CYCLOMATIC));
    try std.testing.expect(dtTagApplies(RULE_COGNITIVE));
    try std.testing.expect(!dtTagApplies(RULE_TOO_MANY_PARAMS));
    try std.testing.expect(!dtTagApplies(RULE_NESTING_TOO_DEEP));

    const flat_switch = ComplexityState{
        .cognitive = 10,
        .cyclomatic = 10,
        .switch_arms = 8,
        .max_nest = 2,
    };
    try std.testing.expect(flatTagApplies(RULE_CYCLOMATIC, &flat_switch));
    try std.testing.expect(flatTagApplies(RULE_COGNITIVE, &flat_switch));
    try std.testing.expect(flatTagApplies(RULE_TOO_MANY_BRANCHES, &flat_switch));
    try std.testing.expect(!flatTagApplies(RULE_TOO_MANY_PARAMS, &flat_switch));
    try std.testing.expect(!flatTagApplies(RULE_NESTING_TOO_DEEP, &flat_switch));
    try std.testing.expect(!flatTagApplies(RULE_FUNC_TOO_LONG, &flat_switch));

    // branchLimit grants no flat-chain allowance: a flat if-chain tags
    // ZA305/306 but never ZA304.
    const flat_chain = ComplexityState{ .cognitive = 10, .cyclomatic = 10, .max_nest = 2 };
    try std.testing.expect(flatTagApplies(RULE_CYCLOMATIC, &flat_chain));
    try std.testing.expect(!flatTagApplies(RULE_TOO_MANY_BRANCHES, &flat_chain));
}

test "pattern tags stay off param findings (EPH-I0276, EPH-I0277)" {
