    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_TOO_MANY_PARAMS)) za303_count += 1;
    }
    // The three C-ABI shapes are exempt; plainFive and decoy still fire
    // (the EntryPoint callconv on a later declaration exempts neither).
    try std.testing.expectEqual(@as(usize, 2), za303_count);
}

test "ZA303 exempts callconv(.Stdcall) and export declarations (EPH-I1093, EPH-I1096)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    // The ABI-pinned shapes carry 5 params the ABI fixes: a suffix and a
    // prefix callconv(.Stdcall) (the WinAPI class), a bodied export fn,
    // and a pub export fn. The sysv fn is the discriminating neighbor —
    // callconv(.x86_64_sysv) is NOT a pinned ABI, so it still fires like
    // the plain control.
    const code =
        \\fn winapiSuffix(a: u8, b: u8, c: u8, d: u8, e: u8) callconv(.Stdcall) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
        \\callconv(.Stdcall) fn winapiPrefix(a: u8, b: u8, c: u8, d: u8, e: u8) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
        \\export fn exportedFive(a: u8, b: u8, c: u8, d: u8, e: u8) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
        \\pub export fn pubExportedFive(a: u8, b: u8, c: u8, d: u8, e: u8) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
        \\fn sysvFive(a: u8, b: u8, c: u8, d: u8, e: u8) callconv(.x86_64_sysv) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
        \\fn plainFive(a: u8, b: u8, c: u8, d: u8, e: u8) void {
        \\    _ = .{ a, b, c, d, e };
        \\}
    ;

    const analysis = try createTestFileAnalysis(allocator, "test_abi_pinned.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_abi_pinned.zig"), {});

    var issues = try analyzeComplexity(allocator, &graph, .{});
    defer deinitIssues(&issues, allocator);

    var za303_count: usize = 0;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_TOO_MANY_PARAMS)) za303_count += 1;
    }
    // The four pinned shapes are exempt; sysvFive and plainFive still fire.
    try std.testing.expectEqual(@as(usize, 2), za303_count);
}

// ============================================================================
// ZA701 Tests — unbreakable string-literal exemption
// ============================================================================

test "stringContentStats splits code from string content (EPH-I0272)" {
    // 4 spaces + quote + 113 x's + quote + comma = 120 visible; code 5,
    // content 113.
    const long_literal = "    \"" ++ "x" ** 113 ++ "\",";
    try std.testing.expectEqual(@as(usize, 120), calculateVisibleLength(long_literal));
    try std.testing.expectEqual(@as(usize, 5), stringContentStats(long_literal).code);
    try std.testing.expectEqual(@as(usize, 113), stringContentStats(long_literal).content);
    // Pure code line — no content excluded
    const pure_code = "x" ** 120;
    try std.testing.expectEqual(@as(usize, 120), stringContentStats(pure_code).code);
    try std.testing.expectEqual(@as(usize, 0), stringContentStats(pure_code).content);
    // Escaped quote inside a literal must not terminate it
    const escaped = stringContentStats("const s = \"a\\\"b\";");
    try std.testing.expectEqual(@as(usize, 11), escaped.code);
    try std.testing.expectEqual(@as(usize, 4), escaped.content);
}

test "stringContentStats does not treat '\"' char literal as a string" {
    // The '"' char literal must not mask the rest of the line as string content
    const char_line =
        "if (c == '\"') return self.handleTheStringLiteral" ++
        "WithAnExcessivelyLongFunctionName(alpha, beta, gamma);";
    try std.testing.expect(calculateVisibleLength(char_line) > 100);
    try std.testing.expect(stringContentStats(char_line).code > 100);
    try std.testing.expectEqual(@as(usize, 0), stringContentStats(char_line).content);
    // Char literals count as ordinary code, whatever their form
    try std.testing.expectEqual(
        @as(usize, 14),
        stringContentStats("const q = '\"';").code,
    );
    try std.testing.expectEqual(
        @as(usize, 16),
        stringContentStats("const nl = '\\n';").code,
    );
    try std.testing.expectEqual(
        @as(usize, 16),
        stringContentStats("const sq = '\\'';").code,
    );
    // Apostrophe-like ' not part of a char literal is ordinary code too
    try std.testing.expectEqual(
        @as(usize, 13),
        stringContentStats("// don't stop").code,
    );
    // Real string overage adjacent to a char literal stays exempt: the
    // 100-column content dominates 26 columns of code.
    const mixed = "    if (c == '\"') return \"" ++ "x" ** 100 ++ "\";";
    try std.testing.expect(calculateVisibleLength(mixed) > 100);
    const mixed_stats = stringContentStats(mixed);
    try std.testing.expectEqual(@as(usize, 26), mixed_stats.code);
    try std.testing.expectEqual(@as(usize, 100), mixed_stats.content);
}

// ============================================================================
// EPH-I1062: generated-file banner detection
// ============================================================================

test "generated-file banner silences ZA701 and ZA703 (EPH-I1062)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Real corpus shape (sig v2/lib/crypto/ed25519/wycheproof.zig): a
    // `//! DO NOT EDIT` head banner over generated content. The camelCase
    // const (should be snake_case) and the over-long line both fire on
    // hand-written code; the banner marks the file generated and silences
    // both. The twin without a banner is the control.
    const generated =
        "//! DO NOT EDIT! File generated by `gen_tool.zig`.\n" ++
        "const badName = 1;\n" ++
        "const line = " ++ ("x" ** 130) ++ ";\n";
    const hand_written =
        "const badName = 1;\n" ++
        "const line = " ++ ("x" ** 130) ++ ";\n";

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();
    const gen = try createTestFileAnalysis(allocator, "gen.zig", generated);
    try graph.files.put(gen.path, gen);
    const plain = try createTestFileAnalysis(allocator, "plain.zig", hand_written);
    try graph.files.put(plain.path, plain);

    var style = try analyzeStyle(allocator, &graph, .{});
    defer deinitIssues(&style, allocator);
    var naming = try analyzeNaming(allocator, &graph, .title_case);
    defer deinitIssues(&naming, allocator);

    for (style.items) |issue| {
        // Multi-file fixture: per-file assertion legitimate (EPH-I1147).
        try std.testing.expect(!mem.eql(u8, issue.file, "gen.zig"));
    }
    for (naming.items) |issue| {
        try std.testing.expect(!mem.eql(u8, issue.file, "gen.zig"));
    }
    // The control still fires both rules: the banner, not the content,
    // drives the silence.
    var control_style: usize = 0;
    var control_naming: usize = 0;
    for (style.items) |issue| {
        if (mem.eql(u8, issue.file, "plain.zig")) control_style += 1;
    }
    for (naming.items) |issue| {
        if (mem.eql(u8, issue.file, "plain.zig")) control_naming += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), control_style);
    try std.testing.expectEqual(@as(usize, 1), control_naming);
}

test "banner tokens past the head do not mark a file generated (EPH-I1062)" {
    // The detector reads only the first two non-empty lines: a prose
    // mention mid-file (zls src/tools/config_gen.zig documents generating
    // src/Config.zig far below the head) must not mark hand-written code
    // generated.
    const content =
        "const std = @import(\"std\");\n" ++
        "pub fn main() void {}\n" ++
        "// NOTE: the deploy step regenerates the config below. DO NOT EDIT it by hand.\n" ++
        "const BadName = 1;\n";
    try std.testing.expect(!detectGeneratedHeader(content));

    // A string literal on line one carrying a token is data, not a banner.
    const string_head =
        "const s = \"DO NOT EDIT\";\n" ++
        "const BadName = 1;\n";
    try std.testing.expect(!detectGeneratedHeader(string_head));

    // Each canonical token does fire inside a head comment.
    try std.testing.expect(
        detectGeneratedHeader("// Code generated by protoc-gen-zig\nconst x = 1;\n"),
    );
    try std.testing.expect(
        detectGeneratedHeader("//" ++ "AUTO-" ++ "GENERATED FILE. DO NOT MODIFY.\nconst x = 1;\n"),
    );
    try std.testing.expect(detectGeneratedHeader("//! DO NOT EDIT\nconst x = 1;\n"));
    // Beyond the second non-empty line the token is inert.
    try std.testing.expect(!detectGeneratedHeader(
        "// header\n// second\n//! DO NOT EDIT\nconst x = 1;\n",
    ));
}

test "ZA701 exempts lines over-length solely due to string literals (EPH-I0267)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    var graph = ImportGraph.init(allocator, &diag);
    defer graph.deinit();

    const long_literal = "    \"" ++ "x" ** 113 ++ "\",";
    const short_string_long_code = "x" ** 50 ++ " \"ab\" " ++ "y" ** 60;
    const pure_code = "x" ** 120;
    const char_literal_line =
        "if (c == '\"') return self.handleTheStringLiteral" ++
        "WithAnExcessivelyLongFunctionName(alpha, beta, gamma);";
    const mixed_char_and_string = "    if (c == '\"') return \"" ++ "x" ** 100 ++ "\";";
    const code = long_literal ++ "\n" ++
        short_string_long_code ++ "\n" ++
        pure_code ++ "\n" ++
        char_literal_line ++ "\n" ++
        mixed_char_and_string ++ "\n";

    const analysis = try createTestFileAnalysis(allocator, "test_long_lines.zig", code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "test_long_lines.zig"), {});

    var issues = try analyzeStyle(allocator, &graph, .{});
    defer deinitIssues(&issues, allocator);

    var flagged_lines: usize = 0;
    for (issues.items) |issue| {
        if (mem.eql(u8, issue.rule, RULE_LINE_TOO_LONG)) {
            // Lines 1 (unbreakable literal) and 5 (literal + char literal) are
            // exempt; lines 2, 3, and 4 (char literal masking) are not.
            try std.testing.expect(issue.line != 1 and issue.line != 5);
            flagged_lines += 1;
        }
    }
    try std.testing.expectEqual(@as(usize, 3), flagged_lines);
}

