test "hasBreakGuardOnPriorLines stops at a canonical while opener (EPH-I0498)" {
    // A guard above a loop opener does not dominate an access inside
    // its body: the loop's later iterations reach the access without
    // re-passing the guard. Pre-fix the opener's own `{` folded the
    // depth negative and the walk ran past it to the stale guard.
    const lines = [_][]const u8{
        "fn f(x: usize, y: usize) void {",
        "    var m = x;",
        "    while (y > 0) {",
        "        if (m == 0) break;",
        "        while (y > 1) {",
        "            m -= 1;",
        "        }",
        "        y -= 1;",
        "    }",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&lines, 5, "m", null));
    // The same-loop guard still dominates: the scan finds it before
    // reaching the opener.
    const same_lines = [_][]const u8{
        "fn f(x: usize) void {",
        "    var m = x;",
        "    while (m > 0) {",
        "        if (m == 0) break;",
        "        m -= 1;",
        "    }",
        "}",
    };
    try std.testing.expect(hasBreakGuardOnPriorLines(&same_lines, 4, "m", null));
}

test "isLoopOpenerLine matches labeled and inline loop openers (EPH-I0937)" {
    // The labeled (`label: while`) and inline (`inline for`/`inline
    // while`) forms must stop the guard walks like plain openers do.
    // Pre-fix the boundary matcher recognized only plain keyword line
    // starts and the walks ran past these openers to a stale guard.
    try std.testing.expect(isLoopOpenerLine("outer: while (y > 0) {"));
    try std.testing.expect(isLoopOpenerLine("outer: for (items) |it| {"));
    try std.testing.expect(isLoopOpenerLine("inline while (y > 0) {"));
    try std.testing.expect(isLoopOpenerLine("inline for (items) |it| {"));
    try std.testing.expect(!isLoopOpenerLine("if (y > 0) {"));
    try std.testing.expect(!isLoopOpenerLine("const pat = \"while (\";"));
}

test "hasBreakGuardOnPriorLines stops at labeled and inline loop openers (EPH-I0937)" {
    // A guard above a labeled or inline loop opener does not dominate an
    // access inside its body — the EPH-I0498 dominance rule. Pre-fix the
    // boundary matcher missed these opener forms and the walk found the
    // stale guard.
    const labeled = [_][]const u8{
        "fn f(x: usize, y: usize) void {",
        "    var m = x;",
        "    if (m == 0) return;",
        "    outer: while (y > 0) {",
        "        m -= 1;",
        "    }",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&labeled, 4, "m", null));
    const inline_while = [_][]const u8{
        "fn f(x: usize, y: usize) void {",
        "    var m = x;",
        "    if (m == 0) return;",
        "    inline while (y > 0) {",
        "        m -= 1;",
        "    }",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&inline_while, 4, "m", null));
    const inline_for = [_][]const u8{
        "fn f(x: usize, items: []const usize) void {",
        "    var m = x;",
        "    if (m == 0) return;",
        "    inline for (items) |it| {",
        "        m -= 1;",
        "    }",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&inline_for, 4, "m", null));
}

test "findEnclosingLoop recognizes labeled and inline openers (EPH-I0937)" {
    // The init-witness scan end (initReassignScanEnd) needs the labeled
    // and inline forms as enclosing loops. Pre-fix findEnclosingLoop
    // returned null for both shapes.
    const labeled = [_][]const u8{
        "fn f(arr: []usize, n: usize) usize {",
        "    _ = n;",
        "    var i = 5;",
        "    outer: while (n > 0) {",
        "        n -= 1;",
        "        _ = arr[i - 1];",
        "    }",
        "    return arr[0];",
        "}",
    };
    const found = findEnclosingLoop(&labeled, 5).?;
    try std.testing.expectEqual(@as(usize, 3), found.header);
    try std.testing.expectEqual(@as(usize, 6), found.close);
    const inline_loop = [_][]const u8{
        "fn f(arr: []usize, n: usize) usize {",
        "    _ = n;",
        "    var i = 5;",
        "    inline while (n > 0) {",
        "        n -= 1;",
        "        _ = arr[i - 1];",
        "    }",
        "    return arr[0];",
        "}",
    };
    const found_inline = findEnclosingLoop(&inline_loop, 5).?;
    try std.testing.expectEqual(@as(usize, 3), found_inline.header);
    try std.testing.expectEqual(@as(usize, 6), found_inline.close);
}

test "opensConditionalBody recognizes labeled and inline loop openers (EPH-I0950)" {
    // The CFG guard collection gates on isGuardEstablishingLine ->
    // opensConditionalBody. Pre-fix isLoopStart matched only plain
    // `while `/`for ` prefixes, so a `label: while (x > 0)` or
    // `inline while (x > 0)` header never established a guard and the
    // body decrement fired. A labeled block (`label: {`) and a labeled
    // if stay non-loop openers.
    try std.testing.expect(opensConditionalBody("outer: while (x > 0) {"));
    try std.testing.expect(opensConditionalBody("outer: for (items) |it| {"));
    try std.testing.expect(opensConditionalBody("inline while (x > 0) {"));
    try std.testing.expect(opensConditionalBody("inline for (items) |it| {"));
    try std.testing.expect(opensConditionalBody("while (x > 0) {"));
    try std.testing.expect(!opensConditionalBody("outer: if (x > 0) {"));
    try std.testing.expect(!opensConditionalBody("outer: {"));
    try std.testing.expect(!opensConditionalBody("const pat = \"while (\";"));
    try std.testing.expect(isGuardEstablishingLine("outer: while (x > 0) {"));
    try std.testing.expect(isGuardEstablishingLine("inline while (x > 0) {"));
}

test "isFuncBoundary ignores fn ( inside a string literal (EPH-I0949)" {
    // The backward walks stop at function boundaries; a string like
    // `const pat = "fn (";` between the loop header and the candidate
    // must not read as a nested signature. Pre-fix the raw byte match
    // returned true and findEnclosingLoop/hasInitWitness stopped short
    // of the real guard or loop opener.
    try std.testing.expect(isFuncBoundary("fn f(x: usize) usize {"));
    try std.testing.expect(isFuncBoundary("pub fn f(x: usize) usize {"));
    try std.testing.expect(!isFuncBoundary("const pat = \"fn (\";"));
    try std.testing.expect(!isFuncBoundary("const s = \"fn\";"));
    try std.testing.expect(!isFuncBoundary("my_fn (x);"));
}

test "trackBraceDepthBackward ignores braces inside literals (EPH-I0949)" {
    // A one-line string `const s = "}";` between the candidate and the
    // loop header must not add a phantom close. Pre-fix the raw byte
    // count read the `}` as a close, the header's `{` never drove the
    // depth negative, and findEnclosingLoop returned null.
    try std.testing.expectEqual(@as(i32, 0), trackBraceDepthBackward("const s = \"}\";", 0));
    try std.testing.expectEqual(@as(i32, -1), trackBraceDepthBackward("while (n > 1) {", 0));
    try std.testing.expectEqual(@as(i32, 1), trackBraceDepthBackward("}", 0));
}

test "findEnclosingLoop ignores fn ( and } inside string literals (EPH-I0949)" {
    // Both string shapes between the loop header and the candidate must
    // keep the walk's decision correct: the loop is still the candidate's
    // enclosing loop. Pre-fix the `fn (` line stopped the walk (false
    // function boundary) and the `}` line faked an open block, so the
    // loop was never found and the init witness never applied.
    const lines = [_][]const u8{
        "fn f(arr: []usize, n: usize) usize {",
        "    var i = 5;",
        "    while (n > 1) {",
        "        const pat = \"fn (\";",
        "        const s = \"}\";",
        "        _ = arr[i - 1];",
        "    }",
        "    return arr[0];",
        "}",
    };
    const found = findEnclosingLoop(&lines, 5).?;
    try std.testing.expectEqual(@as(usize, 2), found.header);
    try std.testing.expectEqual(@as(usize, 6), found.close);
}

test "hasBreakGuardOnPriorLines skips a closed loop body (EPH-I0936)" {
    // A break guard inside a loop body exits the loop; it does not
    // dominate an access after the loop — the loop can exit via its
    // condition with the var still zero. Pre-fix the walk crossed the
    // closing `}` and found the depth-1 guard.
    const lines = [_][]const u8{
        "fn f(x: usize, y: usize) usize {",
        "    var m = x;",
        "    while (y > 0) {",
        "        if (m == 0) break;",
        "        y -= 1;",
        "    }",
        "    m -= 1;",
        "    return m;",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&lines, 6, "m", null));
}

test "hasBreakGuardOnPriorLines skips an Allman closed loop body (EPH-I0951)" {
    // The Allman open is the bare `{` line under the `while` header, so
    // crossClosedBlock does not see a loop opener at the depth-returning
    // line. Pre-fix the body was judged and the in-body break guard
    // suppressed the after-loop decrement; the header check passes the
    // body like the K&R shape.
    const lines = [_][]const u8{
        "fn f(x: usize, y: usize) usize {",
        "    var m = x;",
        "    while (y > 0)",
        "    {",
        "        if (m == 0) break;",
        "        y -= 1;",
        "    }",
        "    m -= 1;",
        "    return m;",
        "}",
    };
    try std.testing.expect(!hasBreakGuardOnPriorLines(&lines, 7, "m", null));
    // A same-line brace-less loop body is not Allman: the `{` block
    // below the header is a separate block, and its guard still
    // dominates the candidate.
    const brace_less = [_][]const u8{
        "fn g(x: usize, y: usize) usize {",
        "    var m = x;",
        "    while (y > 0) y -= 1;",
        "    {",
        "        if (m == 0) return 0;",
        "    }",
        "    m -= 1;",
        "    return m;",
        "}",
    };
    try std.testing.expect(hasBreakGuardOnPriorLines(&brace_less, 6, "m", null));
}

test "hasBreakGuardOnPriorLines stops at a brace-less loop opener whose body is the candidate (EPH-I0936 review F1)" {
    // The inner loop's brace-less next-line body IS the candidate line:
    // loopBodyCloseLine returns that line, and the pre-fix `>` check
    // passed the opener (close == current_idx is not "beyond"), so the
    // stale break guard above the inner loop silenced the in-body
    // decrement. The close must stop the walk on the candidate's own
    // line (`>=`).
    const lines = [_][]const u8{
        "fn f(x: usize, y: usize) usize {",
        "    var m = x;",
        "    while (y > 0) {",
        "        if (m == 0) break;",
