        \\    var i = 9;
        \\    var j = 0;
        \\    while (j < 10) : (j += 1) {
        \\        arr[i - 1_0];
        \\    }
        \\    return i;
        \\}
        \\fn idx_zero_ok(arr: []usize, n: usize) usize {
        \\    if (n == 0) return 0;
        \\    return arr[n - 0x1];
        \\}
        \\fn idx_zero_fire(arr: []usize, n: usize) usize {
        \\    if (n == 0) return 0;
        \\    return arr[n - 0x2];
        \\}
