        \\fn kr_multi_foreign(x: usize, q: usize) usize {
        \\    var m = x;
        \\    if (q > 1 and
        \\        m > 3) {
        \\        m -= 2;
        \\    }
        \\    return m;
        \\}
        \\fn kr_multi_foreign_nn(x: usize, q: usize) usize {
        \\    var m = x;
        \\    var n = 1;
        \\    if (q > 1 and
        \\        m > 3) {
        \\        m -= n;
        \\    }
        \\    return m;
        \\}
        \\fn kr_multi_foreign_big(x: usize, q: usize) usize {
        \\    var m = x;
        \\    if (q > 1 and
