        \\    var m = x;
        \\    if (q > 1) {
        \\        return arr[0];
        \\    }
        \\    else
        \\    {
        \\        return arr[m - 2];
        \\    }
        \\    return 0;
        \\}
        \\fn allman_chain_oneline(x: usize, q: usize, arr: []u8) usize {
        \\    var m = x;
        \\    if (q > 1) {
        \\        return arr[0];
        \\    } else if (m > 3)
