        \\    return 0;
        \\}
        \\fn allman_chain_midline_big(x: usize, q: usize, arr: []u8) usize {
        \\    var m = x;
        \\    if (q > 1) { return 0; } else if (q > 1 and
        \\        m > 3)
        \\    {
        \\        return arr[m - 5];
        \\    }
        \\    return 0;
        \\}
