test "guardOnLineAt judges each arm's decrement against its own region (EPH-I1022)" {
    const chain = "if (m > 1) { return 0; } else if (m > 3) { m -= 2; } else { m -= 1; }";
    const mid_col = findDecrementOpAt(chain, 0).?;
    const final_col = findDecrementOpAt(chain, mid_col + 2).?;
    // The middle arm's own condition proves m >= 4, which covers 2; an
    // amount past the arm's bound still fires. The final else arm's
    // region is the naked body — the negated antecedents never cover
    // the arm below, so its candidate fires. A foreign var never
    // covers any candidate (EPH-I1022).
    try std.testing.expect(guardOnLineAt(chain, mid_col, "m", 2));
    try std.testing.expect(!guardOnLineAt(chain, mid_col, "m", 5));
    try std.testing.expect(!guardOnLineAt(chain, final_col, "m", 1));
    try std.testing.expect(!guardOnLineAt(chain, mid_col, "q", 2));
}

test "ZA901: one-line multi-arm chain reports the unguarded later-arm decrement (EPH-I1022)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The middle arm's `m -= 2` is covered by its own arm's bound and
    // stays silent; the final else arm runs at m <= 3, so its `m -= 1`
    // underflows at m == 0 and fires. Pre-fix only the first decrement
    // was judged, the covered middle arm silenced the whole line, and
    // the final arm's decrement was never reported (FN, EPH-I1022).
    // The single-decrement controls keep their verdicts.
    const content =
        \\fn chain_multi(x: usize) usize {
        \\    var m = x;
        \\    if (m > 1) { return 0; } else if (m > 3) { m -= 2; } else { m -= 1; }
        \\    return m;
        \\}
        \\fn chain_multi2(x: usize) usize {
        \\    var m = x;
        \\    if (m > 3) { m -= 2; } else { m -= 1; }
        \\    return m;
        \\}
        \\fn single_guarded(x: usize) usize {
        \\    var m = x;
        \\    if (m > 0) { m -= 1; }
        \\    return m;
        \\}
        \\fn single_unguarded(x: usize) usize {
        \\    var m = x;
        \\    m -= 1;
        \\    return m;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_za901_chain_multi.zig", content);
    defer run.deinit(allocator);
    try std.testing.expectEqual(
        @as(usize, 3),
        countRuleIssues(
            run.issues.items,
            "test_za901_chain_multi.zig",
            RULE_DECREMENT_WITHOUT_CHECK,
        ),
    );
}

test "ZA901: joined multi-line == conjuncts stay conservative (EPH-I1015)" {
    // The doc-arm pin for the conservative-fire class at
    // guardSpanCoversAmount: an or-tail with an unparseable conjunct
    // (`m == 1`) proves no bound, so the joined multi-line or-tail
    // fires even for `m -= 1`; the and-tail keeps the parseable arm's
    // bound (m >= 2 covers 1 but not 5). The single-line twins fire
    // the same way — the join is a consistent extension of the model
    // limitation (reviewer probes r5/r8).
    const ort = [_][]const u8{
        "fn f(x: usize) usize {",
        "    var m = x;",
        "    if (m > 1 or",
        "        m == 1) {",
        "        m -= 1;",
        "    }",
    };
    try std.testing.expect(!guardLineCoversAmountWithJoin(
        .{ .lines = &ort, .line_idx = 2, .first_offset = 0 },
        "m",
        1,
    ));
    const andt = [_][]const u8{
        "fn f(x: usize) usize {",
        "    var m = x;",
        "    if (m > 1 and",
        "        m == 1) {",
        "        m -= 5;",
        "    }",
    };
    try std.testing.expect(guardLineCoversAmountWithJoin(
        .{ .lines = &andt, .line_idx = 2, .first_offset = 0 },
        "m",
        1,
    ));
    try std.testing.expect(!guardLineCoversAmountWithJoin(
        .{ .lines = &andt, .line_idx = 2, .first_offset = 0 },
        "m",
        5,
    ));
}

test "ZA903: mismatched-array .len guard does not suppress the candidate (EPH-I0496)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // F14: `if (a.len == 0) return;` silenced `b[i - 1]` — the .len
    // guard was never tied to the indexed array. The candidate base is
    // bound first; a guard on `a` cannot cover `b`, so ZA903 fires. The
    // 30-line walk only engages past its window start (the
    // function-boundary stop — pre-existing window shape), so the guard
    // sits 30 lines above the candidate.
    const content =
        \\fn len_mismatch(a: []u8, b: []u8, i: usize) u8 {
        \\    if (a.len == 0) return 0;
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    sink(a);
        \\    return b[i - 1];
        \\}
        \\fn sink(v: u8) void {
        \\    _ = v;
        \\}
    ;
    var run = try runCFGMemoryTest(&diag, allocator, "test_za903_len_mismatch.zig", content);
    defer run.deinit(allocator);
    try std.testing.expect(countRuleIssues(
        run.issues.items,
        "test_za903_len_mismatch.zig",
        RULE_INDEX_ARITHMETIC,
    ) == 1);
}

test "ZA903: matching-array .len guard stays silent (EPH-I0496)" {
    var diag = testDiagCtx();
