        \\    s.a = 1;
        \\    use(s);
        \\}
        \\fn use(v: u32) void {
        \\    _ = v;
        \\}
    ;
    const analysis = try createTestFileAnalysis(allocator, "za204_str_brace.zig", content);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, "za204_str_brace.zig"), {});

