test "trackBraceNesting ignores braces inside char literals" {
    // `'{'` / `'}'` are char data, not scope delimiters — counting them as
    // braces corrupts max_nest and can delay fn-end detection past the real
    // closing brace.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("if (c == '{') x += 1;", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
    try std.testing.expect(!trackBraceNesting("if (c == '}') x -= 1;", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
    try std.testing.expect(trackBraceNesting("}", &state));
}

test "trackBraceNesting handles escaped-quote char literals" {
    // `'\''` — the escaped quote is content (odd backslash run), only the
    // last quote is the delimiter; the `{` after the literal must count.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("if (c == '\\'') {", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    // `'\\'` — backslash literal (even backslash run before the delimiter);
    // the `{` after the literal must count.
    try std.testing.expect(!trackBraceNesting("if (c == '\\\\') {", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting treats quote after even backslash run as delimiter" {
    // `"\\"` closes the string — the backslash run before the quote is even,
    // so the quote is a delimiter and the `}` after the string is code that
    // ends the function scope.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(trackBraceNesting("const s = \"\\\\\"; }", &state));
}

test "trackBraceNesting keeps escaped quote as string data" {
    // `"\""` — the middle quote has an odd backslash run before it, so it is
    // escaped data; the string ends at the last quote and the trailing `}`
    // still closes the scope.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(trackBraceNesting("const s = \"\\\"\"; }", &state));
}

test "trackBraceNesting counts the brace on a string-literal arrow line" {
    // EPH-I0221: `"=>"` is string data, not a switch prong. The raw
    // substring check poisoned is_switch, so the real block brace was
    // skipped and the block's closing `}` ended the fn early.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    const line = "if (mem.eql(u8, tok, \"=>\")) {";
    try std.testing.expect(!trackBraceNesting(line, &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting counts the brace on a comment arrow line" {
    // EPH-I0221: `=>` inside a `//` comment is not code — the masked check
    // must leave is_switch false so the block brace still counts.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("if (x) { // =>", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting still skips the brace of a real switch prong" {
    // A code-level `=>` keeps the prong heuristic: `1 => {` opens a prong
    // block, not a new nesting level.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("1 => {", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
}

// ============================================================================
// Prong-brace open/close pairing (EPH-I0451, EPH-I0133)
// ============================================================================

test "trackBraceNesting skips both braces of a multi-line block prong (EPH-I0451)" {
    // The prong open adds no depth, so its matching close must not remove
    // one. Pre-fix the close decremented and ended fns mid-switch.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting(".catch_block => {", &state));
    const body = "try self.cfg.addEdge(a, b, .sequential);";
    try std.testing.expect(!trackBraceNesting(body, &state));
    try std.testing.expect(!trackBraceNesting("},", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting nets zero on a same-line empty prong (EPH-I0133)" {
    // `else => {},` skips its open, so the close skips too. Pre-fix the
    // close dropped nest and ended the fn at the switch (EPH-I0133).
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("else => {},", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting nets zero on a same-line struct-literal prong (EPH-I0451)" {
    // The first `{` is the struct literal's open; its close pairs with the
    // skip, leaving the enclosing switch depth untouched.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => .{ .x = 1 },", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting counts inner braces on a block prong line (EPH-I0451)" {
    // The if's braces are inner: they count and balance, and neither close
    // consumes the prong's skip. Pre-fix the fn ended on this line.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => { if (x) { foo(); } },", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting nets zero on a one-line switch expression (EPH-I0451)" {
    // The prong heuristic skips the switch body open, so the body close on
    // the same line must not drop the fn depth either.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    const line = "const f = switch (v) { .a => 1, .b => 2 };";
    try std.testing.expect(!trackBraceNesting(line, &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
}

test "trackBraceNesting counts a second open brace on a prong line (EPH-I0451)" {
    // Only the line's first `{` is the prong's. A second open is an inner
    // brace and counts, so its close balances and the prong close still
    // pairs with the skip. The pre-I0451 skip swallowed every brace on the
    // arrow line; the pin uses a real control brace (a literal second open
    // skips as data since EPH-I0811, pinned separately).
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => { if (x) {", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expect(!trackBraceNesting("} },", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting skips a literal second open on a prong line (EPH-I0811)" {
    // `1 => { x = .{` — the prong's brace skips, the literal's braces skip
    // as data; neither counts. Pre-fix the literal counted (nest peaked 3).
    var state = ComplexityState{ .in_fn = true, .nest = 2, .max_nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => { x = .{", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 2), state.max_nest);
    try std.testing.expect(!trackBraceNesting("} },", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting pairs nested skipped prongs at one depth (EPH-I0451)" {
    // A one-line switch expression inside a block prong leaves two skipped
    // opens pending at the same depth. The per-depth count pairs each close
    // with its own skip; a single-bit marker would lose the outer one and
    // end the fn at the switch close.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => {", &state));
    const inner = "const x = switch (b) { .y => 1 };";
    try std.testing.expect(!trackBraceNesting(inner, &state));
    try std.testing.expect(!trackBraceNesting("},", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
}

test "trackBraceNesting pairs 300 nested switch-expression prongs (EPH-I0451)" {
    // A switch expression in prong position records its skipped open at the
    // current depth, which never advances across the nested opens, so 300
    // nested `N => switch (v) {` lines drive the per-depth count to 300.
    // The u8 counter overflowed at 256 (review fixture
    // .tmp/review-i0451/overflow.zig); the usize count pairs every close.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    var buf: [32]u8 = undefined;
    var i: usize = 0;
    while (i < 300) : (i += 1) {
        const line = try std.fmt.bufPrint(&buf, "{d} => switch (v) {{", .{i});
        try std.testing.expect(!trackBraceNesting(line, &state));
        try std.testing.expectEqual(@as(usize, 2), state.nest);
    }
    try std.testing.expectEqual(@as(usize, 300), state.prong_opens[2]);
    i = 0;
    while (i < 300) : (i += 1) {
        try std.testing.expect(!trackBraceNesting("},", &state));
    }
    // Every skip is consumed: the counter is empty and the next close
    // decrements the depth again.
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 0), state.prong_opens[2]);
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
}

// ============================================================================
// Struct/array literal braces are data, not nesting (EPH-I0811, EPH-I0026)
// ============================================================================

test "trackBraceNesting skips same-line struct-literal braces (EPH-I0811)" {
    // `.{` opens an anonymous struct/array literal — data, not a
    // control-flow block. Its braces must not raise the depth or the peak.
    // Pre-fix the open counted and max_nest peaked one level higher.
    var state = ComplexityState{ .in_fn = true, .nest = 3, .max_nest = 3 };
    try std.testing.expect(!trackBraceNesting("const s: Spec = .{ .a = 1, .b = 2 };", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expectEqual(@as(usize, 3), state.max_nest);
}

test "trackBraceNesting skips multiline literal braces across lines (EPH-I0811)" {
    // The literal's `{` opens on its own line and its close arrives lines
    // later (a literal table inside fn>loop>if). Both braces stay invisible
    // to nesting: the enclosing depth never moves and the fn never ends at
    // the literal's close.
    var state = ComplexityState{ .in_fn = true, .nest = 3, .max_nest = 3 };
    try std.testing.expect(!trackBraceNesting("t = .{", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expectEqual(@as(usize, 3), state.max_nest);
    try std.testing.expect(!trackBraceNesting(".a = 1,", &state));
    try std.testing.expect(!trackBraceNesting(".b = 2,", &state));
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
}

test "trackBraceNesting counts a control brace next to a literal (EPH-I0811)" {
    // `if (x) { const t = .{` — the if opens a real level, the literal does
    // not. Pre-fix both counted and max_nest peaked at 4.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting("if (x) { const t = .{", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expectEqual(@as(usize, 3), state.max_nest);
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
}

test "trackBraceNesting keeps a prong-block literal at the prong depth (EPH-I0811)" {
    // A literal table built inside a prong block: pre-fix the literal open
    // counted and peaked at the prong depth plus one.
    var state = ComplexityState{ .in_fn = true, .nest = 2, .max_nest = 2 };
    try std.testing.expect(!trackBraceNesting("1 => {", &state));
    try std.testing.expect(!trackBraceNesting("const t = .{", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expect(!trackBraceNesting("},", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 2), state.max_nest);
}

test "trackBraceNesting attributes an arrow-line literal to the literal mask (EPH-I0811)" {
    // d4 shape: the literal's `{` is the first brace on the arrow line.
    // Pre-fix the prong skip swallowed it (recorded as a prong open); the
    // literal mask claims it, so the prong counter never moves and the
    // literal pairs its own close.
    var state = ComplexityState{ .in_fn = true, .nest = 2 };
    try std.testing.expect(!trackBraceNesting(".y => |n| total += take(.{", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 0), state.prong_opens[2]);
    try std.testing.expectEqual(@as(usize, 1), state.lit_opens[2]);
    try std.testing.expect(!trackBraceNesting("}),", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 0), state.lit_opens[2]);
}

test "trackBraceNesting ends a fn at the body close, not a default-value close (EPH-I0811)" {
    // A `.{}` default in the signature is data: pre-fix its close dropped
    // nest to 0 mid-line and reported the fn ended before the body brace.
    var state = ComplexityState{ .in_fn = true, .nest = 0 };
    try std.testing.expect(!trackBraceNesting("fn foo(x: S = .{ .a = 1 }) void {", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
    try std.testing.expectEqual(@as(usize, 1), state.max_nest);
    try std.testing.expect(!trackBraceNesting("sink();", &state));
    try std.testing.expect(trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 0), state.nest);
}

test "trackBraceNesting still counts real if/while nesting (EPH-I0811)" {
    // The literal mask must not blunt real control flow: while>if>if from
    // the fn body still peaks at 4.
    var state = ComplexityState{ .in_fn = true, .nest = 1 };
    try std.testing.expect(!trackBraceNesting("while (c) {", &state));
    try std.testing.expect(!trackBraceNesting("if (a) {", &state));
    try std.testing.expect(!trackBraceNesting("if (b) {", &state));
    try std.testing.expectEqual(@as(usize, 4), state.max_nest);
    try std.testing.expect(!trackBraceNesting("sink();", &state));
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
}

test "trackBraceNesting counts a literal at depth >= 32 (EPH-I0811)" {
    // The per-depth skip arrays hold 32 slots. A literal opened at depth
    // >= 32 cannot be recorded, so it counts and balances by its real
    // close (mirrors the prong guard, EPH-I0451).
    var state = ComplexityState{ .in_fn = true, .nest = 33, .max_nest = 33 };
    try std.testing.expect(!trackBraceNesting("const t = .{", &state));
    try std.testing.expectEqual(@as(usize, 34), state.nest);
    try std.testing.expectEqual(@as(usize, 34), state.max_nest);
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expectEqual(@as(usize, 33), state.nest);
}

test "trackBraceNesting skips a literal brace after a spaced dot (EPH-I0819)" {
    // `. {` — the space between the dot and the brace is token whitespace,
    // not a break in the `.{` literal token (zig ast-check). Pre-fix the
    // space landed in scan.prev_c, so the open counted and max_nest peaked
    // one higher.
    var state = ComplexityState{ .in_fn = true, .nest = 3, .max_nest = 3 };
    try std.testing.expect(!trackBraceNesting("const t = . { .x = 1 };", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expectEqual(@as(usize, 3), state.max_nest);
}

test "trackBraceNesting skips a literal whose brace opens on the next line (EPH-I0819)" {
    // `const t = .` + `{` — the dot at end of line survives the per-line
    // BraceScan reset via state.prev_code_char (zig ast-check). Pre-fix the
    // fresh-line scan saw no dot and counted the open.
    var state = ComplexityState{ .in_fn = true, .nest = 3, .max_nest = 3 };
    try std.testing.expect(!trackBraceNesting("const t = .", &state));
    try std.testing.expect(!trackBraceNesting("{", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
    try std.testing.expectEqual(@as(usize, 3), state.max_nest);
    try std.testing.expect(!trackBraceNesting(".x = 1,", &state));
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expectEqual(@as(usize, 3), state.nest);
}

test "trackBraceNesting keeps later real blocks counted after a dot-masked literal (EPH-I0819)" {
    // The cross-line carry must not desync later statements (the I0818
    // class): once the literal closes, a real if-block still opens, counts,
    // and closes at the same depth. A stale dot would mask the if's brace,
    // and that block's close would end the fn early.
    var state = ComplexityState{ .in_fn = true, .nest = 1, .max_nest = 1 };
    try std.testing.expect(!trackBraceNesting("const t = .", &state));
    try std.testing.expect(!trackBraceNesting("{", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
    try std.testing.expectEqual(@as(usize, 1), state.max_nest);
    try std.testing.expect(!trackBraceNesting(".x = 1,", &state));
    try std.testing.expect(!trackBraceNesting("};", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
    try std.testing.expect(!trackBraceNesting("if (c) {", &state));
    try std.testing.expectEqual(@as(usize, 2), state.nest);
    try std.testing.expectEqual(@as(usize, 2), state.max_nest);
    try std.testing.expect(!trackBraceNesting("sink();", &state));
    try std.testing.expect(!trackBraceNesting("}", &state));
    try std.testing.expectEqual(@as(usize, 1), state.nest);
}

/// Run analyzeComplexity on one in-memory file and assert exactly one
/// ZA301 fires, carrying the expected measured fn length in its message.
/// The exact count pins "the fn measured its full body", not just "some
/// finding fired" (EPH-I0451).
/// One function-line measurement case: the file name, its source, and
/// the expected measured line count.
const FnLinesCase = struct {
    file: []const u8,
    code: []const u8,
    expect_lines: usize,
};

fn expectMeasuredFnLines(diag: *DiagCtx, allocator: Allocator, case: FnLinesCase) !void {
    const file = case.file;
    const code = case.code;
    const expect_lines = case.expect_lines;
    var graph = ImportGraph.init(allocator, diag);
    defer graph.deinit();

    const analysis = try createTestFileAnalysis(allocator, file, code);
    try graph.files.put(analysis.path, analysis);
    try graph.reachable.put(try allocator.dupe(u8, file), {});

    var issues = try analyzeComplexity(allocator, &graph, .{});
    defer deinitIssues(&issues, allocator);

    try std.testing.expectEqual(
        @as(usize, 1),
        countRuleIssues(issues.items, file, RULE_FUNC_TOO_LONG),
    );
    const needle = try std.fmt.allocPrint(allocator, "has {d} lines", .{expect_lines});
    defer allocator.free(needle);
    for (issues.items) |issue| {
        if (!mem.eql(u8, issue.rule, RULE_FUNC_TOO_LONG)) continue;
        if (mem.indexOf(u8, issue.message, needle) != null) return;
    }
    return error.TestUnexpectedResult;
}

test "ZA301: two block prongs plus a trailing statement measure the full fn (EPH-I0451)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // The true body is 56 lines. Pre-fix the second prong's close ended
    // the measurement at fn line 14 and the trailing lines went unmeasured.
    // The pad joins with an explicit newline: a multiline literal's last
    // line carries no trailing one, so the first pad line would glue onto
    // the switch close and the count drops by one.
    const code =
        \\fn two_prongs(v: u8) void {
        \\    switch (v) {
        \\        1 => {
        \\            sink(1);
        \\            sink(1);
        \\            sink(1);
        \\            sink(1);
        \\        },
        \\        2 => {
        \\            sink(2);
        \\            sink(2);
        \\            sink(2);
        \\            sink(2);
        \\        },
        \\        else => {},
        \\    }
    ++ "\n" ++ "    sink(9);\n" ** 39 ++
        \\}
        \\fn sink(v: u8) void {
        \\    _ = v;
        \\}
    ;
    try expectMeasuredFnLines(&diag, allocator, .{
        .file = "prongs.zig",
        .code = code,
        .expect_lines = 56,
    });
}

