        \\}
        \\fn checkFx(x: u32) !void {
        \\    try fxAssert(x);
        \\}
        \\fn checkBudget(x: u32) !void {
        \\    try assert_invariants(x);
        \\}
        \\test "transfer" {
        \\    var bus = Bus{};
