    defer run.deinit(allocator);

    try expectZC104Counts(run.issues.items, 1, 0);
}

test "transfer predicate: control-flow keywords are not call evidence (EPH-I0402)" {
    // Direct pins on the live helper chain. Pre-fix every keyword arm
    // returned true: the ident walk cannot tell `if (` from `foo(`.
    try std.testing.expect(!isFunctionArgTransfer("if (name == x) {", "name"));
    try std.testing.expect(!isFunctionArgTransfer("while (name != null) {", "name"));
    try std.testing.expect(!isFunctionArgTransfer("for (name) |n| {", "name"));
    try std.testing.expect(!isFunctionArgTransfer("switch (name) {", "name"));
    try std.testing.expect(!isFunctionArgTransfer("return (name);", "name"));
    try std.testing.expect(!isFunctionArgTransfer("probe() catch (name);", "name"));
    try std.testing.expect(!isFunctionArgTransfer("maybe orelse (name);", "name"));
    // F7 pin: a tab between the call name and '(' still reads as a call.
    // Pre-fix the space-only skip missed the tab and the transfer vanished.
    try std.testing.expect(isFunctionArgTransfer("pool.put\t(name);", "name"));
    // Positive control: a real call argument still transfers.
    try std.testing.expect(isFunctionArgTransfer("pool.put(name);", "name"));
}

test "transfer predicate: expression keywords are not call evidence (EPH-I1100)" {
    // Regression pins on the live helper chain. Pre-fix the and/or/fn/
    // comptime/nosuspend arms returned true: the ident walk read the
    // keyword before the '(' as a call name and the parenthesized
    // expression counted as ownership-transfer evidence (the I0402
    // residual). A keyword-guarded operand keeps ownership with the
    // current function; a fn-pointer parameter list never names a call.
    try std.testing.expect(!isFunctionArgTransfer("if (a and (name)) return;", "name"));
    try std.testing.expect(!isFunctionArgTransfer("if (a or (name)) return;", "name"));
    try std.testing.expect(
        !isFunctionArgTransfer("var cb: *const fn (name) void = undefined;", "name"),
    );
    try std.testing.expect(!isFunctionArgTransfer("const x = comptime (name);", "name"));
    try std.testing.expect(!isFunctionArgTransfer("const x = nosuspend (name);", "name"));
    // Positive controls: a real call argument still transfers.
    try std.testing.expect(isFunctionArgTransfer("pool.put(name);", "name"));
    try std.testing.expect(isFunctionArgTransfer("return take(name);", "name"));
}

test "ZC101: wrapped signature with .{} default opens the record at the real body (EPH-I0447)" {
    var diag = testDiagCtx();
    var gpa = std.heap.DebugAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("gpa leaked");
    const allocator = gpa.allocator();

    // Regression pin (fails pre-fix): the `.{}` default on the wrapped
    // param line used to open a phantom record that closed on the same
    // line, so the real body never opened and the lock calls vanished
    // (0 issues instead of the baseline 1). Signature parens now bound
    // the pending window, mirroring the ZT101 updatePending rule.
    const content =
        \\fn work() void {}
        \\fn setup(
        \\    items: []const u8 = &.{ .x = 1 },
        \\) void {
        \\    mu.lock();
        \\    _ = mu;
        \\    mu.unlock();
        \\}
    ;
    var run = try runConcurrencyCheck(&diag, allocator, "zc101_wrapped.zig", content);
    defer run.deinit(allocator);

    try expectZC101Counts(run.issues.items, 0, 1);
}

