// ZA210 Tests — no-catch-return (catch |e| return e is a verbose try)
// ============================================================================

test "ZA210: catch |err| return err fires when enabled" {
    const issue = checkNoCatchReturn("foo() catch |err| return err;", "t.zig", 1);
    try std.testing.expect(issue != null);
    try std.testing.expectEqualStrings(RULE_NO_CATCH_RETURN, issue.?.rule);
    try std.testing.expect(issue.?.severity == .note);
}

test "ZA210: catch |err| return different is silent" {
    const issue = checkNoCatchReturn("foo() catch |err| return other;", "t.zig", 1);
    try std.testing.expect(issue == null);
}

test "ZA210: catch block with logging stays silent (v2 boundary, EPH-I0039)" {
    // Logging between catch and return is real work — the block form fires
    // only when the body's sole statement is the payload return.
    const issue = checkNoCatchReturn("foo() catch |err| { log(err); return err; }", "t.zig", 1);
    try std.testing.expect(issue == null);
}

test "ZA210: catch block whose sole statement is the payload return fires (EPH-I0039)" {
    const issue = checkNoCatchReturn("foo() catch |err| { return err; }", "t.zig", 1);
    try std.testing.expect(issue != null);
    try std.testing.expectEqualStrings(RULE_NO_CATCH_RETURN, issue.?.rule);
    try std.testing.expect(issue.?.severity == .note);
}

test "ZA210: catch block with a second statement stays silent (EPH-I0039)" {
    // A second statement after the payload return is real work.
    try std.testing.expect(
        checkNoCatchReturn("foo() catch |err| { return err; return; }", "t.zig", 1) == null,
    );
    // A different return payload is not the verbose-try shape.
    try std.testing.expect(
        checkNoCatchReturn("foo() catch |err| { return other; }", "t.zig", 1) == null,
    );
}

test "ZA210: try form produces no issue" {
    const issue = checkNoCatchReturn("try foo();", "t.zig", 1);
    try std.testing.expect(issue == null);
}

test "ZA210: catch payload in a trailing comment is prose (EPH-I0417)" {
    // The payload exists only in comment prose — the verbose-try note
    // must stay silent (pre-fix the raw scan fired on the comment).
    try std.testing.expect(checkNoCatchReturn("x(); // catch |e| return e;", "t.zig", 1) == null);
    // A string payload followed by a real catch still fires.
    const mixed = "f(\"catch |\"); foo() catch |err| return err;";
    try std.testing.expect(checkNoCatchReturn(mixed, "t.zig", 1) != null);
}

