test "config parse recovers after a missing colon (EPH-I0514)" {
    // "fail_on" has no separator: the pre-fix colon scan ran to the
    // first `:` ANYWHERE, which belonged to "thresholds" — the whole
    // thresholds object then parsed as fail_on's value and was skipped.
    // The scan now stops at the next string opener, so the malformed
    // pair is skipped and the thresholds object parses in place.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try parseConfigJson(
        &diag,
        allocator,
        "{\"fail_on\" \"never\", \"thresholds\": {\"max_lines\": 9}}",
        &cfg,
    );
    try std.testing.expectEqual(@as(usize, 9), cfg.thresholds.max_function_lines);
}

test "thresholds parse recovers after a missing colon inside the object (EPH-I0514)" {
    // "max_cognitive" has no separator: the pre-fix scan bound it to
    // the colon after "max_branches", so max_cognitive took 7 and
    // max_branches kept its default. The scan now stops at the stray
    // string, the pair is skipped, and max_branches parses in place.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try parseConfigJson(
        &diag,
        allocator,
        "{\"thresholds\": {\"max_lines\": 9, \"max_cognitive\" \"15\", \"max_branches\": 7}}",
        &cfg,
    );
    try std.testing.expectEqual(@as(usize, 9), cfg.thresholds.max_function_lines);
    try std.testing.expectEqual(@as(usize, 15), cfg.thresholds.max_cognitive);
    try std.testing.expectEqual(@as(usize, 7), cfg.thresholds.max_branches);
}

test "config pair with a cross-line colon keeps its default (EPH-I1049)" {
    // B13-6 line-oriented grammar pin: findKeySeparator stops at the
    // first newline, so a separator colon on a later line cannot bind.
    // The pair is skipped — the key keeps its default, no warning — and
    // a clean pair that parsed before it stays intact. Pinned so a
    // future cross-line scan cannot silently change the grammar guarantee.
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try parseConfigJson(
        &diag,
        allocator,
        "{\"thresholds\": {\"max_lines\": 42}, \"path_dir\"\n: \"lib\"}",
        &cfg,
    );
    // "lib" never bound: the skipped path_dir leaves the default "src".
    try std.testing.expectEqualStrings("src", cfg.path);
    try std.testing.expectEqual(@as(usize, 42), cfg.thresholds.max_function_lines);
}

test "config pair with a comment-spanning colon keeps its default (EPH-I1049)" {
    // Same skip class as the cross-line colon: the separator scan stops
    // at the `//` opener, so a colon after a comment cannot bind. The
    // pair is skipped and the default stays (no warning fires).
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    try parseConfigJson(
        &diag,
        allocator,
        "{\"thresholds\": {\"max_lines\": 42}, \"path_dir\" // note\n: \"lib\"}",
        &cfg,
    );
    try std.testing.expectEqualStrings("src", cfg.path);
    try std.testing.expectEqual(@as(usize, 42), cfg.thresholds.max_function_lines);
}

