test "isWithinScanRoot fails closed on a null root with one warning (EPH-I0172)" {
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    var g = ImportGraph.init(std.testing.allocator, &diag);
    defer g.deinit();
    // RED4-7: the pre-fix null root read as contained. Fail closed and
    // say so once; the second miss stays silent (once-guard).
    try std.testing.expect(!g.isWithinScanRoot("/tmp/repo/x.zig"));
    try std.testing.expect(mem.indexOf(u8, capture.slice(), "scan root not set") != null);
    const after_first = capture.len;
    try std.testing.expect(!g.isWithinScanRoot("/tmp/repo/y.zig"));
    try std.testing.expectEqual(after_first, capture.len);
}

test "unresolvedScanRootExit text mode sanitizes the cannot-resolve line (EPH-I1137)" {
    // RED4-7 regression pin (EPH-I0172 abort half): the scan path may
    // carry scanned-tree bytes, so the raw-path render must never return.
    // The sanitized line prints once and the call returns the failure
    // exit code — the I0728 one-line guarantee replaces the pre-fix
    // propagate-and-reprint shape with a silent code.
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    const allocator = std.testing.allocator;
    const code = try unresolvedScanRootExit(
        &diag,
        allocator,
        "/tmp/scan\x1b[2mroot",
        error.FileNotFound,
    );
    try std.testing.expectEqual(@as(u8, 1), code);
    try std.testing.expect(std.mem.indexOfScalar(u8, capture.slice(), 0x1b) == null);
    try std.testing.expectEqualStrings(
        "error: cannot resolve scan path '/tmp/scan?[2mroot': FileNotFound\n",
        capture.slice(),
    );
    // Text mode never stashes: the message went to the sink.
    try std.testing.expectEqual(@as(usize, 0), diag.last_muted_diag_len);
}

test "unresolvedScanRootExit JSON mode aborts with the sanitized message (EPH-I1137)" {
    // The same pin in the machine shape: the stream latch mutes the bare
    // line and stashes the sanitized text, the call returns the error
    // code, and the abort object that rides the code carries the stashed
    // message as its message member.
    var diag = testDiagCtx();
    diag.json_stream = true;
    const allocator = std.testing.allocator;
    const code = try unresolvedScanRootExit(
        &diag,
        allocator,
        "/tmp/scan\x1b[2mroot",
        error.FileNotFound,
    );
    try std.testing.expectEqual(@as(u8, 1), code);
    const stashed = diag.last_muted_diag[0..diag.last_muted_diag_len];
    try std.testing.expect(std.mem.indexOfScalar(u8, stashed, 0x1b) == null);
    var obj = types.OutBuf{ .allocator = allocator };
    defer obj.deinit();
    try buildAbortJson(&obj, allocator, error.ScanRootUnresolved, stashed);
    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, obj.buf.items, .{});
    defer parsed.deinit();
    try std.testing.expectEqualStrings(
        "ScanRootUnresolved",
        parsed.value.object.get("error").?.string,
    );
    try std.testing.expectEqualStrings(
        "error: cannot resolve scan path '/tmp/scan?[2mroot': FileNotFound\n",
        parsed.value.object.get("message").?.string,
    );
}

test "errorExitCode keeps one error line per failure (EPH-I0728)" {
    // Text mode: a failure whose diagnostic already printed returns the
    // silent exit code instead of propagating (the runtime would add a
    // second bare "error: X" line). An error no diagnostic named still
    // propagates so the runtime line stays the only signal. JSON mode
    // keeps the abort-object guarantee.
    var quiet = testDiagCtx();
    try std.testing.expectError(
        error.OutOfMemory,
        errorExitCode(&quiet, std.testing.allocator, error.OutOfMemory, ""),
    );

    var spoken = testDiagCtx();
    spoken.error_diag_printed = true;
    try std.testing.expectEqual(
        @as(u8, 1),
        try errorExitCode(&spoken, std.testing.allocator, error.FileNotFound, ""),
    );

    var json = testDiagCtx();
    json.json_stream = true;
    try std.testing.expectEqual(
        @as(u8, 1),
        try errorExitCode(&json, std.testing.allocator, error.FileNotFound, ""),
    );
}

test "cliDiag latches the printed-error flag on the error keyword (EPH-I0728)" {
    // The latch keys on the comptime "error: " prefix: a warning or note
    // never arms it, and the armed latch drives the one-line exit
    // guarantee in errorExitCode.
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    cliDiag(&diag, "note: something\n", .{});
    cliDiag(&diag, "warning: something\n", .{});
    try std.testing.expect(!diag.error_diag_printed);
    cliDiag(&diag, "error: something failed\n", .{});
    try std.testing.expect(diag.error_diag_printed);
}

test "scanDirectory failure routes through the diagnostics channel (EPH-I0213)" {
    const allocator = std.testing.allocator;
    // Text mode: the error propagates and the line prints.
    var text_diag = testDiagCtx();
    {
        var graph = ImportGraph.init(allocator, &text_diag);
        defer graph.deinit();
        try std.testing.expectError(
            error.FileNotFound,
            graph.scanDirectory("/nonexistent/ephor-jq-scan"),
        );
    }
    // JSON mode: the same propagation, the bare line gated off the
    // machine stream (reportScanOpenError routes through cliDiag).
    var json_diag = testDiagCtx();
    json_diag.json_stream = true;
    {
        var graph = ImportGraph.init(allocator, &json_diag);
        defer graph.deinit();
        try std.testing.expectError(
            error.FileNotFound,
            graph.scanDirectory("/nonexistent/ephor-jq-scan"),
        );
    }
}

test "findPathDirInContent skips comments and rejects unsafe candidates (RED4-2)" {
    // A hostile comment line must not win over a later real match.
    const hostile_comment =
        \\// root_source_file = "/abs/evil.zig"
        \\const std = @import("std");
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(hostile_comment).?);

    // A ".." candidate in a comment line is skipped like any comment.
    const parent_comment =
        \\// root_source_file = "../outside/x.zig"
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("lib/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("lib", findPathDirInContent(parent_comment).?);

    // An absolute candidate in real code is rejected, not selected.
    const absolute_code =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = "/opt/evil/main.zig" });
        \\    const lib = b.addStaticLibrary(.{ .root_source_file = b.path("src/lib.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(absolute_code).?);

    // A ".." candidate in real code is rejected by the component check.
    const parent_code =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("../outside/main.zig") });
        \\    const lib = b.addStaticLibrary(.{ .root_source_file = b.path("src/lib.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(parent_code).?);
}

test "findPathDirInContent masks trailing comments and string bodies (EPH-I0144)" {
    // A payload in a trailing comment on a code line must not win over a
    // later real match.
    const trailing_comment =
        \\const b = std.Build; // root_source_file = "evil/x.zig"
        \\pub fn build(b2: *std.Build) void {
        \\    const exe = b2.addExecutable(.{ .root_source_file = b2.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(trailing_comment).?);

    // A real match keeps its value when a comment follows it.
    const real_then_comment =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/m.zig") }); // note
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(real_then_comment).?);

    // A `//` inside a string literal is not a comment. The quote-aware
    // strip must keep such a line whole.
    const url_own_line =
        \\const url = "https://example.com";
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(url_own_line).?);

    // Same-line form: a naive strip would cut at the string's `//` and
    // hide the pattern after it.
    const url_same_line =
        \\pub fn build(b: *std.Build) void {
        \\    _ = "https://x"; exe.root_src = "src/m.zig";
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(url_same_line).?);

    // A payload on a line-initial `\\` multiline-string body line stays
    // skipped. The existing skip already covers this shape; this pins it.
    const string_body =
        \\pub fn build(b: *std.Build) void {
        \\    const note =
        \\        \\root_source_file = "evil/x.zig"
        \\    ;
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(string_body).?);

    // A multiline string that opens MID-LINE swallows the rest of its
    // line as string data (EPH-I0283): the quoted path inside the tail
    // must not win over a later real match. stripLineComment cuts at the
    // opener (EPH-I0671); this pins the exact shape the I0283 probe
    // used to steer.
    const mid_line_tail =
        \\pub fn build(b: *std.Build) void {
        \\    const note = \\\\root_source_file = "evil/x.zig"
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("src/main.zig") });
        \\}
    ;
    try std.testing.expectEqualStrings("src", findPathDirInContent(mid_line_tail).?);
}

test "findPathDirInContent returns null when nothing matches" {
    // No pattern at all: the caller owns the not-detected report.
    try std.testing.expect(findPathDirInContent("pub fn build(b: *std.Build) void {}\n") == null);
    // Every candidate rejected (absolute, ".."): null, never a value.
    const rejected =
        \\pub fn build(b: *std.Build) void {
        \\    const exe = b.addExecutable(.{ .root_source_file = b.path("../evil/main.zig") });
        \\}
    ;
    try std.testing.expect(findPathDirInContent(rejected) == null);
}

test "detectPathDirFromBuildZig reads the project build.zig through diag" {
    var diag = testDiagCtx();
    const allocator = std.testing.allocator;
    // Self-analysis pin (EPH-I0575): the repo's own build.zig declares
    // root_source_file = "src/main.zig". A foreign cwd has no build.zig,
    // so the test skips there: a tmpDir stand-in would pin the stand-in,
    // not the repo layout.
    Fs.cwd(std.testing.io).access("build.zig", .{}) catch return error.SkipZigTest;
