test "CLI --help after a command selects the help command (EPH-I0727)" {
    // The flag parser used to reject --help after a command as unknown.
    // The documented single-help decision: the request selects the help
    // command, which prints the top-level help. After `--` the token
    // stays a scan path.
    var diag = testDiagCtx();
    diag.cli_diagnostics_enabled = false;
    const allocator = std.testing.allocator;

    const help_flags = [_][]const u8{ "--help", "-h" };
    for (help_flags) |flag| {
        var cfg = testConfig();
        defer cfg.deinit(allocator);
        cfg.command = .memory;
        var cli_entries = false;
        var cli_path = false;
        var no_more_flags = false;
        const cli_ctx: CliParseCtx = .{
            .diag = &diag,
            .allocator = allocator,
            .cfg = &cfg,
            .cli_entries = &cli_entries,
            .cli_path = &cli_path,
            .no_more_flags = &no_more_flags,
        };
        try parseCliArg(cli_ctx, flag);
        try std.testing.expectEqual(Command.help, cfg.command);
    }

    // After the `--` marker the same token is a scan path, not a command.
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    var cli_entries = false;
    var cli_path = false;
    var no_more_flags = true;
    const cli_ctx: CliParseCtx = .{
        .diag = &diag,
        .allocator = allocator,
        .cfg = &cfg,
        .cli_entries = &cli_entries,
        .cli_path = &cli_path,
        .no_more_flags = &no_more_flags,
    };
    try parseCliArg(cli_ctx, "--help");
    try std.testing.expectEqual(Command.check, cfg.command);
    try std.testing.expect(mem.eql(u8, cfg.path, "--help"));
    try std.testing.expect(cfg.path_owned);
}

test "CLI a second positional path is a hard usage error (EPH-I0807)" {
    var diag = testDiagCtx();
    // Regression: every positional went through setOwnedPath, so the last
    // path silently overwrote the earlier ones — `check swD/ two-arms/`
    // scanned only two-arms/ and exited 0 while swD/ carried a ZA106.
    // Both orders must fail closed: one run scans one path.
    diag.cli_diagnostics_enabled = false;
    const allocator = std.testing.allocator;
    const orders = [_][2][]const u8{
        .{ "swD/", "two-arms/" },
        .{ "two-arms/", "swD/" },
    };
    for (orders) |order| {
        var cfg = testConfig();
        defer cfg.deinit(allocator);
        var cli_entries = false;
        var cli_path = false;
        var no_more_flags = false;
        const cli_ctx: CliParseCtx = .{
            .diag = &diag,
            .allocator = allocator,
            .cfg = &cfg,
            .cli_entries = &cli_entries,
            .cli_path = &cli_path,
            .no_more_flags = &no_more_flags,
        };
        try parseCliArg(cli_ctx, order[0]);
        try std.testing.expectError(
            error.ExtraScanPath,
            parseCliArg(cli_ctx, order[1]),
        );
        // The rejected path must not clobber the accepted one.
        try std.testing.expectEqualStrings(order[0], cfg.path);
    }
}

test "JSON parse abort stashes the diagnostic and renders the error object (EPH-I1067)" {
    var diag = testDiagCtx();
    // The flag-first shape: --format=json arms the machine latch before
    // the flag loop, so the ExtraScanPath diagnostic mutes on the stream
    // and stashes for the abort object instead.
    diag.json_stream = true;
    const allocator = std.testing.allocator;
    var cfg = testConfig();
    defer cfg.deinit(allocator);
    var cli_entries = false;
    var cli_path = false;
    var no_more_flags = false;
    const cli_ctx: CliParseCtx = .{
        .diag = &diag,
        .allocator = allocator,
        .cfg = &cfg,
        .cli_entries = &cli_entries,
        .cli_path = &cli_path,
        .no_more_flags = &no_more_flags,
    };
    try parseCliArg(cli_ctx, "check");
    try std.testing.expectError(error.ExtraScanPath, parseCliArg(cli_ctx, "src/"));
    const stashed = diag.last_muted_diag[0..diag.last_muted_diag_len];
    try std.testing.expectEqualStrings(
        "error: unexpected extra scan path 'src/': one path per run (see ephor --help)\n",
        stashed,
    );
    var obj = types.OutBuf{ .allocator = allocator };
    defer obj.deinit();
    try buildAbortJson(&obj, allocator, error.ExtraScanPath, stashed);
    const parsed = try std.json.parseFromSlice(std.json.Value, allocator, obj.buf.items, .{});
    defer parsed.deinit();
    try std.testing.expectEqualStrings(
        "ExtraScanPath",
        parsed.value.object.get("error").?.string,
    );
    try std.testing.expectEqualStrings(
        "error: unexpected extra scan path 'src/': one path per run (see ephor --help)\n",
        parsed.value.object.get("message").?.string,
    );
}

test "JSON abort object renders name-only when no diagnostic is stashed (EPH-I1067)" {
    // A mid-run handler failure has no stashed diagnostic: the object
