test "jsonRejectedCommandName rejects only the human-output commands in JSON mode (EPH-I1070, EPH-I1097)" {
    var cfg = testConfig();
    defer cfg.deinit(std.testing.allocator);
    cfg.format = .json;
    cfg.command = .upgrade;
    try std.testing.expectEqualStrings("upgrade", jsonRejectedCommandName(&cfg).?);
    cfg.command = .install;
    try std.testing.expectEqualStrings("install", jsonRejectedCommandName(&cfg).?);
    cfg.command = .init;
    try std.testing.expectEqualStrings("init", jsonRejectedCommandName(&cfg).?);
    // help/version print the human banner on the armed stream (EPH-I1097):
    // same class, same rejection.
    cfg.command = .help;
    try std.testing.expectEqualStrings("help", jsonRejectedCommandName(&cfg).?);
    cfg.command = .version;
    try std.testing.expectEqualStrings("version", jsonRejectedCommandName(&cfg).?);
    // Analysis commands keep their machine output.
    cfg.command = .check;
    try std.testing.expect(jsonRejectedCommandName(&cfg) == null);
    cfg.command = .stats;
    try std.testing.expect(jsonRejectedCommandName(&cfg) == null);
    cfg.command = .runtime;
    try std.testing.expect(jsonRejectedCommandName(&cfg) == null);
    // Text mode never rejects: the interactive commands keep their
    // human progress output.
    cfg.format = .text;
    cfg.command = .upgrade;
    try std.testing.expect(jsonRejectedCommandName(&cfg) == null);
}

test "parseArgs parses a command word after flags (EPH-I1098)" {
    if (@import("builtin").os.tag == .windows or @import("builtin").os.tag == .wasi)
        return error.SkipZigTest;
    // Flag-first ordering: upgrade is a command, not a scan path. The
    // rejection fires with the stashed diagnostic, exactly like the
    // command-first spelling (EPH-I1070).
    {
        var diag = testDiagCtx();
        const args = std.process.Args{ .vector = &.{
            @as([*:0]const u8, "ephor"),
            @as([*:0]const u8, "--format=json"),
            @as([*:0]const u8, "upgrade"),
        } };
        try std.testing.expectError(
            error.JsonCommandUnsupported,
            parseArgs(&diag, std.testing.allocator, args),
        );
        try std.testing.expect(diag.json_stream);
        const stashed = diag.last_muted_diag[0..diag.last_muted_diag_len];
        try std.testing.expect(std.mem.indexOf(
            u8,
            stashed,
            "upgrade command has no machine-readable output",
        ) != null);
    }
    // Text mode: the flag-first command parses and the run proceeds with
    // the command's own path rules. The mute keeps the success-path
    // config/detection notes off the green-run log.
    {
        var diag = testDiagCtx();
        diag.cli_diagnostics_enabled = false;
        const args = std.process.Args{ .vector = &.{
            @as([*:0]const u8, "ephor"),
            @as([*:0]const u8, "--verbose"),
            @as([*:0]const u8, "stats"),
        } };
        var cfg = try parseArgs(&diag, std.testing.allocator, args);
        defer cfg.deinit(std.testing.allocator);
        try std.testing.expectEqual(Command.stats, cfg.command);
    }
    // A consumed command word does not claim the next bare word: the
    // command-first position still wins over the path latch.
    {
        var diag = testDiagCtx();
        diag.cli_diagnostics_enabled = false;
        const args = std.process.Args{ .vector = &.{
            @as([*:0]const u8, "ephor"),
            @as([*:0]const u8, "check"),
            @as([*:0]const u8, "upgrade"),
        } };
        var cfg = try parseArgs(&diag, std.testing.allocator, args);
        defer cfg.deinit(std.testing.allocator);
        try std.testing.expectEqual(Command.check, cfg.command);
        try std.testing.expectEqualStrings("upgrade", cfg.path);
    }
    // `--` ends the command window: the word stays a scan path.
    {
        var diag = testDiagCtx();
        diag.cli_diagnostics_enabled = false;
        const args = std.process.Args{ .vector = &.{
            @as([*:0]const u8, "ephor"),
            @as([*:0]const u8, "--"),
            @as([*:0]const u8, "upgrade"),
        } };
        var cfg = try parseArgs(&diag, std.testing.allocator, args);
        defer cfg.deinit(std.testing.allocator);
        try std.testing.expectEqual(Command.check, cfg.command);
        try std.testing.expectEqualStrings("upgrade", cfg.path);
    }
    // A latched scan path ends the command window: the command word is
    // an extra scan path, the hard usage error (EPH-I0807).
    {
        var diag = testDiagCtx();
        diag.cli_diagnostics_enabled = false;
        const args = std.process.Args{ .vector = &.{
            @as([*:0]const u8, "ephor"),
            @as([*:0]const u8, "src/"),
            @as([*:0]const u8, "upgrade"),
        } };
        try std.testing.expectError(
            error.ExtraScanPath,
            parseArgs(&diag, std.testing.allocator, args),
        );
    }
}

test "pre-scan scans the raw POSIX argv vector infallibly (EPH-I1056)" {
    // POSIX argv is a borrowed [*:0] slice: the scan allocates nothing,
    // so no OOM can fire before the stream gate arms. The latch must
    // arm on either token spelling and stay clear otherwise.
    if (@import("builtin").os.tag == .windows or @import("builtin").os.tag == .wasi)
        return error.SkipZigTest;
    const args = std.process.Args{ .vector = &.{
        @as([*:0]const u8, "ephor"),
        @as([*:0]const u8, "check"),
        @as([*:0]const u8, "src/"),
        @as([*:0]const u8, "--format=json"),
    } };
    try std.testing.expect(scanArgsForJson(args));
    const args_short = std.process.Args{ .vector = &.{
        @as([*:0]const u8, "ephor"),
        @as([*:0]const u8, "-f=json"),
    } };
    try std.testing.expect(scanArgsForJson(args_short));
    const args_text = std.process.Args{ .vector = &.{
        @as([*:0]const u8, "ephor"),
        @as([*:0]const u8, "--format=text"),
    } };
    try std.testing.expect(!scanArgsForJson(args_text));
}

test "pre-scan honors the -- end-of-flags marker (EPH-I1057)" {
    // `--` ends flag parsing in the real parser, so a --format=json
    // behind it is a positional path and must not arm the latch. Both
    // directions: the marker before the flag stays clear, and a flag
    // already consumed before the marker still arms it.
    if (@import("builtin").os.tag == .windows or @import("builtin").os.tag == .wasi)
        return error.SkipZigTest;
    const marker_before = std.process.Args{ .vector = &.{
        @as([*:0]const u8, "ephor"),
        @as([*:0]const u8, "check"),
        @as([*:0]const u8, "--"),
        @as([*:0]const u8, "--format=json"),
    } };
    try std.testing.expect(!scanArgsForJson(marker_before));
    const marker_after = std.process.Args{ .vector = &.{
        @as([*:0]const u8, "ephor"),
        @as([*:0]const u8, "--format=json"),
        @as([*:0]const u8, "--"),
        @as([*:0]const u8, "src/"),
    } };
    try std.testing.expect(scanArgsForJson(marker_after));
}

test "WTF-16 pre-scan finds the JSON tokens in a raw command line (EPH-I1056)" {
    // Windows argv is one WTF-16 command-line string: quoted tokens and
    // repeated spaces included. The logic is pure u16, so the darwin
    // test run covers the Windows branch.
    const plain = comptime utf16Literal("ephor --format=json src");
    try std.testing.expect(scanWtf16ArgsForJson(&plain));
    const quoted = comptime utf16Literal("ephor check \"--format=json\" src");
    try std.testing.expect(scanWtf16ArgsForJson(&quoted));
    // The Windows CRT strips unescaped quotes anywhere inside a word, so
    // the value-quoted spellings parse to the bare tokens (EPH-I1056).
    const value_quoted = comptime utf16Literal("ephor --format=\"json\" src");
    try std.testing.expect(scanWtf16ArgsForJson(&value_quoted));
    const short_value_quoted = comptime utf16Literal("ephor -f=\"json\"");
    try std.testing.expect(scanWtf16ArgsForJson(&short_value_quoted));
    const mid_word_quoted = comptime utf16Literal("ephor --form\"at=json");
    try std.testing.expect(scanWtf16ArgsForJson(&mid_word_quoted));
    const short = comptime utf16Literal("ephor -f=json");
    try std.testing.expect(scanWtf16ArgsForJson(&short));
    const doubled_spaces = comptime utf16Literal("ephor  --format=json");
    try std.testing.expect(scanWtf16ArgsForJson(&doubled_spaces));
    const text = comptime utf16Literal("ephor --format=text --format=jsonx");
    try std.testing.expect(!scanWtf16ArgsForJson(&text));
    // Word-boundary semantics: a larger token that merely contains the
    // flag must not false-arm the latch.
    const embedded = comptime utf16Literal("ephor x--format=json");
    try std.testing.expect(!scanWtf16ArgsForJson(&embedded));
}

test "WTF-16 pre-scan honors -- and quote grouping (EPH-I1057)" {
    // `--` before the flag: the token is a positional path, no arm.
    const marker_before = comptime utf16Literal("ephor check -- --format=json");
    try std.testing.expect(!scanWtf16ArgsForJson(&marker_before));
    // `--` after the flag: the flag already armed the latch.
    const marker_after = comptime utf16Literal("ephor --format=json -- src");
    try std.testing.expect(scanWtf16ArgsForJson(&marker_after));
    // Fold-in: the quoted phrase is one CRT argv word, so the token
    // inside it never arms the latch alone (the real parser sees the
    // whole phrase as one positional path).
    const quoted_phrase = comptime utf16Literal("ephor check \"docs --format=json dir\"");
    try std.testing.expect(!scanWtf16ArgsForJson(&quoted_phrase));
    // A backslash-escaped quote is a literal quote (the CRT rule): it
    // does not toggle the quote state, and the token stays inside one
    // quoted word.
    const escaped_quote = comptime utf16Literal("ephor \"a\\\"b --format=json\"");
    try std.testing.expect(!scanWtf16ArgsForJson(&escaped_quote));
}

test "Windows argv pre-scan skips argv[0] under the std exe-name rules (EPH-I1069)" {
    // The flag loop never parses the first word as a flag: parseArgs
    // skips argv[0], and std.process.Args.Windows yields it under its
    // exe-name rules. The pre-scan must match, or a command line whose
    // exe-name word spells a JSON token arms the latch on a run where
    // the flag loop reads no such flag. The logic is pure u16, so the
    // darwin test run covers the Windows branch.
    const bare_flag = comptime utf16Literal("--format=json");
    try std.testing.expect(!scanWtf16ArgsForJson(&bare_flag));
    const bare_short = comptime utf16Literal("-f=json src");
    try std.testing.expect(!scanWtf16ArgsForJson(&bare_short));
    // A `--` exe name is skipped, not honored as the end marker: the
    // flag loop skips argv[0] outright, so the later flag still arms.
    const marker_exe_name = comptime utf16Literal("-- --format=json");
    try std.testing.expect(scanWtf16ArgsForJson(&marker_exe_name));
    // Quoted exe name: the whitespace inside the quotes stays part of
    // argv[0], and the scan continues after the closing quote.
    const quoted_exe_name = comptime utf16Literal("\"my ephor.exe\" --format=json");
    try std.testing.expect(scanWtf16ArgsForJson(&quoted_exe_name));
    // The exe-name rules carry no backslash processing: the quote
    // behind `\` still toggles, so the whole rest of the vector stays
    // inside argv[0] and nothing arms. The CRT rules for later words
    // would read that quote as a literal and find a flag word instead.
    const exe_name_backslash = comptime utf16Literal("ephor\\\" --format=json");
    try std.testing.expect(!scanWtf16ArgsForJson(&exe_name_backslash));
    // An embedded NUL ends the command line the way the std iterator
    // reads it (Args.zig): no word after it is ever parsed, so the
    // flag-looking tail must not arm the latch.
    const embedded_nul = comptime utf16Literal("exe\x00 --format=json");
    try std.testing.expect(!scanWtf16ArgsForJson(&embedded_nul));
}

test "unknown-version warning routes through the sink and off the JSON stream (EPH-I1054)" {
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    compat.markUnknownVersionFallback();
    reportUnknownVersionWarning(&diag);
    // Supported builds carry an empty warning text (the fallback never
    // engages there), so the capture is empty; the sink route itself is
    // pinned by the flag consumption and the JSON gate on every build.
    if (compat.unknown_version_warning_text.len > 0) {
        try std.testing.expect(std.mem.indexOf(u8, capture.slice(), "WARNING: ephor") != null);
    }
    // The flag is consumed exactly once per call.
    try std.testing.expect(!compat.takeUnknownVersionWarning());
    // JSON mode: the machine stream stays pure.
    compat.markUnknownVersionFallback();
    diag.json_stream = true;
    capture = .{};
    diag.diag_sink = capture.sink();
    reportUnknownVersionWarning(&diag);
    try std.testing.expectEqual(@as(usize, 0), capture.len);
    try std.testing.expect(!compat.takeUnknownVersionWarning());
}

test "export notice sanitizes the path and stays off the JSON stream (EPH-I0542)" {
    var diag = testDiagCtx();
    var capture = CaptureSink{};
    diag.diag_sink = capture.sink();
    printExportNotice(&diag, std.testing.allocator, 7, "ok.md");
    try std.testing.expect(
        std.mem.indexOf(u8, capture.slice(), "exported 7 issues to ok.md") != null,
    );
    // Hostile bytes never reach the capture: the path crosses the
    // terminal sanitizer first (EPH-I0147), each replaced by '?'.
    capture = .{};
    diag.diag_sink = capture.sink();
    printExportNotice(&diag, std.testing.allocator, 7, "ev\x1b[2Jil.md");
    try std.testing.expect(std.mem.indexOf(u8, capture.slice(), "\x1b") == null);
    try std.testing.expect(std.mem.indexOf(u8, capture.slice(), "exported 7 issues to") != null);
    // JSON mode: the machine stream stays pure; the export file is the
    // result signal.
    capture = .{};
    diag.diag_sink = capture.sink();
    diag.json_stream = true;
    printExportNotice(&diag, std.testing.allocator, 7, "ok.md");
    try std.testing.expectEqual(@as(usize, 0), capture.len);
}

