    });
    try std.testing.expect(
        patchZonFingerprint(std.testing.io, allocator, tmp.dir, "0xd75e6f2a0588dd40"),
    );
    const after = try tmp.dir.readFileAlloc(
        std.testing.io,
        "build.zig.zon",
